window.CURIO_QUESTIONS = [
  // ---------- HISTORY ----------
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "Which ancient wonder still stands today?", options: ["Hanging Gardens of Babylon", "Great Pyramid of Giza", "Colossus of Rhodes", "Lighthouse of Alexandria"], answer: 1, fact: "The Great Pyramid was the tallest human-made structure on Earth for ~3,800 years.", src: "https://en.wikipedia.org/wiki/Great_Pyramid_of_Giza" },
  { cat: "History", region: "Africa", diff: 2, q: "The Rosetta Stone was key to deciphering which writing?", options: ["Cuneiform", "Egyptian hieroglyphs", "Linear B", "Mayan glyphs"], answer: 1, fact: "It repeats one decree in three scripts, letting scholars crack hieroglyphs in the 1820s.", src: "https://en.wikipedia.org/wiki/Rosetta_Stone" },
  { cat: "History", region: "Europe", diff: 2, kids: true, q: "Which empire built an extensive road network with the phrase 'all roads lead to' its capital?", options: ["Persian", "Roman", "Mongol", "Ottoman"], answer: 1, fact: "Rome's roads totalled over 400,000 km — about 80,500 km of it stone-paved.", src: "https://en.wikipedia.org/wiki/Roman_roads" },
  { cat: "History", region: "Europe", diff: 3, q: "The Treaty of Westphalia (1648) is credited with founding the modern idea of what?", options: ["Free trade", "The sovereign nation-state", "Universal suffrage", "Central banking"], answer: 1, fact: "It ended the Thirty Years' War and set the principle that states control their own internal affairs.", src: "https://en.wikipedia.org/wiki/Peace_of_Westphalia" },
  { cat: "History", region: "Europe", diff: 1, kids: true, q: "Who was the first woman to win a Nobel Prize?", options: ["Rosalind Franklin", "Marie Curie", "Ada Lovelace", "Dorothy Hodgkin"], answer: 1, fact: "Marie Curie later became the only person to win Nobels in two different sciences: physics and chemistry.", src: "https://en.wikipedia.org/wiki/Marie_Curie" },
  { cat: "History", region: "Europe", diff: 2, kids: true, q: "The printing press was popularized in Europe by whom?", options: ["Leonardo da Vinci", "Johannes Gutenberg", "Galileo Galilei", "William Caxton"], answer: 1, fact: "Within 50 years of Gutenberg's 1450s press, Europe printed an estimated 20 million books.", src: "https://en.wikipedia.org/wiki/Printing_press" },
  { cat: "History", region: "Asia", diff: 3, q: "Which civilization invented the concept of zero as a number?", options: ["Ancient Greece", "Ancient India", "Ancient Rome", "Ancient Egypt"], answer: 1, fact: "The symbol and rules for zero were formalized by Indian mathematician Brahmagupta around 628 CE.", src: "https://en.wikipedia.org/wiki/Brahmagupta" },
  { cat: "History", region: "Global", diff: 2, kids: true, q: "The Silk Road primarily connected China with what region?", options: ["The Americas", "The Mediterranean and Europe", "Australia", "Sub-Saharan Africa"], answer: 1, fact: "It traded more than silk — paper, gunpowder and the plague all travelled it too.", src: "https://en.wikipedia.org/wiki/Silk_Road" },
  { cat: "History", region: "Americas", diff: 1, kids: true, q: "Which South American civilization built Machu Picchu high in the Andes?", options: ["Aztec", "Maya", "Inca", "Olmec"], answer: 2, fact: "The Inca fitted Machu Picchu's stones together without any mortar — so precisely that a knife blade can't slip between them.", src: "https://en.wikipedia.org/wiki/Machu_Picchu" },
  { cat: "History", region: "Asia", diff: 1, kids: true, q: "The Great Wall, stretching thousands of kilometres, was built to protect what country?", options: ["China", "Japan", "India", "Mongolia"], answer: 0, fact: "Contrary to the famous myth, astronauts confirm the Great Wall can't be seen from the Moon — no human-made structure can.", src: "https://en.wikipedia.org/wiki/Great_Wall_of_China" },
  { cat: "History", region: "Global", diff: 1, kids: true, q: "Who was the first person to walk on the Moon, in 1969?", options: ["Neil Armstrong", "Buzz Aldrin", "Yuri Gagarin", "Michael Collins"], answer: 0, fact: "The Moon has no wind or rain, so the astronauts' boot prints could stay crisp for millions of years.", src: "https://en.wikipedia.org/wiki/Apollo_11" },
  { cat: "History", region: "Europe", diff: 1, kids: true, q: "The Vikings originally set sail from which region of the world?", options: ["The Mediterranean", "Central Asia", "The British Isles", "Scandinavia"], answer: 3, fact: "Vikings reached North America around 1000 CE — almost 500 years before Columbus — leaving a settlement at L'Anse aux Meadows in Canada.", src: "https://en.wikipedia.org/wiki/L%27Anse_aux_Meadows" },
  { cat: "History", region: "Africa", diff: 2, kids: true, q: "Mansa Musa, often called the richest person in history, ruled which West African empire?", options: ["Ghana Empire", "Songhai Empire", "Mali Empire", "Benin Empire"], answer: 2, fact: "On his 1324 pilgrimage to Mecca, Mansa Musa handed out so much gold in Cairo that its value there reportedly stayed depressed for years.", src: "https://en.wikipedia.org/wiki/Mansa_Musa" },
  { cat: "History", region: "Asia", diff: 2, kids: true, q: "Which city was Japan's imperial capital for over 1,000 years before Tokyo?", options: ["Osaka", "Nara", "Yokohama", "Kyoto"], answer: 3, fact: "Tokyo literally means 'eastern capital' — the city was renamed from Edo when the emperor moved there from Kyoto in 1868.", src: "https://en.wikipedia.org/wiki/Tokyo" },
  { cat: "History", region: "Americas", diff: 2, q: "The ruins of Tenochtitlan, the Aztec capital, lie beneath which modern city?", options: ["Lima", "Mexico City", "Guatemala City", "Bogotá"], answer: 1, fact: "Aztec farmers grew food on chinampas — artificial island gardens so productive that some still operate in Mexico City's Xochimilco district.", src: "https://en.wikipedia.org/wiki/Chinampa" },
  { cat: "History", region: "MiddleEast", diff: 2, q: "Which ancient people of Mesopotamia developed cuneiform, one of the world's earliest writing systems?", options: ["The Babylonians", "The Sumerians", "The Assyrians", "The Phoenicians"], answer: 1, fact: "The earliest cuneiform tablets are mostly receipts and inventories — writing was invented for accounting long before poems or stories.", src: "https://en.wikipedia.org/wiki/Cuneiform" },
  { cat: "History", region: "Asia", diff: 2, q: "Which Ming dynasty admiral led China's giant 'treasure fleets' across the Indian Ocean in the early 1400s?", options: ["Kublai Khan", "Qin Shi Huang", "Confucius", "Zheng He"], answer: 3, fact: "One of Zheng He's voyages brought a giraffe to the Ming court, where it was celebrated as a qilin — a mythical creature of good omen.", src: "https://en.wikipedia.org/wiki/Zheng_He" },
  { cat: "History", region: "Asia", diff: 3, q: "Which empire was the largest contiguous land empire in world history?", options: ["Roman Empire", "British Empire", "Mongol Empire", "Russian Empire"], answer: 2, fact: "The Mongols ran the Yam, a horse-relay postal network whose riders, swapping mounts at stations, could move messages hundreds of kilometres a day.", src: "https://en.wikipedia.org/wiki/Yam_(route)" },
  { cat: "History", region: "Africa", diff: 3, q: "Which African kingdom, centered in modern Ethiopia, grew rich on Red Sea trade and minted its own gold coins?", options: ["Kush", "Aksum", "Great Zimbabwe", "Carthage"], answer: 1, fact: "One of Aksum's giant carved obelisks was taken to Rome on Mussolini's orders in 1937 — Italy finally returned it to Ethiopia in 2005.", src: "https://en.wikipedia.org/wiki/Obelisk_of_Axum" },
  { cat: "History", region: "Europe", diff: 3, q: "How many years did the Hundred Years' War between England and France actually last?", options: ["116 years", "100 years", "99 years", "130 years"], answer: 0, fact: "Despite its name it ran 116 years (1337–1453) — a series of wars between England and France broken up by long truces.", src: "https://en.wikipedia.org/wiki/Hundred_Years%27_War" },


  // ---------- REGIONAL HISTORY (decolonized, region-tagged) ----------
  // -- Africa --
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "The great medieval stone city of Great Zimbabwe gave its name to which modern country?", options: ["Zambia", "Zimbabwe", "Botswana", "Mozambique"], answer: 1, fact: "Its high walls rise from millions of granite blocks stacked without mortar; 'zimbabwe' comes from a Shona phrase meaning 'houses of stone'.", src: "https://en.wikipedia.org/wiki/Great_Zimbabwe" },
  { cat: "History", region: "Africa", diff: 2, q: "The world's largest mud-brick (adobe) building is the Great Mosque of Djenné, found in which West African country?", options: ["Mali", "Morocco", "Sudan", "Nigeria"], answer: 0, fact: "Each year the whole town of Djenné turns out for a festival to replaster the mosque by hand, smoothing its earthen walls after the rains.", src: "https://en.wikipedia.org/wiki/Great_Mosque_of_Djenn%C3%A9" },
  { cat: "History", region: "Africa", diff: 2, kids: true, q: "Which land, home to the ancient Kingdom of Kush, actually contains more ancient pyramids than Egypt?", options: ["Libya", "Sudan", "Ethiopia", "Chad"], answer: 1, fact: "Sudan holds roughly 200 ancient pyramids — more than double Egypt's — steep, sharp-sided royal tombs for the kings and queens of Kush.", src: "https://en.wikipedia.org/wiki/Nubian_pyramids" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "In the Mali and Songhai empires, the city of Timbuktu became famous across the world as a great center of what?", options: ["Diamond mining", "Learning and books", "Shipbuilding", "Silk weaving"], answer: 1, fact: "Timbuktu's Sankore and other schools drew thousands of students; families there still guard hundreds of thousands of old manuscripts.", src: "https://en.wikipedia.org/wiki/Timbuktu" },
  { cat: "History", region: "Africa", diff: 2, q: "The Ghana Empire grew rich by taxing trans-Saharan caravans carrying gold and which other precious commodity?", options: ["Salt", "Tea", "Sugar", "Amber"], answer: 0, fact: "Salt was scarce in West Africa and gold plentiful, so Saharan caravans swapped one for the other — and Ghana's kings taxed every load.", src: "https://en.wikipedia.org/wiki/Ghana_Empire" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "The Swahili coast city-states such as Kilwa and Mombasa grew wealthy trading across which ocean?", options: ["Atlantic Ocean", "Indian Ocean", "Pacific Ocean", "Southern Ocean"], answer: 1, fact: "Seasonal monsoon winds carried Swahili traders to Arabia, India and China; their Bantu language, Kiswahili, absorbed many Arabic words.", src: "https://en.wikipedia.org/wiki/Swahili_coast" },
  { cat: "History", region: "Africa", diff: 2, q: "In 1896 Ethiopia defeated an invading European army at the Battle of Adwa, keeping its independence. Which country did it defeat?", options: ["Britain", "France", "Italy", "Portugal"], answer: 2, fact: "Led by Emperor Menelik II and Empress Taytu Betul, Ethiopia routed the Italian army — a rare defeat of a European power in the Scramble for Africa.", src: "https://en.wikipedia.org/wiki/Battle_of_Adwa", deeper: ["Adwa became a rallying symbol of anti-colonial pride for Africans and people of African descent around the world.", "Italy invaded again in 1935 and occupied Ethiopia, but was driven out by 1941; it never became a lasting colony."] },
  { cat: "History", region: "Africa", diff: 3, q: "The celebrated 'Benin Bronzes' — intricate cast plaques and heads — were made by the Kingdom of Benin, in what is now which country?", options: ["Republic of Benin", "Ghana", "Nigeria", "Cameroon"], answer: 2, fact: "Cast in brass by the lost-wax method, the plaques lined the royal palace, recording the Edo kingdom's history in metal.", src: "https://en.wikipedia.org/wiki/Benin_Bronzes", deeper: ["British forces looted thousands of the works in 1897; many still sit in Western museums, though Nigeria has begun winning some back.", "Their fine casting stunned Europeans and undercut false claims that such sophisticated art could not be African in origin."] },
  { cat: "History", region: "Africa", diff: 3, q: "One of the largest empires in African history, ruled from the city of Gao and expanded by Askia Muhammad, was the:", options: ["Songhai Empire", "Zulu Kingdom", "Kanem-Bornu Empire", "Almoravid dynasty"], answer: 0, fact: "Askia Muhammad split the empire into provinces with governors, judges and an army, controlling Niger River trade and the hub of Timbuktu.", src: "https://en.wikipedia.org/wiki/Songhai_Empire" },
  { cat: "History", region: "Africa", diff: 3, q: "The 11 medieval churches of Lalibela in Ethiopia are famous because they were:", options: ["Built from imported marble", "Carved downward out of solid rock", "Made entirely of gold", "Floated on a lake"], answer: 1, fact: "Carved top-down from single blocks of rock about 800 years ago as a 'New Jerusalem', they are still living churches of Ethiopian Orthodoxy.", src: "https://en.wikipedia.org/wiki/Rock-Hewn_Churches,_Lalibela", deeper: ["Trenches and tunnels link the churches, and features were named for holy sites, recreating Jerusalem in the Ethiopian highlands.", "They were cut with hand tools like hammers and chisels; tradition says the work took about 24 years."] },
  // -- Americas --
  { cat: "History", region: "Americas", diff: 1, kids: true, q: "The Inca kept numbers and records without an alphabet, using bundles of knotted cords called what?", options: ["Quipu", "Papyrus", "Abacus", "Wampum"], answer: 0, fact: "A quipu's knots recorded numbers in base-10 — a knot's position on the cord marked ones, tens or hundreds, read by specialists called quipucamayocs.", src: "https://en.wikipedia.org/wiki/Quipu" },
  { cat: "History", region: "Americas", diff: 1, kids: true, q: "Many Indigenous peoples of the Americas grew three crops together as the 'Three Sisters': maize (corn), squash, and which third plant?", options: ["Beans", "Potatoes", "Rice", "Wheat"], answer: 0, fact: "The trio help one another: bean vines climb the cornstalks, the beans enrich the soil with nitrogen, and broad squash leaves shade out weeds.", src: "https://en.wikipedia.org/wiki/Three_Sisters_(agriculture)" },
  { cat: "History", region: "Americas", diff: 1, kids: true, q: "The Mexica (Aztec) founded Tenochtitlan where legend says they saw an eagle perched on a cactus. That scene is on the flag of which country today?", options: ["Mexico", "Peru", "Guatemala", "Colombia"], answer: 0, fact: "The eagle stands on a nopal cactus growing from a rock in the water — in Mexica tradition, the sign marking where to build Tenochtitlan, today's Mexico City.", src: "https://en.wikipedia.org/wiki/Flag_of_Mexico" },
  { cat: "History", region: "Americas", diff: 2, kids: true, q: "English words like 'canoe,' 'hammock,' and 'hurricane' come from the Taino — the people who first met Europeans in which part of the Americas?", options: ["The Caribbean", "The Andes", "The Great Plains", "Patagonia"], answer: 0, fact: "'Hurricane' comes from Taino juracan, 'canoe' from kanoa, 'hammock' from hamaca and 'barbecue' from barbacoa — all carried into English through Spanish.", src: "https://en.wikipedia.org/wiki/Ta%C3%ADno" },
  { cat: "History", region: "Americas", diff: 2, q: "Which people created the most fully developed writing system of the ancient Americas — a script of hundreds of glyphs?", options: ["The Maya", "The Inca", "The Mexica (Aztec)", "The Haudenosaunee"], answer: 0, fact: "Maya writing was logosyllabic — mixing word-signs and syllable-signs — so a word could be spelled several ways; it was largely deciphered only in the late 1900s.", src: "https://en.wikipedia.org/wiki/Maya_script" },
  { cat: "History", region: "Americas", diff: 2, q: "Cahokia, the largest city in the Americas north of Mexico before European contact, was built by Mississippian people near which modern US city?", options: ["St. Louis", "Chicago", "Atlanta", "Denver"], answer: 0, fact: "Monks Mound, its central earthwork, is the largest north of Mexico; around 1100 CE Cahokia may have held more people than London did at the time.", src: "https://en.wikipedia.org/wiki/Cahokia", deeper: ["Its builders moved an estimated 55 million cubic feet of earth by hand, basket-load by basket-load, to raise about 120 mounds.", "Rows of tall timber posts nicknamed 'Woodhenge' tracked the sun, marking the solstices and equinoxes."] },
  { cat: "History", region: "Americas", diff: 2, q: "Cliff Palace at Mesa Verde — a stone village built into a canyon alcove — was made by which people of the US Southwest?", options: ["Ancestral Puebloans", "The Inca", "The Haudenosaunee", "The Olmec"], answer: 0, fact: "At Chaco Canyon the same culture raised great houses like Pueblo Bonito — up to five storeys with about 800 rooms, built to track the sun's and moon's cycles.", src: "https://en.wikipedia.org/wiki/Pueblo_Bonito" },
  { cat: "History", region: "Americas", diff: 3, q: "The Haudenosaunee (Iroquois) Confederacy united nations under its Great Law of Peace. How many nations did it originally bring together?", options: ["Five", "Two", "Nine", "Thirteen"], answer: 0, fact: "The five founders were the Mohawk, Oneida, Onondaga, Cayuga and Seneca; the Tuscarora acceded in 1722, making it the Six Nations.", src: "https://en.wikipedia.org/wiki/Great_Law_of_Peace", deeper: ["The confederacy's emblem is a great eastern white pine, the Tree of Peace, standing for the nations joined as one.", "Its Great Law was recorded not on paper but on wampum — belts of shell beads encoding the message in pictograms."] },
  { cat: "History", region: "Americas", diff: 3, q: "The Maya were expert skywatchers. Their Dresden Codex is celebrated above all for a table charting the cycles of which planet?", options: ["Venus", "Mars", "Jupiter", "Saturn"], answer: 0, fact: "The codex's Venus table tracked the planet's cycles well enough to predict its risings, and its lunar tables line up with the timing of eclipses.", src: "https://en.wikipedia.org/wiki/Dresden_Codex" },
  { cat: "History", region: "Americas", diff: 3, q: "The Inca linked their empire with over 40,000 km of roads. With no horses or wheels, how were urgent messages relayed along them?", options: ["Relay runners", "Carrier pigeons", "Signal drums", "Smoke signals"], answer: 0, fact: "Chasqui runners dashed between waystations spaced about a day's walk apart, handing off spoken messages and quipus so news sped across the empire on foot.", src: "https://en.wikipedia.org/wiki/Inca_road_system", deeper: ["The roads leapt Andean gorges on woven-grass suspension bridges, which crews had to replace roughly every two years.", "Called Qhapaq Nan, the network laced together Tawantinsuyu — the 'four quarters' — from Colombia to Chile."] },
  // -- Asia --
  { cat: "History", region: "Asia", diff: 1, kids: true, q: "The Terracotta Army — thousands of life-sized clay soldiers — was buried to guard the tomb of which ruler?", options: ["Qin Shi Huang", "Confucius", "Kublai Khan", "Sun Tzu"], answer: 0, fact: "Qin Shi Huang was China's first emperor, uniting its warring states in 221 BCE. No two of the roughly 8,000 terracotta soldiers share the same face.", src: "https://en.wikipedia.org/wiki/Terracotta_Army", deeper: ["The central tomb mound has never been dug up; ancient records tell of rivers of mercury inside, and soil tests there really do show unusually high mercury.", "The clay warriors were once brightly painted, but the lacquer can flake off within minutes of meeting dry air after 2,000 years underground."] },
  { cat: "History", region: "Asia", diff: 1, kids: true, q: "In old Japan, warriors who served lords and followed a strict code called bushido were known as what?", options: ["Cossacks", "Janissaries", "Samurai", "Shaolin monks"], answer: 2, fact: "Bushido, 'the way of the warrior,' stressed loyalty and honour. On duty a samurai wore a matched pair of swords — a long katana and a shorter blade — called daisho.", src: "https://en.wikipedia.org/wiki/Samurai" },
  { cat: "History", region: "Asia", diff: 1, kids: true, q: "Angkor Wat, the largest religious monument in the world, was built in the 1100s by which empire?", options: ["Gupta Empire", "Chola Empire", "Majapahit Empire", "Khmer Empire"], answer: 3, fact: "Angkor Wat began as a Hindu temple to the god Vishnu, then gradually became a Buddhist site. It has appeared on Cambodia's national flag since 1863.", src: "https://en.wikipedia.org/wiki/Angkor_Wat", deeper: ["At its peak, greater Angkor sprawled over at least 1,000 sq km — bigger than modern Paris — likely the largest city of the pre-industrial world.", "Angkor's temples used more stone than all of ancient Egypt's monuments combined, and its farmland may have fed close to a million people."] },
  { cat: "History", region: "Asia", diff: 2, kids: true, q: "Korea's own alphabet, Hangul, was created in the 1440s under which king?", options: ["Gwanggaeto", "Sejong the Great", "Taejo", "Kublai Khan"], answer: 1, fact: "Hangul was made so ordinary people could read easily; the shapes of its consonants copy how the tongue and lips move to make each sound.", src: "https://en.wikipedia.org/wiki/Hangul", deeper: ["Many elite scholars scorned Hangul, preferring Chinese characters; it only became Korea's main script in the late 1800s. Koreans mark Hangul Day each October.", "Because its letters map so neatly onto sounds, Hangul is often praised as one of the most logical and easy-to-learn writing systems ever created."] },
  { cat: "History", region: "Asia", diff: 2, q: "Emperor Ashoka, who spread Buddhist teachings across South Asia, ruled which ancient empire?", options: ["Gupta Empire", "Mauryan Empire", "Mughal Empire", "Chola Empire"], answer: 1, fact: "Ashoka had edicts carved on rocks and pillars across his empire. The four-lion Lion Capital of Ashoka is now the national emblem of India.", src: "https://en.wikipedia.org/wiki/Ashoka" },
  { cat: "History", region: "Asia", diff: 2, q: "Gunpowder was first developed over a thousand years ago by alchemists in which country?", options: ["Persia", "India", "Egypt", "China"], answer: 3, fact: "Chinese alchemists stumbled on gunpowder around the 800s CE while seeking an elixir of eternal life — one of the 'Four Great Inventions' of ancient China.", src: "https://en.wikipedia.org/wiki/Gunpowder" },
  { cat: "History", region: "Asia", diff: 2, q: "At its 14th-century peak, the mighty Majapahit Empire ruled much of maritime Southeast Asia from its heartland on which island?", options: ["Sri Lanka", "Borneo", "Java", "Luzon"], answer: 2, fact: "Majapahit's chief minister Gajah Mada swore the famous Palapa oath — vowing to take no rest until he had united the archipelago's islands under Majapahit.", src: "https://en.wikipedia.org/wiki/Majapahit" },
  { cat: "History", region: "Asia", diff: 3, q: "The Silk Road city of Samarkand became the dazzling capital of whose empire in the late 1300s?", options: ["Timur (Tamerlane)", "Genghis Khan", "Cyrus the Great", "Babur"], answer: 0, fact: "Timur filled Samarkand with tiled mosques and madrasas. His grandson Ulugh Beg built an observatory there and measured the year to within about a minute.", src: "https://en.wikipedia.org/wiki/Ulugh_Beg" },
  { cat: "History", region: "Asia", diff: 3, q: "Srivijaya, a great maritime power that rose in the 600s CE, was famed across Asia as a center for studying which religion?", options: ["Zoroastrianism", "Shinto", "Islam", "Buddhism"], answer: 3, fact: "The Chinese monk Yijing spent six months at Srivijaya's capital, Palembang on Sumatra, in 671 CE; the empire was a Buddhist learning hub for centuries.", src: "https://en.wikipedia.org/wiki/Srivijaya" },
  { cat: "History", region: "Asia", diff: 3, q: "Which grandson of Genghis Khan founded China's Yuan dynasty and ruled from a city that is now Beijing?", options: ["Batu Khan", "Ögedei Khan", "Kublai Khan", "Timur"], answer: 2, fact: "Kublai Khan proclaimed the Yuan dynasty in 1271 and built his capital, Dadu, where Beijing now stands — the first non-Han dynasty to rule all of China.", src: "https://en.wikipedia.org/wiki/Yuan_dynasty" },
  // -- Europe --
  { cat: "History", region: "Europe", diff: 1, kids: true, q: "In which land were the ancient Olympic Games first held, at a sanctuary called Olympia?", options: ["Egypt", "Greece", "Italy", "Persia"], answer: 1, fact: "The ancient Games ran for nearly 1,200 years, and a sacred truce paused wars so athletes and spectators could travel to Olympia in safety.", src: "https://en.wikipedia.org/wiki/Ancient_Olympic_Games" },
  { cat: "History", region: "Europe", diff: 2, q: "Which ancient Greek city is remembered as an early birthplace of democracy?", options: ["Sparta", "Athens", "Corinth", "Thebes"], answer: 1, fact: "Athens was a direct democracy, but only free adult men could vote — women, enslaved people and foreigners were excluded, perhaps 4 in 5 residents.", src: "https://en.wikipedia.org/wiki/Athenian_democracy" },
  { cat: "History", region: "Europe", diff: 2, q: "Which Roman town, famously preserved under volcanic ash, was buried by Mount Vesuvius in 79 CE?", options: ["Pompeii", "Ostia", "Ravenna", "Capua"], answer: 0, fact: "Ash sealed the town so completely that archaeologists found loaves of bread, painted shop signs and wall graffiti — a snapshot of ordinary Roman life.", src: "https://en.wikipedia.org/wiki/Pompeii" },
  { cat: "History", region: "Europe", diff: 1, kids: true, q: "In medieval Europe, most ordinary people earned their living as what?", options: ["Peasant farmers", "Merchant traders", "Soldiers", "Craftsmen in guilds"], answer: 0, fact: "Many peasants were serfs, bound to a lord's land: they farmed his fields for protection and a small plot of their own, and couldn't leave without permission.", src: "https://en.wikipedia.org/wiki/Serfdom" },
  { cat: "History", region: "Europe", diff: 3, q: "The Black Death that swept Europe in the 1340s was a devastating outbreak of which disease?", options: ["Cholera", "Plague", "Smallpox", "Typhus"], answer: 1, fact: "It killed perhaps a third to a half of Europe's people in just a few years — among the deadliest disasters in all of human history.", src: "https://en.wikipedia.org/wiki/Black_Death", deeper: ["With so few workers left, surviving peasants could demand higher pay — helping to weaken serfdom across much of Europe.", "The bacterium behind it, Yersinia pestis, still causes plague today, but is now curable with antibiotics."] },
  { cat: "History", region: "Europe", diff: 2, kids: true, q: "The Renaissance is generally said to have begun in which Italian city?", options: ["Rome", "Venice", "Florence", "Paris"], answer: 2, fact: "'Renaissance' is French for 'rebirth' — thinkers and artists revived the learning of ancient Greece and Rome after the Middle Ages.", src: "https://en.wikipedia.org/wiki/Renaissance", deeper: ["The Medici who funded Florence's art were bankers, not kings — their fortune paid for work by Leonardo, Botticelli and Michelangelo.", "Scholars called 'humanists' tracked down ancient Greek and Latin manuscripts, reviving learning nearly lost in Europe."] },
  { cat: "History", region: "Europe", diff: 3, q: "In 1517 Martin Luther sparked the Reformation by publishing his Ninety-five Theses in which town?", options: ["Rome", "Geneva", "Wittenberg", "Paris"], answer: 2, fact: "Though written in Latin, the Theses were soon translated into German and printed, spreading across the region within about two weeks.", src: "https://en.wikipedia.org/wiki/Ninety-five_Theses", deeper: ["Luther was protesting 'indulgences' — payments the Church claimed could reduce the punishment for a person's sins.", "The movement split Western Christianity, creating Protestant churches independent of the Pope in Rome."] },
  { cat: "History", region: "Europe", diff: 2, q: "The Industrial Revolution began around the 1760s in which country?", options: ["France", "Great Britain", "Germany", "United States"], answer: 1, fact: "Early cotton mills relied on the labour of women and children, some working twelve-hour days, until reform laws slowly limited it.", src: "https://en.wikipedia.org/wiki/Industrial_Revolution" },
  { cat: "History", region: "Europe", diff: 3, q: "Whose greatly improved steam engine, with a separate condenser, became a driving force of the Industrial Revolution?", options: ["Isambard Kingdom Brunel", "James Watt", "George Stephenson", "Richard Arkwright"], answer: 1, fact: "Watt's design used up to five times less fuel than earlier engines — the unit of power, the watt, is named in his honour.", src: "https://en.wikipedia.org/wiki/James_Watt" },
  { cat: "History", region: "Europe", diff: 1, kids: true, q: "An early steam locomotive that won the 1829 Rainhill Trials was named what?", options: ["Rocket", "Comet", "Puffing Billy", "Locomotion"], answer: 0, fact: "Rocket reached about 48 km/h (30 mph) — dizzying then, when most people had never travelled faster than a galloping horse.", src: "https://en.wikipedia.org/wiki/Stephenson%27s_Rocket" },
  // -- Middle East --
  { cat: "History", region: "MiddleEast", diff: 1, q: "Which Babylonian king is remembered for issuing one of the earliest written law codes, carved onto a tall stone pillar?", options: ["Sargon of Akkad", "Hammurabi", "Nebuchadnezzar II", "Ashurbanipal"], answer: 1, fact: "His code was carved on a basalt pillar over 2 metres tall — now in the Louvre — setting fixed penalties so justice no longer varied case by case.", src: "https://en.wikipedia.org/wiki/Code_of_Hammurabi" },
  { cat: "History", region: "MiddleEast", diff: 1, kids: true, q: "Which Persian king founded the Achaemenid Empire and let the peoples he ruled keep their own customs and religions?", options: ["Cyrus the Great", "Xerxes I", "Darius III", "Cambyses II"], answer: 0, fact: "The Cyrus Cylinder, a clay barrel written in cuneiform, records his reign; the original is in the British Museum and a replica sits at the United Nations.", src: "https://en.wikipedia.org/wiki/Cyrus_Cylinder" },
  { cat: "History", region: "MiddleEast", diff: 2, kids: true, q: "The word 'algebra' comes from a book written by which scholar of Baghdad's House of Wisdom?", options: ["Omar Khayyam", "Ibn Sina", "Al-Razi", "Al-Khwarizmi"], answer: 3, fact: "The title word 'al-jabr' means 'restoration' — the step of balancing an equation by adding equal amounts to both sides; we now call the whole subject algebra.", src: "https://en.wikipedia.org/wiki/Al-Khwarizmi", deeper: ["The word 'algorithm' also comes from his name, which medieval Europe wrote in Latin as 'Algoritmi'.", "He helped spread Hindu-Arabic numerals — the 0-9 digits the world still writes with today."] },
  { cat: "History", region: "MiddleEast", diff: 1, kids: true, q: "The Phoenicians, seafaring traders of the eastern Mediterranean, are credited with spreading an early version of what?", options: ["The wheel", "The alphabet", "Paper", "Gunpowder"], answer: 1, fact: "Their alphabet had 22 letters and no vowels; the Greeks borrowed it and added vowels, and nearly every Western alphabet descends from it.", src: "https://en.wikipedia.org/wiki/Phoenician_alphabet", deeper: ["Our word 'alphabet' comes from its first two letters, 'aleph' and 'bet'.", "Traders carried the script across the sea from home cities like Tyre and Byblos in what is now Lebanon."] },
  { cat: "History", region: "MiddleEast", diff: 2, q: "The House of Wisdom, a celebrated centre of learning and translation, stood in which city?", options: ["Damascus", "Cordoba", "Baghdad", "Samarkand"], answer: 2, fact: "During the Abbasid era its scholars translated Greek, Persian and Indian works into Arabic, safeguarding knowledge that later flowed on to Europe.", src: "https://en.wikipedia.org/wiki/House_of_Wisdom" },
  { cat: "History", region: "MiddleEast", diff: 2, q: "In 1453 the Ottoman sultan Mehmed II captured which great city and made it his new capital?", options: ["Vienna", "Cairo", "Baghdad", "Constantinople"], answer: 3, fact: "Mehmed II was only about 21; his conquest ended the thousand-year Byzantine (Eastern Roman) Empire, and the city — later Istanbul — became the Ottoman capital.", src: "https://en.wikipedia.org/wiki/Fall_of_Constantinople" },
  { cat: "History", region: "MiddleEast", diff: 3, q: "The Epic of Gilgamesh, among the world's oldest surviving stories, was composed by which civilization?", options: ["Ancient Mesopotamia", "Ancient Egypt", "Ancient Greece", "The Indus Valley"], answer: 0, fact: "Preserved on clay tablets, it includes a great-flood tale in which a man builds a boat to survive — a story written centuries before the similar account in Genesis.", src: "https://en.wikipedia.org/wiki/Epic_of_Gilgamesh" },
  { cat: "History", region: "MiddleEast", diff: 3, q: "Persepolis, with its great columned halls, was the ceremonial capital of which empire?", options: ["The Ottoman Empire", "The Babylonian Empire", "The Achaemenid Persian Empire", "The Assyrian Empire"], answer: 2, fact: "Its Apadana staircase is carved with delegations from across the empire bringing gifts; Alexander of Macedon's army burned the palace in 330 BCE.", src: "https://en.wikipedia.org/wiki/Persepolis" },
  { cat: "History", region: "MiddleEast", diff: 3, q: "'The Canon of Medicine', a medical encyclopaedia used for centuries, was written by which scholar?", options: ["Ibn Battuta", "Al-Ghazali", "Rumi", "Ibn Sina (Avicenna)"], answer: 3, fact: "Completed around 1025, the Canon was still used as a standard medical textbook in European universities into the 1600s — roughly 600 years later.", src: "https://en.wikipedia.org/wiki/The_Canon_of_Medicine" },
  { cat: "History", region: "MiddleEast", diff: 2, kids: true, q: "Our 60-minute hour and 360-degree circle are inherited from the counting system of which ancient people?", options: ["The Romans", "The Babylonians", "The Egyptians", "The Greeks"], answer: 1, fact: "They counted in base 60 — a system begun by the Sumerians — and it still shapes how we measure time and the angles of a circle today.", src: "https://en.wikipedia.org/wiki/Sexagesimal", deeper: ["60 is the smallest number evenly divisible by 1, 2, 3, 4, 5 and 6, which made fractions easy to handle.", "They wrote every number by combining just two cuneiform marks — one for units and one for tens — pressed into clay."] },

  // -- verified batch: africaNorth --
  { cat: "History", region: "Africa", country: "Tunisia", diff: 1, kids: true, q: "The mighty trading city of Carthage, near today's Tunis in Tunisia, was founded almost 3,000 years ago by settlers from which seafaring people?", options: ["The Greeks", "The Phoenicians", "The Egyptians", "The Romans"], answer: 1, fact: "Its Punic name, Qart-hadasht, means 'new city'; legend says it was founded by queen Elissa — the Dido of Greek and Roman stories — who sailed from Tyre.", src: "https://en.wikipedia.org/wiki/Carthage", deeper: ["In the legend, Elissa was offered as much land as one oxhide could cover — so she cut the hide into thin strips and enclosed a whole hill.", "'New city' implied a 'new Tyre' — Carthage began as a colony of the Phoenician port of Tyre and grew into a great power in its own right."] },
  { cat: "History", region: "Africa", country: "Tunisia", diff: 2, q: "Founded in 670 CE, which city in today's Tunisia became one of North Africa's earliest great centres of Islamic learning?", options: ["Kairouan", "Tunis", "Sfax", "Carthage"], answer: 0, fact: "Its Great Mosque doubled as a university of Islamic sciences under the Maliki school, drawing students and scholars from across the Muslim world.", src: "https://en.wikipedia.org/wiki/Kairouan" },
  { cat: "History", region: "Africa", country: "Algeria", diff: 3, q: "Massinissa, who in 202 BCE united his people into one kingdom and then ruled it for over 50 years, was the first king of which North African state?", options: ["Kush", "Aksum", "Numidia", "Ancient Mauretania"], answer: 2, fact: "Massinissa spread new farming techniques so well that Numidia became known as a breadbasket of Rome — and he was still leading troops at his death, aged 90.", src: "https://en.wikipedia.org/wiki/Masinissa", deeper: ["His capital Cirta lives on as Constantine, one of modern Algeria's great cities.", "In 202 BCE his cavalry helped decide the Battle of Zama, which ended the Second Punic War — the same year he became king of united Numidia."] },
  { cat: "History", region: "Africa", country: "Algeria", diff: 2, q: "Emir Abdelkader, honoured as a founding hero of modern Algeria, led a 16-year resistance from 1831 against invasion by which country?", options: ["Spain", "Britain", "France", "The Ottoman Empire"], answer: 2, fact: "Decades later, exiled in Damascus, Abdelkader sheltered thousands of Christians during the 1860 massacres, earning decorations from governments across the world.", src: "https://en.wikipedia.org/wiki/Abdelkader_ibn_Muhieddine" },
  { cat: "History", region: "Africa", country: "Morocco", diff: 1, kids: true, q: "Which city, founded around 1070 as an imperial capital, later gave its name to the whole country of Morocco?", options: ["Fes", "Casablanca", "Rabat", "Marrakesh"], answer: 3, fact: "Marrakesh was founded by the Almoravids, an Amazigh (Berber) dynasty whose empire stretched from the edge of Senegal to the centre of Spain.", src: "https://en.wikipedia.org/wiki/Marrakesh", deeper: ["European names for Morocco — Maroc, Marokko, Marruecos — all derive from Murrakush, the city's name.", "The Almohads, who took Marrakesh in 1147, built the Koutoubia minaret, whose design influenced Seville's Giralda and Rabat's Hassan Tower."] },
  { cat: "History", region: "Africa", country: "Morocco", diff: 2, q: "The Qarawiyyin in Fes, Morocco — a mosque and centre of learning teaching since the 9th century — was founded, tradition holds, by whom?", options: ["Ibn Khaldun, the historian", "Fatima al-Fihri, a merchant's daughter", "Idris II, founder of Fes", "An Almohad caliph"], answer: 1, fact: "UNESCO and Guinness World Records cite al-Qarawiyyin as the world's oldest continually operating higher-learning institution — built with Fatima's inheritance.", src: "https://en.wikipedia.org/wiki/University_of_al-Qarawiyyin" },
  { cat: "History", region: "Africa", country: "Egypt", diff: 1, kids: true, q: "Which famous African capital city was founded in 969 CE under the Arabic name al-Qahira — 'the Conqueror'?", options: ["Cairo", "Tunis", "Tripoli", "Khartoum"], answer: 0, fact: "Cairo was laid out as a royal capital by the Fatimid dynasty; their al-Azhar mosque grew into one of the world's oldest universities and still teaches today.", src: "https://en.wikipedia.org/wiki/Cairo" },
  { cat: "History", region: "Africa", country: "Egypt", diff: 3, q: "The Mamluks — elite soldiers of enslaved origin who rose to rule Egypt — crushed which seemingly unstoppable army at Ain Jalut in 1260?", options: ["The Mongols", "The Crusaders", "The Byzantines", "The Ottomans"], answer: 0, fact: "Ain Jalut marked the first major halt to the Mongol advance — cited as the first time the Mongols were lastingly stopped from expanding their reach.", src: "https://en.wikipedia.org/wiki/Battle_of_Ain_Jalut", deeper: ["'Mamluk' means 'owned' in Arabic: boys bought mainly from Central Asia and the Caucasus trained as elite cavalry and could rise, by merit, to the throne.", "After the Mongols destroyed Baghdad in 1258, Mamluk Cairo became the Islamic world's leading city and hosted a new line of Abbasid caliphs."] },
  { cat: "History", region: "Africa", country: "Libya", diff: 2, q: "The Roman emperor Septimius Severus was born in Leptis Magna and showered his home city with grand monuments. Its ruins stand in which modern country?", options: ["Tunisia", "Egypt", "Morocco", "Libya"], answer: 3, fact: "Severus gave Leptis a magnificent new forum, a basilica and rebuilt docks; Punic in origin, the city is among the best-preserved Roman sites in the Mediterranean.", src: "https://en.wikipedia.org/wiki/Leptis_Magna" },
  { cat: "History", region: "Africa", country: "Regional", diff: 2, kids: true, q: "Tuareg communities of the Sahara — in Niger, Mali and beyond — still write with the tifinagh alphabet. The Tuareg belong to which indigenous North African people?", options: ["The Nubians", "The Copts", "The Phoenicians", "The Amazigh (Berbers)"], answer: 3, fact: "Tifinagh descends from the ancient Libyco-Berber script, with inscriptions as old as the 6th century BCE; since 2003 a modern form is taught in Moroccan schools.", src: "https://en.wikipedia.org/wiki/Tifinagh" },
  { cat: "History", region: "Africa", country: "Mali", diff: 1, kids: true, q: "The traveller Ibn Battuta visited the Saharan trade town of Taghaza in 1352 and found its houses and mosque built from a surprising material. What was it?", options: ["Mud bricks", "Palm-wood planks", "Slabs of salt", "Blocks of coral stone"], answer: 2, fact: "The salt-slab buildings were roofed with camel skins; nothing grew at Taghaza, so food arrived by caravan while camels carried salt south, two slabs each.", src: "https://en.wikipedia.org/wiki/Taghaza" },
  { cat: "History", region: "Africa", country: "Mauritania", diff: 3, q: "Chinguetti, a medieval caravan town whose family-run libraries still guard centuries-old manuscripts, lies deep in the desert of which modern country?", options: ["Sudan", "Mauritania", "Chad", "Niger"], answer: 1, fact: "For centuries, pilgrims from across the Maghreb gathered at Chinguetti before crossing the desert to Mecca; UNESCO listed the old town in 1996.", src: "https://en.wikipedia.org/wiki/Chinguetti" },

  // -- verified batch: history30 --
  { cat: "History", region: "Africa", country: "Egypt", diff: 1, kids: true, q: "Who was the famous last queen of ancient Egypt?", options: ["Nefertiti", "Hatshepsut", "Nefertari", "Cleopatra"], answer: 3, fact: "Though queen of Egypt, Cleopatra was Macedonian Greek — the only ruler of her dynasty known to have learned the Egyptian language.", src: "https://en.wikipedia.org/wiki/Cleopatra", deeper: ["Her dynasty was founded by Ptolemy, a Macedonian general and companion of Alexander the Great, after Alexander's death.", "Rome's takeover after her death in 30 BCE ended nearly three centuries of Ptolemaic rule in Egypt."] },
  { cat: "History", region: "Africa", country: "Egypt", diff: 1, kids: true, q: "Whose nearly untouched tomb, packed with golden treasures, was discovered in Egypt in 1922?", options: ["Ramses II", "Tutankhamun", "Cleopatra", "Khufu"], answer: 1, fact: "Tutankhamun became pharaoh at about age nine and died at around 18 — the famous 'boy king' ruled for roughly a decade.", src: "https://en.wikipedia.org/wiki/Tutankhamun", deeper: ["Howard Carter's team catalogued more than 5,000 artifacts packed inside the tomb.", "Born Tutankhaten, he changed his name as Egypt restored its old gods after his father Akhenaten's religious revolution."] },
  { cat: "History", region: "Americas", country: "United States", diff: 1, kids: true, q: "Which two brothers made the first successful powered airplane flights in 1903?", options: ["The Montgolfier brothers", "The Wright brothers", "The Lumière brothers", "The Grimm brothers"], answer: 1, fact: "The first flight lasted just 12 seconds and covered 37 metres — shorter than the wingspan of a modern jumbo jet.", src: "https://en.wikipedia.org/wiki/Wright_brothers", deeper: ["The brothers funded their experiments with profits from their bicycle shop in Dayton, Ohio.", "They built a wind tunnel in the shop and tested about 200 miniature wing shapes to perfect their design."] },
  { cat: "History", region: "Europe", country: "United Kingdom", diff: 1, q: "Which famous ship sank on its first voyage in April 1912 after striking an iceberg?", options: ["Lusitania", "Queen Mary", "Titanic", "Britannic"], answer: 2, fact: "The wreck was only found in 1985, lying 3,800 metres down in two pieces — located by a French–American team led by Robert Ballard.", src: "https://en.wikipedia.org/wiki/Wreck_of_the_Titanic" },
  { cat: "History", region: "Americas", country: "United States", diff: 1, kids: true, q: "What was the name of the ship that carried the Pilgrims from England to America in 1620?", options: ["Santa María", "Endeavour", "Beagle", "Mayflower"], answer: 3, fact: "The crossing took 66 days — and before going ashore, passengers signed the Mayflower Compact, an early agreement to govern themselves.", src: "https://en.wikipedia.org/wiki/Mayflower", deeper: ["The Pilgrims built Plymouth Colony on the site of Patuxet, a Wampanoag village recently emptied by an epidemic that earlier European contact had brought.", "The Mayflower Compact bound only the English settlers to one another — the land they settled had been home to the Wampanoag and other Native nations for thousands of years."] },
  { cat: "History", region: "Americas", country: "Regional", diff: 1, kids: true, q: "In 1492, Christopher Columbus crossed which ocean hoping to find a westward route to Asia?", options: ["The Pacific Ocean", "The Indian Ocean", "The Atlantic Ocean", "The Arctic Ocean"], answer: 2, fact: "Columbus made four round-trip voyages between 1492 and 1504, reaching the Caribbean and the coasts of Central and South America.", src: "https://en.wikipedia.org/wiki/Christopher_Columbus", deeper: ["The islands he reached were already home to millions of Indigenous people, including the Taíno, who had lived there for thousands of years.", "Columbus went to his grave insisting he had reached Asia, never accepting he had encountered continents unknown to Europeans."] },
  { cat: "History", region: "Europe", country: "United Kingdom", diff: 1, kids: true, q: "Which British queen reigned for over 63 years during the 19th century?", options: ["Elizabeth I", "Anne", "Victoria", "Mary II"], answer: 2, fact: "Victoria reigned 63 years and 216 days — longer than any monarch before her — and gave her name to an era of sweeping change.", src: "https://en.wikipedia.org/wiki/Queen_Victoria" },
  { cat: "History", region: "MiddleEast", country: "Jordan", diff: 2, kids: true, q: "The ancient 'Rose City' of Petra, carved into pink sandstone cliffs, lies in which modern country?", options: ["Egypt", "Jordan", "Turkey", "Iran"], answer: 1, fact: "Petra's builders, the Nabataeans, mastered desert rainwater collection — their channels and cisterns created an artificial oasis.", src: "https://en.wikipedia.org/wiki/Petra" },
  { cat: "History", region: "Africa", country: "Tunisia", diff: 2, q: "Which Carthaginian general crossed the Alps with war elephants to invade Roman Italy?", options: ["Hannibal", "Scipio Africanus", "Attila the Hun", "Alexander the Great"], answer: 0, fact: "Hannibal held southern Italy for 15 years; Romans cried 'Hannibal ad portas' — 'Hannibal is at the gates!' — a phrase that long outlived him.", src: "https://en.wikipedia.org/wiki/Hannibal" },
  { cat: "History", region: "Europe", country: "United Kingdom", diff: 2, q: "In 1215, rebellious barons forced King John of England to accept which famous charter?", options: ["The Bill of Rights", "Magna Carta", "The Domesday Book", "The Edict of Nantes"], answer: 1, fact: "Only four original 1215 copies survive — and Pope Innocent III annulled the charter almost immediately, sparking the First Barons' War.", src: "https://en.wikipedia.org/wiki/Magna_Carta" },
  { cat: "History", region: "Global", country: "Chile", diff: 2, kids: true, q: "On which Pacific island did the Rapa Nui people carve more than 900 giant stone statues called moai?", options: ["Fiji", "Tahiti", "Easter Island", "Hawaii"], answer: 2, fact: "The famous 'Easter Island heads' actually have full bodies — many moai are simply buried up to their shoulders.", src: "https://en.wikipedia.org/wiki/Moai", deeper: ["All but 53 of the 900-plus moai were carved from volcanic tuff at one quarry, Rano Raraku, where 394 statues still stand unfinished.", "Experiments show islanders could have 'walked' statues upright to their platforms, rocking them side to side with ropes."] },
  { cat: "History", region: "Europe", country: "Italy", diff: 2, q: "Who became the first Roman emperor?", options: ["Julius Caesar", "Augustus", "Nero", "Constantine"], answer: 1, fact: "The month of August is named after him — the Senate granted the honorific 'Augustus', meaning 'the revered', in 27 BCE.", src: "https://en.wikipedia.org/wiki/Augustus", deeper: ["He was born Gaius Octavius; his great-uncle Julius Caesar named him heir on condition he take Caesar's name.", "He ruled for over 40 years, from 27 BCE until his death in 14 CE."] },
  { cat: "History", region: "MiddleEast", country: "Egypt", diff: 2, q: "The Suez Canal, opened in 1869, connects the Mediterranean Sea with which other sea?", options: ["The Black Sea", "The Red Sea", "The Caspian Sea", "The Arabian Sea"], answer: 1, fact: "The canal has no locks — seawater flows freely through it — and it shortens the sea route from the Arabian Sea to London by about 8,900 km.", src: "https://en.wikipedia.org/wiki/Suez_Canal" },
  { cat: "History", region: "Americas", country: "United States", diff: 2, q: "Who was the first woman to fly solo nonstop across the Atlantic Ocean, in 1932?", options: ["Amelia Earhart", "Bessie Coleman", "Harriet Quimby", "Valentina Tereshkova"], answer: 0, fact: "Her 15-hour flight from Newfoundland ended in a Northern Ireland pasture — asked 'Have you flown far?', she replied, 'From America.'", src: "https://en.wikipedia.org/wiki/Amelia_Earhart" },
  { cat: "History", region: "Global", country: "New Zealand", diff: 2, q: "Which country became the first in the world where all women could vote in national elections, in 1893?", options: ["United States", "United Kingdom", "France", "New Zealand"], answer: 3, fact: "The victorious 1893 petition carried nearly 32,000 signatures — almost a quarter of New Zealand's adult European women.", src: "https://en.wikipedia.org/wiki/Women%27s_suffrage_in_New_Zealand", deeper: ["Campaign leader Kate Sheppard went on to found the National Council of Women of New Zealand in 1896.", "Women cast their first ballots just weeks after the law passed, in the election of 28 November 1893."] },
  { cat: "History", region: "Global", country: "Australia", diff: 2, kids: true, q: "About how long ago did the ancestors of Aboriginal Australians first arrive on their continent?", options: ["About 500 years ago", "About 5,000 years ago", "At least 50,000 years ago", "About 2 million years ago"], answer: 2, fact: "More than 250 distinct Aboriginal languages were spoken across Australia when Europeans first arrived.", src: "https://en.wikipedia.org/wiki/Aboriginal_Australians" },
  { cat: "History", region: "Europe", country: "Turkey", diff: 3, q: "Which Byzantine emperor rebuilt the Hagia Sophia and ordered the great codification of Roman law?", options: ["Constantine I", "Heraclius", "Basil II", "Justinian I"], answer: 3, fact: "Justinian's Roman law code remains the basis of civil law in many modern states; he rebuilt Hagia Sophia after riots burned the church.", src: "https://en.wikipedia.org/wiki/Justinian_I" },
  { cat: "History", region: "Africa", country: "Morocco", diff: 3, q: "Which 14th-century Moroccan traveler journeyed about 117,000 km, from West Africa to China?", options: ["Ibn Battuta", "Ibn Khaldun", "Al-Idrisi", "Ibn Sina"], answer: 0, fact: "He travelled about 117,000 km — more than any known explorer of the pre-modern world, nearly five times Marco Polo's total.", src: "https://en.wikipedia.org/wiki/Ibn_Battuta", deeper: ["Near the end of his life he dictated his adventures into a famous account known simply as the Rihla — 'The Travels'.", "His distance even tops Ming admiral Zheng He's great ocean voyages, credited at about 50,000 km."] },
  { cat: "History", region: "Americas", country: "United States", diff: 3, q: "In 1821, Sequoyah completed a groundbreaking writing system for which language?", options: ["Cherokee", "Navajo", "Hawaiian", "Maori"], answer: 0, fact: "Within 25 years Cherokee literacy neared 100%, surpassing nearby settlers — and the Cherokee Phoenix became North America's first bilingual newspaper.", src: "https://en.wikipedia.org/wiki/Sequoyah" },
  { cat: "History", region: "Africa", country: "Ghana", diff: 3, q: "Which African country, formerly the British colony of the Gold Coast, won independence in 1957?", options: ["Ghana", "Kenya", "Nigeria", "Senegal"], answer: 0, fact: "It was the first sub-Saharan colony to win sovereignty, and renamed itself after the medieval Ghana Empire, a West African power of centuries past.", src: "https://en.wikipedia.org/wiki/Ghana", deeper: ["First leader Kwame Nkrumah was the first African head of state to promote pan-Africanism.", "The old empire's name is thought to come from a royal title; its rulers grew rich on West African gold."] },
  { cat: "History", region: "Europe", country: "Germany", diff: 3, q: "Which city served as the informal capital of the Hanseatic League, medieval Europe's great trading network?", options: ["Hamburg", "Lübeck", "Berlin", "Munich"], answer: 1, fact: "Its kontor trading posts stretched from London and Bruges to Bergen and Novgorod, tying together nearly 200 towns in eight modern countries.", src: "https://en.wikipedia.org/wiki/Hanseatic_League" },

  // ---------- SCIENCE ----------
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "What gas do plants primarily absorb for photosynthesis?", options: ["Oxygen", "Nitrogen", "Carbon dioxide", "Hydrogen"], answer: 2, fact: "A large tree can absorb ~22 kg of CO2 per year and release enough oxygen for two people.", src: "https://en.wikipedia.org/wiki/Photosynthesis" },
  { cat: "Science", sub: "Chemistry", diff: 2, q: "What is the most abundant element in the universe?", options: ["Oxygen", "Carbon", "Hydrogen", "Helium"], answer: 2, fact: "Hydrogen makes up about 75% of all normal matter by mass.", src: "https://en.wikipedia.org/wiki/Hydrogen" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "How many bones are in the adult human body?", options: ["206", "312", "180", "256"], answer: 0, fact: "Babies are born with ~300 bones; many fuse together as they grow.", src: "https://en.wikipedia.org/wiki/List_of_bones_of_the_human_skeleton" },
  { cat: "Science", sub: "Physics", diff: 3, q: "What does the 'c' represent in E = mc²?", options: ["A constant of gravity", "The speed of light", "Charge", "Specific heat"], answer: 1, fact: "Because c is squared and huge, a tiny bit of mass converts into an enormous amount of energy.", src: "https://en.wikipedia.org/wiki/Mass%E2%80%93energy_equivalence" },
  { cat: "Science", sub: "Chemistry", diff: 1, kids: true, q: "What is H2O more commonly known as?", options: ["Salt", "Water", "Hydrogen peroxide", "Ammonia"], answer: 1, fact: "Water is one of the few substances less dense as a solid than a liquid — which is why ice floats.", src: "https://en.wikipedia.org/wiki/Ice" },
  { cat: "Science", sub: "Physics", diff: 3, q: "Which particle carries a negative electric charge?", options: ["Proton", "Neutron", "Electron", "Photon"], answer: 2, fact: "Electrons are ~1,836 times lighter than protons yet define nearly all of chemistry.", src: "https://en.wikipedia.org/wiki/Electron" },
  { cat: "Science", sub: "Life Sciences", diff: 2, q: "What part of the cell contains genetic material?", options: ["Mitochondria", "Nucleus", "Ribosome", "Membrane"], answer: 1, fact: "If you unravelled the DNA in a single cell it would stretch about 2 metres.", src: "https://en.wikipedia.org/wiki/DNA" },
  { cat: "Science", sub: "Physics", diff: 3, q: "At what temperature are Celsius and Fahrenheit equal?", options: ["0°", "-40°", "100°", "-273°"], answer: 1, fact: "-40 is the one point where both scales read the same number.", src: "https://en.wikipedia.org/wiki/Fahrenheit" },
  { cat: "Science", sub: "Earth & Space", diff: 1, kids: true, q: "Which planet is known as the Red Planet?", options: ["Venus", "Jupiter", "Mars", "Mercury"], answer: 2, fact: "Mars is home to Olympus Mons, a volcano about 2.5 times the height of Mount Everest.", src: "https://en.wikipedia.org/wiki/Olympus_Mons" },
  { cat: "Science", sub: "Earth & Space", diff: 1, kids: true, q: "What is the closest star to Earth?", options: ["Polaris", "Alpha Centauri", "Sirius", "The Sun"], answer: 3, fact: "Sunlight takes about 8 minutes to reach Earth — you always see the Sun as it was 8 minutes ago.", src: "https://en.wikipedia.org/wiki/Sunlight" },
  { cat: "Science", sub: "Physics", diff: 1, kids: true, q: "What force pulls a dropped ball down toward the ground?", options: ["Gravity", "Magnetism", "Friction", "Electricity"], answer: 0, fact: "Gravity is the weakest of nature's four fundamental forces — a small fridge magnet can beat the pull of the entire Earth.", src: "https://en.wikipedia.org/wiki/Fundamental_interaction" },
  { cat: "Science", sub: "Chemistry", diff: 1, kids: true, q: "What is the hardest naturally occurring material?", options: ["Quartz", "Iron", "Diamond", "Granite"], answer: 2, fact: "Diamond and pencil graphite are both pure carbon — only the arrangement of the atoms makes one hard and the other soft.", src: "https://en.wikipedia.org/wiki/Allotropes_of_carbon" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "How many chambers does the human heart have?", options: ["Two", "Three", "Four", "Five"], answer: 2, fact: "Your heart beats about 100,000 times every day — over 2.5 billion beats in an average lifetime.", src: "https://en.wikipedia.org/wiki/Heart" },
  { cat: "Science", sub: "Chemistry", diff: 2, q: "What is the chemical symbol for gold?", options: ["Go", "Au", "Gd", "Ag"], answer: 1, fact: "Gold is so malleable that a single gram can be hammered into a sheet about one square metre in size.", src: "https://en.wikipedia.org/wiki/Gold" },
  { cat: "Science", sub: "Chemistry", diff: 2, q: "Which gas makes up about 78% of Earth's atmosphere?", options: ["Oxygen", "Nitrogen", "Carbon dioxide", "Argon"], answer: 1, fact: "You can't use the nitrogen you inhale — it must first be 'fixed' by bacteria or lightning into compounds plants can absorb.", src: "https://en.wikipedia.org/wiki/Nitrogen_fixation" },
  { cat: "Science", sub: "Chemistry", diff: 2, q: "What process produces the Sun's energy?", options: ["Nuclear fission", "Nuclear fusion", "Chemical combustion", "Gravitational collapse"], answer: 1, fact: "The Sun converts about 4 million tonnes of matter into pure energy every single second — with fuel for billions of years more.", src: "https://en.wikipedia.org/wiki/Sun" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "Where in the human body would you find the femur?", options: ["In the arm", "In the leg", "In the skull", "In the spine"], answer: 1, fact: "The femur, your thigh bone, is the longest and strongest bone in your body — about a quarter of your total height.", src: "https://en.wikipedia.org/wiki/Femur" },
  { cat: "Science", sub: "Chemistry", diff: 3, q: "What is the most abundant metal in Earth's crust?", options: ["Iron", "Copper", "Aluminium", "Zinc"], answer: 2, fact: "In 1884 aluminium was still so costly that the Washington Monument was capped with a small pyramid of it as a showpiece.", src: "https://en.wikipedia.org/wiki/Washington_Monument" },
  { cat: "Science", sub: "Physics", diff: 3, q: "Approximately what temperature is absolute zero in Celsius?", options: ["-100°C", "-273°C", "-460°C", "0°C"], answer: 1, fact: "Absolute zero can never quite be reached — but labs have chilled atoms to less than a billionth of a degree above it.", src: "https://en.wikipedia.org/wiki/Absolute_zero" },
  { cat: "Science", sub: "Chemistry", diff: 3, q: "Who created the periodic table, leaving gaps for elements not yet discovered?", options: ["Antoine Lavoisier", "John Dalton", "Dmitri Mendeleev", "Niels Bohr"], answer: 2, fact: "Mendeleev predicted the properties of the missing elements — when gallium and germanium were found, they matched almost exactly.", src: "https://en.wikipedia.org/wiki/Dmitri_Mendeleev" },

  // -- verified batch: science30 --
  { cat: "Science", sub: "Physics", diff: 1, kids: true, q: "Which travels faster — light or sound?", options: ["Light", "Sound", "They travel at the same speed", "It depends on the light's color"], answer: 0, fact: "You see lightning before hearing thunder: light arrives almost instantly, but sound crawls at about 343 m/s — so counting the seconds tells you how far the storm is.", src: "https://en.wikipedia.org/wiki/Speed_of_sound" },
  { cat: "Science", sub: "Physics", diff: 1, kids: true, q: "What is the boiling point of water at sea level?", options: ["90°C", "100°C", "120°C", "50°C"], answer: 1, fact: "At high altitude water boils cooler — atop Mount Everest it boils at about 70°C, too cool to properly cook many foods.", src: "https://en.wikipedia.org/wiki/Boiling_point" },
  { cat: "Science", sub: "Physics", diff: 2, q: "What is the SI unit of force?", options: ["Joule", "Newton", "Watt", "Pascal"], answer: 1, fact: "One newton is roughly the downward pull of a small 100-gram apple in your hand — a fitting name, given the legend of Newton and the falling apple.", src: "https://en.wikipedia.org/wiki/Newton_(unit)" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "Why does the daytime sky appear blue?", options: ["Sunlight reflects off the oceans", "Air molecules scatter the Sun's blue light", "The atmosphere is full of blue gases", "Ozone is naturally blue"], answer: 1, fact: "The sky is blue because air molecules scatter the Sun's shorter blue wavelengths far more than the longer red ones — an effect called Rayleigh scattering.", src: "https://en.wikipedia.org/wiki/Rayleigh_scattering", deeper: ["The same scattering reddens sunrises and sunsets: low sunlight passes through much more air, so nearly all the blue is scattered away before it reaches you.", "Above the atmosphere the daytime sky is black — with no air to scatter sunlight, astronauts see the Sun against a starry black backdrop even at noon."] },
  { cat: "Science", sub: "Physics", diff: 3, q: "What is the SI unit of electrical resistance?", options: ["Volt", "Ampere", "Ohm", "Watt"], answer: 2, fact: "Ohm's law ties them together: voltage = current × resistance (V = I × R), one of the first formulas every electronics student learns; the unit honors Georg Ohm.", src: "https://en.wikipedia.org/wiki/Ohm" },
  { cat: "Science", sub: "Physics", diff: 1, kids: true, q: "A ramp is an example of which simple machine?", options: ["Lever", "Pulley", "Inclined plane", "Wheel and axle"], answer: 2, fact: "A ramp trades distance for force: a longer, gentler slope lets you raise the same load with a much smaller push.", src: "https://en.wikipedia.org/wiki/Inclined_plane" },
  { cat: "Science", sub: "Physics", diff: 3, q: "Through which of these can sound NOT travel?", options: ["Water", "Steel", "A wooden door", "Empty space (a vacuum)"], answer: 3, fact: "Sound needs a material to travel through, so in the vacuum of space it can't propagate at all — a real space battle would be completely silent.", src: "https://en.wikipedia.org/wiki/Sound" },
  { cat: "Science", sub: "Chemistry", diff: 1, kids: true, q: "What is the chemical name for common table salt?", options: ["Sodium chloride", "Calcium carbonate", "Sodium bicarbonate", "Potassium chloride"], answer: 0, fact: "Its sodium and chloride ions lock into a cube-shaped 'rock salt' lattice — which is why grains of table salt are shaped like tiny cubes.", src: "https://en.wikipedia.org/wiki/Sodium_chloride" },
  { cat: "Science", sub: "Chemistry", diff: 2, q: "Where in an atom are the protons and neutrons found?", options: ["In the nucleus", "In the electron shells", "Orbiting the outer edge", "In the empty space between atoms"], answer: 0, fact: "The nucleus is thousands of times smaller than the whole atom yet holds nearly all its mass — if an atom were a stadium, the nucleus would be a marble at its center.", src: "https://en.wikipedia.org/wiki/Atomic_nucleus" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "What gas is produced when baking soda reacts with vinegar?", options: ["Oxygen", "Carbon dioxide", "Hydrogen", "Nitrogen"], answer: 1, fact: "The fizz is carbon dioxide gas: the acid in vinegar reacts with baking soda, a base, and releases CO2 bubbles.", src: "https://en.wikipedia.org/wiki/Sodium_bicarbonate", deeper: ["It's a classic acid-base reaction — the same kind that makes a 'volcano' erupt in school science demonstrations.", "That same CO2 gas, from baking soda or from yeast, is what makes bread rise and gives fizzy drinks their bubbles."] },
  { cat: "Science", sub: "Chemistry", diff: 3, q: "What is the pH of a neutral solution such as pure water?", options: ["0", "7", "10", "14"], answer: 1, fact: "The pH scale is logarithmic: each step is a tenfold change, so a pH of 4 is ten times more acidic than 5 and a hundred times more than 6.", src: "https://en.wikipedia.org/wiki/PH" },
  { cat: "Science", sub: "Chemistry", diff: 1, kids: true, q: "What is dry ice made of?", options: ["Frozen carbon dioxide", "Frozen water", "Frozen nitrogen", "Frozen oxygen"], answer: 0, fact: "Dry ice is frozen carbon dioxide at about -78°C; it 'sublimes' straight from solid to gas, skipping liquid — which is why it fogs but never puddles.", src: "https://en.wikipedia.org/wiki/Dry_ice" },
  { cat: "Science", sub: "Chemistry", diff: 3, q: "Rust forms when iron reacts with oxygen and what else?", options: ["Water", "Nitrogen", "Sunlight", "Carbon"], answer: 0, fact: "Rust needs both oxygen and water, and because it's flaky rather than sealing, corrosion keeps eating inward — unlike aluminium's protective oxide skin.", src: "https://en.wikipedia.org/wiki/Rust" },
  { cat: "Science", sub: "Chemistry", diff: 2, q: "Which element has the chemical symbol 'Fe'?", options: ["Iron", "Fluorine", "Lead", "Tin"], answer: 0, fact: "Iron's symbol Fe comes from the Latin 'ferrum'; Earth's core is mostly iron, and its churning motion generates the magnetic field that shields our planet.", src: "https://en.wikipedia.org/wiki/Iron" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "What is often nicknamed the 'powerhouse' of the cell?", options: ["The nucleus", "The mitochondria", "The ribosome", "The cell membrane"], answer: 1, fact: "Mitochondria are the cell's 'powerhouses', turning food and oxygen into usable energy — busy cells like muscle and heart cells hold thousands each.", src: "https://en.wikipedia.org/wiki/Mitochondrion", deeper: ["Unlike most cell parts, mitochondria carry their own small loop of DNA, separate from the DNA stored in the nucleus.", "That hints at their origin: mitochondria likely descend from free-living bacteria absorbed by a larger cell billions of years ago."] },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "What green pigment do plants use to capture sunlight?", options: ["Keratin", "Chlorophyll", "Hemoglobin", "Melanin"], answer: 1, fact: "Chlorophyll is the green pigment that lets plants capture sunlight to make food by photosynthesis.", src: "https://en.wikipedia.org/wiki/Chlorophyll", deeper: ["It absorbs mainly blue and red light and reflects green — which is exactly why leaves look green to us.", "In autumn, chlorophyll breaks down and stops masking other pigments, revealing the yellows and oranges hidden in the leaf all along."] },
  { cat: "Science", sub: "Life Sciences", diff: 2, q: "What is the largest organ of the human body?", options: ["The liver", "The skin", "The brain", "The lungs"], answer: 1, fact: "Skin is the body's largest organ, covering about 2 square metres in an adult, and its outer layer constantly sheds and replaces dead cells.", src: "https://en.wikipedia.org/wiki/Human_skin" },
  { cat: "Science", sub: "Life Sciences", diff: 3, q: "How many chromosomes are in a typical human body cell?", options: ["23", "46", "48", "64"], answer: 1, fact: "Humans have 46 chromosomes in 23 pairs — threadlike bundles of tightly coiled DNA that carry the body's genetic instructions.", src: "https://en.wikipedia.org/wiki/Chromosome", deeper: ["You inherit one chromosome of each pair from each parent, mixing traits from both sides of your family.", "Scientists miscounted for decades, wrongly believing humans had 48 chromosomes until the true number, 46, was pinned down in the 1950s."] },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "What word describes animals that are active mainly at night?", options: ["Diurnal", "Nocturnal", "Migratory", "Hibernating"], answer: 1, fact: "Many nocturnal animals have a mirror-like layer behind the retina, the tapetum lucidum, that boosts night vision — it's why cats' eyes glow in the dark.", src: "https://en.wikipedia.org/wiki/Nocturnality" },
  { cat: "Science", sub: "Life Sciences", diff: 2, q: "Which type of blood cell is the body's main defender against infection?", options: ["Red blood cells", "White blood cells", "Platelets", "Plasma"], answer: 1, fact: "A drop of blood holds millions of red cells but only thousands of white ones — yet those few multiply rapidly to swarm invaders when infection strikes.", src: "https://en.wikipedia.org/wiki/White_blood_cell" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which part of a plant usually absorbs water and minerals from the soil?", options: ["The leaves", "The roots", "The flowers", "The stem"], answer: 1, fact: "Root tips are covered in tiny 'root hairs' that hugely increase surface area, letting a plant soak up far more water and minerals from the soil.", src: "https://en.wikipedia.org/wiki/Root" },
  { cat: "Science", sub: "Earth & Space", diff: 1, kids: true, q: "Which planet is closest to the Sun?", options: ["Venus", "Mercury", "Mars", "Earth"], answer: 1, fact: "Mercury is the smallest planet and the closest to the Sun, whipping around it in just 88 Earth days — the shortest year of any planet.", src: "https://en.wikipedia.org/wiki/Mercury_(planet)", deeper: ["With almost no atmosphere to hold heat, Mercury bakes to about 430°C in sunlight yet drops to around -180°C at night — a huge daily swing.", "Being closest doesn't make it hottest: cloud-wrapped Venus, farther out, is the hottest planet, its thick CO2 blanket trapping the heat."] },
  { cat: "Science", sub: "Earth & Space", diff: 1, kids: true, q: "Which galaxy contains our Solar System?", options: ["Andromeda", "The Milky Way", "The Whirlpool Galaxy", "Triangulum"], answer: 1, fact: "The hazy band we call the Milky Way is the combined glow of hundreds of billions of stars in our own galaxy, seen edge-on from inside it.", src: "https://en.wikipedia.org/wiki/Milky_Way" },
  { cat: "Science", sub: "Earth & Space", diff: 2, q: "What causes the cycle of day and night on Earth?", options: ["Earth orbiting the Sun", "Earth spinning on its axis", "The Moon's phases", "The Sun orbiting Earth"], answer: 1, fact: "Earth spins once about every 24 hours; that rotation, not the Sun moving, gives us day and night — and the spin is very slowly slowing over time.", src: "https://en.wikipedia.org/wiki/Earth%27s_rotation" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "Which planet is famous for its bright, wide system of rings?", options: ["Jupiter", "Saturn", "Uranus", "Neptune"], answer: 1, fact: "Saturn's rings stretch over 280,000 km across but are only about 10 metres thick in places — far thinner, proportionally, than a sheet of paper.", src: "https://en.wikipedia.org/wiki/Saturn", deeper: ["The rings are made almost entirely of water ice, in chunks ranging from tiny dust grains to house-sized boulders.", "Saturn is the only planet less dense than water — given a big enough ocean, it would float."] },
  { cat: "Science", sub: "Earth & Space", diff: 3, q: "A light-year is a unit of what?", options: ["Time", "Distance", "Speed", "Brightness"], answer: 1, fact: "A light-year measures distance, not time — about 9.5 trillion kilometres, the distance light travels in one year.", src: "https://en.wikipedia.org/wiki/Light-year", deeper: ["Light travels so fast it could circle Earth about 7.5 times in a single second — yet still takes a whole year to cross one light-year.", "The nearest star beyond the Sun, Proxima Centauri, is about 4.2 light-years away, so we see it as it was over four years ago."] },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "How many teeth does a typical adult human have?", options: ["20", "28", "32", "40"], answer: 2, fact: "Adults normally have 32 teeth, including four wisdom teeth that surface around ages 17–25 — often too late for jaws that no longer have room for them.", src: "https://en.wikipedia.org/wiki/Human_tooth" },
  { cat: "Science", sub: "Life Sciences", diff: 3, q: "What is the hardest substance in the human body?", options: ["Bone", "Tooth enamel", "Cartilage", "Fingernail"], answer: 1, fact: "Tooth enamel is the hardest substance the body makes — about 96% mineral — but unlike bone it has no living cells, so it can't heal or regrow once damaged.", src: "https://en.wikipedia.org/wiki/Tooth_enamel" },
  { cat: "Science", sub: "Life Sciences", diff: 2, q: "Who discovered penicillin in 1928?", options: ["Louis Pasteur", "Alexander Fleming", "Joseph Lister", "Robert Koch"], answer: 1, fact: "Alexander Fleming discovered penicillin in 1928 when mould drifting onto a lab dish killed the bacteria growing around it.", src: "https://en.wikipedia.org/wiki/Penicillin", deeper: ["It was a lucky accident — Fleming had left culture dishes out while away and returned to find a tell-tale clear ring around the mould.", "Turning it into a usable medicine took another decade and the urgency of World War II, work led by Howard Florey and Ernst Chain."] },
  { cat: "Science", sub: "Life Sciences", diff: 3, q: "A deficiency of vitamin C causes which disease?", options: ["Rickets", "Scurvy", "Anaemia", "Beriberi"], answer: 1, fact: "Scurvy comes from a lack of vitamin C, which the body can't make or store long-term — it makes gums bleed and old wounds reopen.", src: "https://en.wikipedia.org/wiki/Scurvy", deeper: ["On long voyages scurvy could kill more sailors than storms or battles, before its link to fresh food was understood.", "British ships began issuing lime and lemon juice to prevent it — which is how British sailors earned the nickname 'limeys'."] },

  // ---------- GEOGRAPHY ----------
  { cat: "Geography", sub: "Landscapes", diff: 1, kids: true, q: "What is the largest ocean on Earth?", options: ["Atlantic", "Indian", "Arctic", "Pacific"], answer: 3, fact: "The Pacific is bigger than all Earth's land area combined.", src: "https://en.wikipedia.org/wiki/Pacific_Ocean" },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, q: "Which country has the most time zones?", options: ["Russia", "USA", "China", "France"], answer: 3, fact: "France, counting overseas territories, spans 12 time zones — more than any other country.", src: "https://en.wikipedia.org/wiki/Time_in_France" },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Mount Everest sits on the border of Nepal and which country?", options: ["India", "China", "Bhutan", "Pakistan"], answer: 1, fact: "Everest grows about 4 mm taller each year as tectonic plates keep colliding.", src: "https://en.wikipedia.org/wiki/Mount_Everest" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "The Sahara Desert is located primarily on which continent?", options: ["Asia", "Australia", "Africa", "South America"], answer: 2, fact: "The Sahara is roughly the size of the entire United States.", src: "https://en.wikipedia.org/wiki/Sahara" },
  { cat: "Geography", sub: "Countries & Flags", diff: 3, q: "What is the capital of Australia?", options: ["Sydney", "Melbourne", "Canberra", "Perth"], answer: 2, fact: "Canberra was purpose-built as a compromise between rivals Sydney and Melbourne.", src: "https://en.wikipedia.org/wiki/Canberra" },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "The Amazon River flows mainly through which country?", options: ["Colombia", "Peru", "Brazil", "Venezuela"], answer: 2, fact: "The Amazon discharges more water than the next seven largest rivers combined.", src: "https://en.wikipedia.org/wiki/Amazon_River" },
  { cat: "Geography", sub: "Landscapes", diff: 3, kids: true, q: "Which is the only country that is also a continent?", options: ["Greenland", "Australia", "Antarctica", "Iceland"], answer: 1, fact: "Australia is the smallest continent — because it counts as a continent, Greenland gets the title of world's largest island.", src: "https://en.wikipedia.org/wiki/List_of_islands_by_area" },
  { cat: "Geography", sub: "Landscapes", diff: 1, kids: true, q: "Which river runs through Egypt's capital, Cairo?", options: ["Tigris", "Nile", "Euphrates", "Congo"], answer: 1, fact: "The Nile is about 6,650 km long and fed one of humanity's earliest great civilizations.", src: "https://en.wikipedia.org/wiki/Nile" },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country is the largest in the world by area?", options: ["Canada", "Russia", "China", "United States"], answer: 1, fact: "Russia spans 11 time zones — the Trans-Siberian train from Moscow to Vladivostok takes about a week.", src: "https://en.wikipedia.org/wiki/Time_in_Russia" },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "What is the capital of Japan?", options: ["Kyoto", "Osaka", "Tokyo", "Hiroshima"], answer: 2, fact: "Tokyo means 'eastern capital' — the emperor moved there in 1868 from Kyoto, Japan's capital for over 1,000 years.", src: "https://en.wikipedia.org/wiki/Tokyo" },
  { cat: "Geography", sub: "Landscapes", diff: 1, kids: true, q: "Which continent is the coldest on Earth?", options: ["Asia", "North America", "Europe", "Antarctica"], answer: 3, fact: "Antarctica is technically Earth's largest desert — some of its Dry Valleys haven't seen rain in nearly 2 million years.", src: "https://en.wikipedia.org/wiki/Antarctica" },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which imaginary line circles Earth exactly halfway between the poles?", options: ["The Equator", "The Prime Meridian", "The Tropic of Cancer", "The International Date Line"], answer: 0, fact: "You weigh about 0.5% less at the Equator than at the poles — Earth's spin and bulge weaken gravity's pull there.", src: "https://en.wikipedia.org/wiki/Gravity_of_Earth" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "What is the longest mountain range on land?", options: ["The Himalayas", "The Andes", "The Rocky Mountains", "The Alps"], answer: 1, fact: "The Andes stretch about 7,000 km through seven countries and contain the world's highest volcanoes.", src: "https://en.wikipedia.org/wiki/Andes" },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Nairobi is the capital of which African country?", options: ["Tanzania", "Ethiopia", "Kenya", "Uganda"], answer: 2, fact: "Nairobi has a national park where wild lions and giraffes roam within sight of downtown skyscrapers.", src: "https://en.wikipedia.org/wiki/Nairobi_National_Park" },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, q: "Which two countries share the longest land border in the world?", options: ["Russia and China", "United States and Canada", "Argentina and Chile", "United States and Mexico"], answer: 1, fact: "The border includes 'the Slash' — a 6-metre-wide treeless strip clear-cut through thousands of kilometres of forest.", src: "https://en.wikipedia.org/wiki/Canada%E2%80%93United_States_border" },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, q: "The Strait of Gibraltar separates Spain from which country?", options: ["Algeria", "Tunisia", "Portugal", "Morocco"], answer: 3, fact: "At its narrowest the strait is only about 13 km wide — on a clear day, you can see Africa from Europe.", src: "https://en.wikipedia.org/wiki/Strait_of_Gibraltar" },
  { cat: "Geography", sub: "Landscapes", diff: 2, q: "Where is Lake Baikal, the deepest lake on Earth?", options: ["Russia", "Canada", "Mongolia", "China"], answer: 0, fact: "Baikal holds about one-fifth of Earth's unfrozen fresh surface water — more than all five North American Great Lakes combined.", src: "https://en.wikipedia.org/wiki/Lake_Baikal" },
  { cat: "Geography", sub: "Cities & Places", diff: 3, q: "How many capital cities does South Africa have?", options: ["One", "Two", "Three", "Four"], answer: 2, fact: "Pretoria is the executive capital, Cape Town the legislative, and Bloemfontein the judicial — a compromise from 1910.", src: "https://en.wikipedia.org/wiki/Pretoria" },
  { cat: "Geography", sub: "Landscapes", diff: 3, q: "What is the driest non-polar desert on Earth?", options: ["Gobi", "Kalahari", "Atacama", "Mojave"], answer: 2, fact: "Parts of the Atacama have never recorded rainfall — NASA uses its Mars-like soil to test rover instruments.", src: "https://en.wikipedia.org/wiki/Atacama_Desert" },
  { cat: "Geography", sub: "Countries & Flags", diff: 3, q: "Which country is 'doubly landlocked' — surrounded only by other landlocked countries?", options: ["Mongolia", "Uzbekistan", "Bolivia", "Nepal"], answer: 1, fact: "Only two doubly landlocked countries exist: Uzbekistan and tiny Liechtenstein, tucked in the Alps.", src: "https://en.wikipedia.org/wiki/Landlocked_country" },

  // -- verified batch: geography30 --
  { cat: "Geography", sub: "Cities & Places", diff: 1, kids: true, q: "Which European country is famously shaped like a boot?", options: ["Spain", "Italy", "Greece", "Portugal"], answer: 1, fact: "Italy also owns the Mediterranean's two largest islands — Sicily, the biggest, and Sardinia, the runner-up.", src: "https://en.wikipedia.org/wiki/Sardinia" },
  { cat: "Geography", sub: "Cities & Places", diff: 1, kids: true, q: "What is the smallest country in the world?", options: ["Vatican City", "Monaco", "San Marino", "Liechtenstein"], answer: 0, fact: "Vatican City covers just 0.49 km² and is the only country in the world with fewer than 1,000 residents.", src: "https://en.wikipedia.org/wiki/Vatican_City", deeper: ["It only became an independent state in 1929, through the Lateran Treaty between the Holy See and Italy.", "It prints its own stamps, runs its own radio station, and has the world's shortest national railway."] },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "A red maple leaf appears on the flag of which country?", options: ["Canada", "Denmark", "Switzerland", "United States"], answer: 0, fact: "The leaf's 11 points mean nothing — the design won partly because wind-tunnel tests showed it stayed least blurry in high wind. It debuted in 1965.", src: "https://en.wikipedia.org/wiki/Flag_of_Canada" },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "The Great Barrier Reef lies off the coast of which country?", options: ["Indonesia", "Philippines", "Australia", "Mexico"], answer: 2, fact: "Stretching over 2,300 km, the reef is the world's biggest single structure made by living organisms — and it can be seen from outer space.", src: "https://en.wikipedia.org/wiki/Great_Barrier_Reef" },
  { cat: "Geography", sub: "Cities & Places", diff: 1, kids: true, q: "In which city does the Eiffel Tower stand?", options: ["Rome", "Brussels", "London", "Paris"], answer: 3, fact: "On hot days the iron expands — the tower's top can lean up to 18 cm away from the sun as the heated side stretches.", src: "https://en.wikipedia.org/wiki/Eiffel_Tower" },
  { cat: "Geography", sub: "Landscapes", diff: 1, kids: true, q: "What is the smallest of Earth's oceans?", options: ["Arctic", "Indian", "Atlantic", "Southern"], answer: 0, fact: "There is no land at the North Pole — unlike the South Pole, it sits mid-ocean on constantly shifting sea ice, so no permanent station can be built there.", src: "https://en.wikipedia.org/wiki/North_Pole" },
  { cat: "Geography", sub: "Landscapes", diff: 1, kids: true, q: "Which river flows through the middle of London?", options: ["Severn", "Mersey", "Thames", "Trent"], answer: 2, fact: "Through London the Thames is tidal, rising and falling up to 7 m twice a day — the Thames Barrier at Woolwich shields the city from surges.", src: "https://en.wikipedia.org/wiki/Tideway" },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Mount Fuji is the highest mountain of which country?", options: ["China", "Japan", "South Korea", "Vietnam"], answer: 1, fact: "Fuji is not just a pretty peak — it's an active stratovolcano whose last eruption ran from 1707 to 1708.", src: "https://en.wikipedia.org/wiki/Mount_Fuji" },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "What is the largest US state by area?", options: ["Texas", "California", "Alaska", "Montana"], answer: 2, fact: "The US bought Alaska from Russia in 1867 for $7.2 million — about 2 cents per acre.", src: "https://en.wikipedia.org/wiki/Alaska_Purchase", deeper: ["Critics dubbed the deal 'Seward's Folly' after the Secretary of State who arranged it — then gold strikes and oil proved him right.", "The purchase added 586,412 square miles — more land than Texas, California and Montana combined."] },
  { cat: "Geography", sub: "Landscapes", diff: 1, kids: true, q: "Which ocean lies between Africa and Australia?", options: ["Atlantic", "Pacific", "Arctic", "Indian"], answer: 3, fact: "The Indian Ocean is the warmest of the world's oceans — and the third largest, covering about 70 million km².", src: "https://en.wikipedia.org/wiki/Indian_Ocean" },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's national flag is shaped like two stacked triangles?", options: ["Bhutan", "Sri Lanka", "Nepal", "Mongolia"], answer: 2, fact: "It's the only non-rectangular national flag on Earth — and Nepal's constitution devotes a whole section to exact instructions for drawing it.", src: "https://en.wikipedia.org/wiki/Flag_of_Nepal", deeper: ["Until 1962 the flag's sun and moon emblems had human faces; they were removed to modernise the design.", "The sun and moon express the hope that Nepal will endure as long as those bodies remain in the sky."] },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "What is the capital city of Canada?", options: ["Toronto", "Ottawa", "Vancouver", "Montreal"], answer: 1, fact: "Each winter a 7.8 km stretch of Ottawa's Rideau Canal freezes into the world's largest naturally frozen ice rink — a Guinness World Record.", src: "https://en.wikipedia.org/wiki/Rideau_Canal" },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, q: "What is the capital of New Zealand?", options: ["Wellington", "Auckland", "Christchurch", "Queenstown"], answer: 0, fact: "At latitude 41°S, Wellington is the southernmost capital city of any sovereign state on Earth.", src: "https://en.wikipedia.org/wiki/Wellington" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, q: "Which purpose-built city took over as Brazil's capital in 1960?", options: ["Rio de Janeiro", "São Paulo", "Salvador", "Brasília"], answer: 3, fact: "Brasília was raised from empty savanna in just 41 months, inaugurated in 1960 — and its street plan is shaped like an airplane.", src: "https://en.wikipedia.org/wiki/Bras%C3%ADlia", deeper: ["Urban planner Lúcio Costa laid out the 'Pilot Plan'; architect Oscar Niemeyer designed most of the public buildings.", "In 1987 UNESCO made Brasília a World Heritage Site for its modernist design — barely 27 years after the city opened."] },
  { cat: "Geography", sub: "Landscapes", diff: 2, q: "The city of Istanbul is split between which two continents?", options: ["Europe and Asia", "Africa and Asia", "Europe and Africa", "Asia and Australia"], answer: 0, fact: "For all its fame, Istanbul is not Turkey's capital — Ankara is. The city was Byzantium, then Constantinople, before officially becoming İstanbul in 1930.", src: "https://en.wikipedia.org/wiki/Istanbul" },
  { cat: "Geography", sub: "Landscapes", diff: 2, q: "Victoria Falls thunders down on which African river?", options: ["Congo", "Niger", "Zambezi", "Limpopo"], answer: 2, fact: "Its spray can rise over 400 m and be seen 50 km away — the local name Mosi-oa-Tunya means 'the smoke that thunders.'", src: "https://en.wikipedia.org/wiki/Victoria_Falls" },
  { cat: "Geography", sub: "Landscapes", diff: 2, q: "What is Africa's largest lake by area?", options: ["Lake Tanganyika", "Lake Victoria", "Lake Malawi", "Lake Chad"], answer: 1, fact: "Lake Victoria is also the world's largest tropical lake — and its outflow at Jinja, Uganda, launches the longest branch of the Nile.", src: "https://en.wikipedia.org/wiki/Lake_Victoria" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "The Panama Canal links the Pacific Ocean with which other ocean?", options: ["Atlantic Ocean", "Indian Ocean", "Arctic Ocean", "Southern Ocean"], answer: 0, fact: "Ships don't cross at sea level — locks lift them 26 m up into Gatun Lake, an artificial freshwater lake, then lower them down to the far ocean.", src: "https://en.wikipedia.org/wiki/Panama_Canal", deeper: ["The canal formally opened on 15 August 1914, with the cargo ship SS Ancon making the first official transit.", "Gatun Lake was created by damming the Chagres River — when it filled, it was the largest artificial lake on Earth."] },
  { cat: "Geography", sub: "Landscapes", diff: 2, q: "The shores of which body of water are the lowest dry land on Earth?", options: ["Caspian Sea", "Dead Sea", "Great Salt Lake", "Lake Titicaca"], answer: 1, fact: "The Dead Sea is nearly ten times saltier than the ocean — so dense that swimming feels like floating, and no fish can live in it (hence the name).", src: "https://en.wikipedia.org/wiki/Dead_Sea" },
  { cat: "Geography", sub: "Landscapes", diff: 2, q: "Roughly a quarter of which European country lies below sea level?", options: ["Belgium", "Denmark", "Germany", "Netherlands"], answer: 3, fact: "The below-sea-level lands are polders, reclaimed from water — Dutch land reclamation has been under way since the 14th century.", src: "https://en.wikipedia.org/wiki/Netherlands" },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, q: "The Bering Strait separates Russia from which country?", options: ["Canada", "Japan", "United States", "Norway"], answer: 2, fact: "Mid-strait, Russia's Big Diomede and America's Little Diomede sit just 3.8 km apart — yet the date line between them puts them about 21 hours apart.", src: "https://en.wikipedia.org/wiki/Diomede_Islands", deeper: ["That's why the pair are nicknamed Tomorrow Island (Big Diomede) and Yesterday Island (Little Diomede).", "In winter an ice bridge can form between them — technically letting a person walk from the USA to Russia."] },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "What is the highest mountain in Africa?", options: ["Mount Kenya", "Mount Kilimanjaro", "Ras Dashen", "Mount Elgon"], answer: 1, fact: "Kilimanjaro is the world's tallest free-standing mountain — a dormant volcano rising alone from the plains rather than sitting in a range.", src: "https://en.wikipedia.org/wiki/Mount_Kilimanjaro", deeper: ["It's built from three volcanic cones: Kibo the highest, then Mawenzi and Shira.", "Despite standing just south of the equator, its summit carries an ice cap and Africa's largest glaciers."] },
  { cat: "Geography", sub: "Countries & Flags", diff: 3, q: "Which country is entirely surrounded by South Africa?", options: ["Eswatini", "Lesotho", "Botswana", "Zimbabwe"], answer: 1, fact: "Lesotho is the only country lying entirely above 1,000 m — its lowest point, at 1,400 m, is the highest 'low point' of any nation on Earth.", src: "https://en.wikipedia.org/wiki/Lesotho" },
  { cat: "Geography", sub: "Countries & Flags", diff: 3, q: "Which two South American countries are landlocked?", options: ["Bolivia and Paraguay", "Peru and Bolivia", "Paraguay and Uruguay", "Ecuador and Venezuela"], answer: 0, fact: "Bolivia still maintains a navy — patrolling Lake Titicaca — having lost its entire coastline to Chile in the War of the Pacific (1879–83).", src: "https://en.wikipedia.org/wiki/Bolivian_Navy", deeper: ["Lake Titicaca, which Bolivia shares with Peru, is the highest navigable lake in the world.", "The naval force was established in 1963, six decades after a 1904 treaty formalized the loss of Bolivia's coastline."] },
  { cat: "Geography", sub: "Landscapes", diff: 3, q: "Which European capital is built across 14 islands, where Lake Mälaren meets the Baltic Sea?", options: ["Copenhagen", "Helsinki", "Amsterdam", "Stockholm"], answer: 3, fact: "Just offshore begins the Stockholm archipelago — roughly 24,000 more islands and islets scattered into the Baltic Sea.", src: "https://en.wikipedia.org/wiki/Stockholm_archipelago" },
  { cat: "Geography", sub: "Landscapes", diff: 3, q: "Which is the only country with coastlines on both the Red Sea and the Persian Gulf?", options: ["Egypt", "Saudi Arabia", "Yemen", "Oman"], answer: 1, fact: "Saudi Arabia has no permanent rivers or lakes at all — the country runs on groundwater, scarce streams and desalinated seawater.", src: "https://en.wikipedia.org/wiki/Geography_of_Saudi_Arabia" },
  { cat: "Geography", sub: "Countries & Flags", diff: 3, q: "How many national capital cities sit on the Danube river?", options: ["Two", "Three", "Four", "Five"], answer: 2, fact: "They are Vienna, Bratislava, Budapest and Belgrade — the Danube crosses or borders ten countries between Germany's Black Forest and the Black Sea.", src: "https://en.wikipedia.org/wiki/Danube", deeper: ["For centuries the river marked the Roman Empire's northern frontier, studded with legionary forts.", "At its mouth it fans into the Danube Delta, a vast UNESCO-listed wetland shared by Romania and Ukraine."] },
  { cat: "Geography", sub: "Landscapes", diff: 3, q: "Where would you find Angel Falls, the tallest uninterrupted waterfall in the world?", options: ["Brazil", "Guyana", "Colombia", "Venezuela"], answer: 3, fact: "The 979 m falls are named for US aviator Jimmie Angel, whose plane bogged down atop the tepui in 1937 — his party trekked 11 days back to civilisation.", src: "https://en.wikipedia.org/wiki/Angel_Falls" },
  { cat: "Geography", sub: "Countries & Flags", diff: 3, q: "At about 3,650 m above sea level, which city is the world's highest seat of national government?", options: ["Quito", "Bogotá", "La Paz", "Kathmandu"], answer: 2, fact: "La Paz holds Bolivia's government, but the constitutional capital is Sucre, which retains the judiciary — a split-capital arrangement.", src: "https://en.wikipedia.org/wiki/La_Paz" },

  // ---------- ARTS & LETTERS ----------
  { cat: "Arts", diff: 1, kids: true, q: "Who painted the Mona Lisa?", options: ["Michelangelo", "Leonardo da Vinci", "Raphael", "Donatello"], answer: 1, fact: "The Mona Lisa has no visible eyebrows — a fashion of the era, or lost to cleaning.", src: "https://en.wikipedia.org/wiki/Mona_Lisa" },
  { cat: "Arts", diff: 2, q: "Which playwright wrote 'Hamlet'?", options: ["Christopher Marlowe", "William Shakespeare", "Ben Jonson", "Oscar Wilde"], answer: 1, fact: "Shakespeare coined or popularized over 1,700 words still used in English today.", src: "https://en.wikipedia.org/wiki/Influence_of_William_Shakespeare" },
  { cat: "Arts", diff: 2, kids: true, q: "The Starry Night was painted by which artist?", options: ["Claude Monet", "Vincent van Gogh", "Paul Cézanne", "Edvard Munch"], answer: 1, fact: "Van Gogh painted it from memory in an asylum, and sold only one painting in his lifetime.", src: "https://en.wikipedia.org/wiki/The_Starry_Night" },
  { cat: "Arts", diff: 3, kids: true, q: "Which composer continued writing music after going deaf?", options: ["Mozart", "Beethoven", "Bach", "Chopin"], answer: 1, fact: "Beethoven composed his monumental Ninth Symphony when almost completely deaf.", src: "https://en.wikipedia.org/wiki/Symphony_No._9_(Beethoven)" },
  { cat: "Arts", diff: 3, q: "'One Hundred Years of Solitude' was written by which author?", options: ["Pablo Neruda", "Gabriel García Márquez", "Jorge Luis Borges", "Isabel Allende"], answer: 1, fact: "It's the flagship of 'magical realism' and has sold over 50 million copies.", src: "https://en.wikipedia.org/wiki/One_Hundred_Years_of_Solitude" },
  { cat: "Arts", diff: 1, kids: true, q: "How many strings does a standard violin have?", options: ["Four", "Six", "Five", "Seven"], answer: 0, fact: "Those four strings can produce an astonishing range through position and bowing.", src: "https://en.wikipedia.org/wiki/Violin" },
  { cat: "Arts", diff: 2, q: "The Sistine Chapel ceiling was painted by whom?", options: ["Raphael", "Michelangelo", "Botticelli", "Titian"], answer: 1, fact: "Michelangelo spent about four years painting it, mostly standing and craning upward — not lying down.", src: "https://en.wikipedia.org/wiki/Sistine_Chapel_ceiling" },
  { cat: "Arts", diff: 3, kids: true, q: "Which ballet features 'The Dance of the Sugar Plum Fairy'?", options: ["Swan Lake", "The Nutcracker", "Giselle", "The Firebird"], answer: 1, fact: "Tchaikovsky used the then-new celesta for its shimmering, music-box tone.", src: "https://en.wikipedia.org/wiki/Celesta" },
  { cat: "Arts", diff: 1, kids: true, q: "What is a painting of a person's face and shoulders called?", options: ["Portrait", "Landscape", "Still life", "Mural"], answer: 0, fact: "A portrait an artist makes of themselves is a self-portrait — Rembrandt made around 80 of them, a visual diary of his whole adult life.", src: "https://en.wikipedia.org/wiki/Self-portraits_by_Rembrandt" },
  { cat: "Arts", diff: 1, kids: true, q: "How many keys does a standard modern piano have?", options: ["66", "76", "88", "96"], answer: 2, fact: "The piano's full name is 'pianoforte' — Italian for 'soft-loud' — because unlike the harpsichord it could play both gently and thunderously.", src: "https://en.wikipedia.org/wiki/Piano" },
  { cat: "Arts", diff: 1, kids: true, q: "Which ancient Greek epic poem follows the hero Odysseus's long sea journey home?", options: ["The Iliad", "The Odyssey", "The Aeneid", "Beowulf"], answer: 1, fact: "The hero's name gave English the word 'odyssey' — and the poem famously begins in the middle of the story, a trick called 'in medias res'.", src: "https://en.wikipedia.org/wiki/Odyssey" },
  { cat: "Arts", diff: 1, kids: true, q: "The Beatles formed in which English city?", options: ["London", "Manchester", "Birmingham", "Liverpool"], answer: 3, fact: "In one week of April 1964, The Beatles became the first act ever to hold all five top spots on the US Billboard singles chart.", src: "https://en.wikipedia.org/wiki/Can%27t_Buy_Me_Love" },
  { cat: "Arts", diff: 2, kids: true, q: "Who created the famous Japanese woodblock print 'The Great Wave off Kanagawa'?", options: ["Utagawa Hiroshige", "Katsushika Hokusai", "Kitagawa Utamaro", "Yayoi Kusama"], answer: 1, fact: "Hokusai made it in his early seventies for the series 'Thirty-six Views of Mount Fuji' — Fuji is the tiny peak behind the towering wave.", src: "https://en.wikipedia.org/wiki/The_Great_Wave_off_Kanagawa" },
  { cat: "Arts", diff: 2, kids: true, q: "Mexican painter Frida Kahlo is most famous for which kind of artwork?", options: ["Stained glass windows", "Marble sculptures", "Self-portraits", "Watercolour seascapes"], answer: 2, fact: "After a bus accident at 18, Kahlo began painting in bed with a mirror fixed overhead — about a third of her works show her own face.", src: "https://en.wikipedia.org/wiki/Frida_Kahlo" },
  { cat: "Arts", diff: 2, q: "Who is the storyteller who narrates the tales of 'One Thousand and One Nights'?", options: ["Aladdin", "Sinbad the Sailor", "Scheherazade", "Morgiana"], answer: 2, fact: "Aladdin and Ali Baba are missing from the earliest Arabic manuscripts — French translator Antoine Galland added those tales in the early 1700s.", src: "https://en.wikipedia.org/wiki/One_Thousand_and_One_Nights" },
  { cat: "Arts", diff: 2, q: "An architect from which country designed the Sydney Opera House?", options: ["Denmark", "Australia", "United States", "Brazil"], answer: 0, fact: "Danish architect Jørn Utzon resigned mid-build in 1966 and never returned to see his masterpiece finished — it finally opened in 1973.", src: "https://en.wikipedia.org/wiki/Sydney_Opera_House" },
  { cat: "Arts", diff: 2, q: "Which artist painted 'The Scream'?", options: ["Gustav Klimt", "Salvador Dalí", "Wassily Kandinsky", "Edvard Munch"], answer: 3, fact: "Munch made four versions of The Scream; two were stolen from Oslo museums in 1994 and 2004, and both were eventually recovered.", src: "https://en.wikipedia.org/wiki/The_Scream" },
  { cat: "Arts", diff: 3, q: "'The Tale of Genji', often called the world's first novel, was written in which country?", options: ["China", "Persia", "Japan", "Korea"], answer: 2, fact: "Murasaki Shikibu, a lady-in-waiting at Japan's imperial court, wrote it around 1000 CE — centuries before the printing press reached Europe.", src: "https://en.wikipedia.org/wiki/The_Tale_of_Genji" },
  { cat: "Arts", diff: 3, q: "Which Nigerian writer's 1958 novel 'Things Fall Apart' became a classic of world literature?", options: ["Wole Soyinka", "Chinua Achebe", "Ben Okri", "Buchi Emecheta"], answer: 1, fact: "Achebe took the title from a W.B. Yeats poem, 'The Second Coming'; the novel has been translated into more than 50 languages.", src: "https://en.wikipedia.org/wiki/Things_Fall_Apart" },
  { cat: "Arts", diff: 3, q: "Which architect designed New York's spiral-shaped Guggenheim Museum?", options: ["Frank Gehry", "Le Corbusier", "Zaha Hadid", "Frank Lloyd Wright"], answer: 3, fact: "Wright wanted visitors to ride the lift up and stroll down the spiral ramp; the museum opened in 1959, six months after his death.", src: "https://en.wikipedia.org/wiki/Solomon_R._Guggenheim_Museum" },

  // ---------- TECH & MATH ----------
  { cat: "Tech", diff: 1, q: "What does 'HTTP' stand for?", options: ["HyperText Transfer Protocol", "High Transfer Text Program", "Hyperlink Text Transit Path", "Home Tool Transfer Protocol"], answer: 0, fact: "HTTP was invented by Tim Berners-Lee around 1989–91, along with the first web browser." , src: "https://en.wikipedia.org/wiki/HTTP" },
  { cat: "Tech", diff: 2, q: "In binary, what number does '1010' represent?", options: ["8", "10", "12", "5"], answer: 1, fact: "Each place doubles: 8 + 0 + 2 + 0 = 10." , src: "https://en.wikipedia.org/wiki/Binary_number" },
  { cat: "Tech", diff: 3, kids: true, q: "Who is often called the first computer programmer?", options: ["Grace Hopper", "Ada Lovelace", "Alan Turing", "Charles Babbage"], answer: 1, fact: "In the 1840s Ada Lovelace wrote an algorithm for Babbage's never-built Analytical Engine." , src: "https://en.wikipedia.org/wiki/Ada_Lovelace" },
  { cat: "Tech", diff: 2, kids: true, q: "What is the value of pi (π) to two decimals?", options: ["3.14", "3.41", "2.72", "1.62"], answer: 0, fact: "Pi has been computed to over 100 trillion digits, yet 15 digits suffice for most engineering." , src: "https://en.wikipedia.org/wiki/Pi" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: true, q: "A prime number is divisible only by 1 and what?", options: ["Zero", "Itself", "Two", "Ten"], answer: 1, fact: "2 is the only even prime — every other even number is divisible by 2." , src: "https://en.wikipedia.org/wiki/Prime_number" },
  { cat: "Tech", diff: 1, kids: true, q: "What does 'CPU' stand for?", options: ["Central Processing Unit", "Computer Power Unit", "Central Program Utility", "Core Processing Unit"], answer: 0, fact: "Modern CPUs can perform billions of operations per second across multiple cores." , src: "https://en.wikipedia.org/wiki/Central_processing_unit" },
  { cat: "Tech", diff: 3, kids: true, q: "What is the next number in the Fibonacci sequence: 1, 1, 2, 3, 5, 8, ...?", options: ["11", "12", "13", "15"], answer: 2, fact: "Each Fibonacci number is the sum of the two before it — 5 + 8 = 13." , src: "https://en.wikipedia.org/wiki/Fibonacci_sequence" },
  { cat: "Tech", diff: 2, q: "Which company released the first mass-market GUI personal computer, the Macintosh?", options: ["IBM", "Apple", "Microsoft", "Xerox"], answer: 1, fact: "Apple's 1984 Mac popularized ideas Xerox PARC had pioneered but never sold widely." , src: "https://en.wikipedia.org/wiki/Macintosh_128K" },
  { cat: "Tech", diff: 1, kids: true, q: "How many bits make up one byte?", options: ["4", "16", "8", "32"], answer: 2, fact: "The word 'byte' was coined at IBM in 1956 and deliberately spelled with a 'y' so a typo could never turn it into 'bit'." , src: "https://en.wikipedia.org/wiki/Byte" },
  { cat: "Tech", diff: 1, kids: true, q: "Which of these units of digital storage is the largest?", options: ["Megabyte", "Terabyte", "Kilobyte", "Gigabyte"], answer: 1, fact: "One terabyte holds about a million megabytes — and big data centers now talk in exabytes, each a million terabytes." , src: "https://en.wikipedia.org/wiki/Units_of_information" },
  { cat: "Tech", diff: 1, kids: true, q: "What was the shell of the very first computer mouse made of?", options: ["Plastic", "Rubber", "Wood", "Glass"], answer: 2, fact: "Inventor Douglas Engelbart's team named it 'mouse' because the cord trailing out the back looked like a tail." , src: "https://en.wikipedia.org/wiki/Computer_mouse" },
  { cat: "Tech", diff: 1, kids: true, q: "Which of these programs is a web browser?", options: ["Excel", "Chrome", "Photoshop", "Spotify"], answer: 1, fact: "The first hit browser, Mosaic (1993), popularized showing pictures inside the page instead of in separate windows." , src: "https://en.wikipedia.org/wiki/Google_Chrome" },
  { cat: "Tech", diff: 2, q: "In which decade was the first email sent over the ARPANET?", options: ["1950s", "1960s", "1970s", "1990s"], answer: 2, fact: "Ray Tomlinson picked the @ symbol to separate user from machine, and recalled his first test message as something like 'QWERTYUIOP'." , src: "https://en.wikipedia.org/wiki/Ray_Tomlinson" },
  { cat: "Tech", diff: 2, q: "What was the name of the room-sized electronic computer unveiled at the University of Pennsylvania in 1946?", options: ["UNIVAC", "Colossus", "EDSAC", "ENIAC"], answer: 3, fact: "ENIAC weighed about 27 tonnes — and its six original programmers were all women, hired as mathematicians." , src: "https://en.wikipedia.org/wiki/ENIAC" },
  { cat: "Tech", diff: 2, kids: true, q: "In Morse code, what pattern makes up the distress signal 'SOS'?", options: ["Three dots, three dashes, three dots", "Three dashes, three dots, three dashes", "Six dots and six dashes", "Nine dashes in a row"], answer: 0, fact: "SOS doesn't stand for anything — it was adopted in 1906 simply because the pattern is quick to send and hard to mistake." , src: "https://en.wikipedia.org/wiki/SOS" },
  { cat: "Tech", diff: 2, kids: true, q: "The QWERTY keyboard layout was originally designed for which machine?", options: ["Typewriter", "Telegraph", "Cash register", "Printing press"], answer: 0, fact: "'Typewriter' is one of the longest common English words you can type using only QWERTY's top row of letters." , src: "https://en.wikipedia.org/wiki/QWERTY" },
  { cat: "Tech", diff: 2, q: "Computer chips are built from silicon — refined from what common material?", options: ["Sand", "Coal", "Clay", "Seawater"], answer: 0, fact: "Chip-grade silicon must be 99.9999999% pure — 'nine nines', among the purest materials humans have ever made." , src: "https://en.wikipedia.org/wiki/Silicon" },
  { cat: "Tech", diff: 3, q: "In the hexadecimal number system, what value does the digit 'F' represent?", options: ["16", "10", "12", "15"], answer: 3, fact: "Two hex digits describe exactly one byte — that's why web colors like #FF6600 are written with six of them." , src: "https://en.wikipedia.org/wiki/Hexadecimal" },
  { cat: "Tech", diff: 3, q: "The famous test of whether a machine can pass as human in conversation is named after whom?", options: ["John von Neumann", "Alan Turing", "Claude Shannon", "Marvin Minsky"], answer: 1, fact: "Turing's 1950 paper opened with 'Can machines think?' — then swapped that question for his 'imitation game'." , src: "https://en.wikipedia.org/wiki/Turing_test" },
  { cat: "Tech", diff: 3, q: "In 1969 the first ARPANET link connected UCLA to which other institution?", options: ["MIT", "Harvard", "Bell Labs", "Stanford Research Institute"], answer: 3, fact: "The first message was meant to be 'LOGIN', but the system crashed after two letters — so the internet era began with 'LO'." , src: "https://en.wikipedia.org/wiki/ARPANET" },

  // ---------- NATURE ----------
  { cat: "Nature", diff: 1, kids: true, q: "What is the largest animal ever known to have lived?", options: ["African elephant", "Blue whale", "Argentinosaurus", "Giant squid"], answer: 1, fact: "A blue whale's heart alone can weigh as much as a small car." , src: "https://en.wikipedia.org/wiki/Blue_whale" },
  { cat: "Nature", diff: 2, kids: true, q: "Which is the only mammal capable of true sustained flight?", options: ["Flying squirrel", "Bat", "Sugar glider", "Colugo"], answer: 1, fact: "Bats make up about a fifth of all mammal species." , src: "https://en.wikipedia.org/wiki/Bat" },
  { cat: "Nature", diff: 2, kids: true, q: "How many hearts does an octopus have?", options: ["One", "Two", "Three", "Four"], answer: 2, fact: "Two hearts pump blood to the gills, one to the body — and their blood is blue." , src: "https://en.wikipedia.org/wiki/Octopus" },
  { cat: "Nature", diff: 1, kids: true, q: "What do bees collect to make honey?", options: ["Pollen", "Nectar", "Sap", "Water"], answer: 1, fact: "A single bee makes about 1/12 of a teaspoon of honey in its entire life." , src: "https://en.wikipedia.org/wiki/Honey_bee" },
  { cat: "Nature", diff: 3, kids: true, q: "Which tree species is the tallest living thing on Earth?", options: ["Giant sequoia", "Coast redwood", "Douglas fir", "Eucalyptus"], answer: 1, fact: "The tallest coast redwood, 'Hyperion', stands over 115 metres — taller than the Statue of Liberty." , src: "https://en.wikipedia.org/wiki/Sequoia_sempervirens" },
  { cat: "Nature", diff: 2, kids: true, q: "A group of lions is called a what?", options: ["Pack", "Herd", "Pride", "Colony"], answer: 2, fact: "Lions are the only truly social big cats, living in prides of related females." , src: "https://en.wikipedia.org/wiki/Lion" },
  { cat: "Nature", diff: 3, kids: true, q: "Which animal has the longest known migration?", options: ["Monarch butterfly", "Arctic tern", "Humpback whale", "Caribou"], answer: 1, fact: "The Arctic tern flies pole to pole, over 70,000 km a year — seeing two summers annually." , src: "https://en.wikipedia.org/wiki/Arctic_tern" },
  { cat: "Nature", diff: 1, kids: true, q: "What is the fastest land animal?", options: ["Lion", "Cheetah", "Pronghorn", "Greyhound"], answer: 1, fact: "A cheetah can go 0–100 km/h in about three seconds — faster acceleration than most sports cars." , src: "https://en.wikipedia.org/wiki/Cheetah" },
  { cat: "Nature", diff: 1, kids: true, q: "What is the largest land animal alive today?", options: ["African elephant", "Hippopotamus", "White rhinoceros", "Giraffe"], answer: 0, fact: "An elephant's trunk has no bones but around 40,000 muscles — the entire human body has only about 600." , src: "https://en.wikipedia.org/wiki/African_bush_elephant" },
  { cat: "Nature", diff: 1, kids: true, q: "What do we call an animal that eats only plants?", options: ["Carnivore", "Omnivore", "Herbivore", "Insectivore"], answer: 2, fact: "Plant-eaters often have far longer intestines than meat-eaters, giving tough fibre more time to break down." , src: "https://en.wikipedia.org/wiki/Herbivore" },
  { cat: "Nature", diff: 1, kids: true, q: "Which is the largest species of big cat?", options: ["Lion", "Jaguar", "Tiger", "Leopard"], answer: 2, fact: "No two tigers share the same stripe pattern — and the stripes go right down to their skin, not just the fur." , src: "https://en.wikipedia.org/wiki/Tiger" },
  { cat: "Nature", diff: 1, kids: true, q: "How many legs does an insect have?", options: ["Four", "Six", "Eight", "Ten"], answer: 1, fact: "Every insect has six legs and three body parts; spiders have eight legs and aren't insects at all." , src: "https://en.wikipedia.org/wiki/Insect" },
  { cat: "Nature", diff: 2, q: "On the Mohs scale of hardness, which of these minerals is the hardest?", options: ["Corundum", "Quartz", "Topaz", "Diamond"], answer: 3, fact: "Natural diamonds form about 150 km underground and ride to the surface in rare, deep volcanic eruptions." , src: "https://en.wikipedia.org/wiki/Diamond" },
  { cat: "Nature", diff: 2, kids: true, q: "Which food, if sealed properly, essentially never spoils?", options: ["Bread", "Honey", "Cheese", "Rice"], answer: 1, fact: "Archaeologists have found honey in ancient Egyptian tombs still perfectly edible — its low moisture and acidity block microbes." , src: "https://en.wikipedia.org/wiki/Honey" },
  { cat: "Nature", diff: 2, kids: true, q: "What is a baby kangaroo called?", options: ["Cub", "Kit", "Joey", "Calf"], answer: 2, fact: "A newborn joey is about the size of a jellybean and crawls unaided into its mother's pouch to keep growing." , src: "https://en.wikipedia.org/wiki/Kangaroo" },
  { cat: "Nature", diff: 2, kids: true, q: "What is the largest living bird?", options: ["Andean condor", "Emu", "Albatross", "Ostrich"], answer: 3, fact: "An ostrich's eye is about 5 cm across — larger than its own brain." , src: "https://en.wikipedia.org/wiki/Common_ostrich" },
  { cat: "Nature", diff: 2, q: "What is a violently rotating column of air that touches the ground called?", options: ["Hurricane", "Cyclone", "Tornado", "Typhoon"], answer: 2, fact: "The strongest tornadoes pack winds over 480 km/h — the fastest winds ever measured near Earth's surface." , src: "https://en.wikipedia.org/wiki/Tornado" },
  { cat: "Nature", diff: 3, q: "Which tree includes the oldest known living individual, nearly 4,900 years old?", options: ["Coast redwood", "Bristlecone pine", "Baobab", "English oak"], answer: 1, fact: "A bristlecone named 'Methuselah' sprouted around 2833 BCE — before the Great Pyramid of Giza was finished." , src: "https://en.wikipedia.org/wiki/Bristlecone_pine" },
  { cat: "Nature", diff: 3, q: "Where would you find the Challenger Deep, the ocean's deepest point?", options: ["Puerto Rico Trench", "Mariana Trench", "Java Trench", "Tonga Trench"], answer: 1, fact: "It lies about 10,935 m down — deeper than Everest is tall, under more than 1,000 times sea-level pressure." , src: "https://en.wikipedia.org/wiki/Challenger_Deep" },
  { cat: "Nature", diff: 3, q: "Which is the largest living reptile?", options: ["Komodo dragon", "Green anaconda", "Saltwater crocodile", "Galapagos tortoise"], answer: 2, fact: "The saltwater crocodile has the strongest bite ever measured in a living animal — about 3,700 pounds of force." , src: "https://en.wikipedia.org/wiki/Saltwater_crocodile" },

  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["South Korea", "Indonesia", "Vietnam", "Japan"], answer: 3, fact: "Japan had no legally defined national flag until 1999 — for 130 years it was simply the one everybody used.", src: "https://en.wikipedia.org/wiki/Flag_of_Japan", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Flag_of_Japan.svg/960px-Flag_of_Japan.svg.png", "by": "Various", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Japan.svg", "fit": "contain", "alt": "A white flag with a large red circle in the centre.", "alt_fr": "Un drapeau blanc portant un grand cercle rouge en son centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Nepal", "South Korea", "Mongolia", "Vietnam"], answer: 1, fact: "The four corner symbols are trigrams from the I Ching, and they stand for heaven, earth, fire and water.", src: "https://en.wikipedia.org/wiki/Flag_of_South_Korea", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Flag_of_South_Korea.svg/960px-Flag_of_South_Korea.svg.png", "by": "Original: Government of the Republic of Korea Vector:  Great Brightsta", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_South_Korea.svg", "fit": "contain", "alt": "A white flag with a red-and-blue circular symbol in the centre and four groups of black bars in the corners.", "alt_fr": "Un drapeau blanc avec un symbole circulaire rouge et bleu au centre et quatre groupes de barres noires aux angles."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["South Korea", "Vietnam", "Bangladesh", "Indonesia"], answer: 1, fact: "The design was first flown in a failed 1940 uprising, five years before the country it now represents existed.", src: "https://en.wikipedia.org/wiki/Flag_of_Vietnam", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Flag_of_Vietnam.svg/960px-Flag_of_Vietnam.svg.png", "by": "See File history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Vietnam.svg", "fit": "contain", "alt": "A red flag with a single large yellow five-pointed star in the centre.", "alt_fr": "Un drapeau rouge portant une seule grande étoile jaune à cinq branches au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["India", "Thailand", "Vietnam", "Mongolia"], answer: 1, fact: "The old flag showed a white elephant. It was changed after being flown upside down in front of the king.", src: "https://en.wikipedia.org/wiki/Flag_of_Thailand", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Flag_of_Thailand.svg/960px-Flag_of_Thailand.svg.png", "by": "Zscout370", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Thailand.svg", "fit": "contain", "alt": "Five horizontal bands: red, white, a thicker blue centre, white, red.", "alt_fr": "Cinq bandes horizontales : rouge, blanc, une bande bleue centrale plus large, blanc, rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["South Korea", "Nepal", "Thailand", "Kazakhstan"], answer: 1, fact: "It is the only national flag on Earth that is not a rectangle, and its exact shape is defined in the constitution by geometric construction.", src: "https://en.wikipedia.org/wiki/Flag_of_Nepal", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Flag_of_Nepal.svg/960px-Flag_of_Nepal.svg.png", "by": "Drawn by Pumbaa80, Achim1999", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Nepal.svg", "fit": "contain", "alt": "The only non-rectangular national flag: two stacked crimson pennants with a blue border, bearing a white moon and a white sun.", "alt_fr": "Le seul drapeau national non rectangulaire : deux fanions cramoisis superposés bordés de bleu, portant une lune et un soleil blancs."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Philippines", "Bangladesh", "India", "Mongolia"], answer: 2, fact: "The wheel replaced a spinning wheel at independence — the same object, redrawn as an ancient emperor's symbol of law.", src: "https://en.wikipedia.org/wiki/Flag_of_India", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Flag_of_India.svg/960px-Flag_of_India.svg.png", "by": "Government of India", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_India.svg", "fit": "contain", "alt": "Three horizontal bands of saffron, white and green, with a navy-blue 24-spoke wheel in the centre.", "alt_fr": "Trois bandes horizontales safran, blanche et verte, avec une roue bleu marine à 24 rayons au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["South Korea", "Bhutan", "Japan", "Bangladesh"], answer: 3, fact: "The disc sits left of centre on purpose, so that it looks centred once the flag is flying.", src: "https://en.wikipedia.org/wiki/Flag_of_Bangladesh", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Flag_of_Bangladesh.svg/960px-Flag_of_Bangladesh.svg.png", "by": "See File history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Bangladesh.svg", "fit": "contain", "alt": "A dark green flag with a red circle set slightly left of centre.", "alt_fr": "Un drapeau vert foncé avec un cercle rouge légèrement décalé vers la gauche."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Philippines", "South Korea", "Indonesia", "Cambodia"], answer: 2, fact: "It is almost identical to Monaco's, which is older — the two countries simply agreed to live with it.", src: "https://en.wikipedia.org/wiki/Flag_of_Indonesia", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Flag_of_Indonesia.svg/960px-Flag_of_Indonesia.svg.png", "by": "Jayakatwang", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Indonesia.svg", "fit": "contain", "alt": "Two horizontal bands, red above white.", "alt_fr": "Deux bandes horizontales, rouge au-dessus de blanc."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Kazakhstan", "Nepal", "Mongolia", "Philippines"], answer: 3, fact: "It is flown upside down in wartime — the only national flag with a deliberate second, official meaning.", src: "https://en.wikipedia.org/wiki/Flag_of_the_Philippines", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Flag_of_the_Philippines.svg/960px-Flag_of_the_Philippines.svg.png", "by": "See File history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_the_Philippines.svg", "fit": "contain", "alt": "A white triangle at the hoist bearing a golden sun and three stars, beside horizontal blue and red bands.", "alt_fr": "Un triangle blanc au guindant portant un soleil doré et trois étoiles, à côté de bandes horizontales bleue et rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Japan", "Bhutan", "Mongolia", "Vietnam"], answer: 2, fact: "The golden symbol on the hoist, the Soyombo, is a character from an alphabet invented by a 17th-century monk.", src: "https://en.wikipedia.org/wiki/Flag_of_Mongolia", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Flag_of_Mongolia.svg/960px-Flag_of_Mongolia.svg.png", "by": "See File history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Mongolia.svg", "fit": "contain", "alt": "Three vertical bands of red, blue, red, with a golden columnar emblem on the hoist band.", "alt_fr": "Trois bandes verticales rouge, bleue, rouge, avec un emblème doré en colonne sur la bande du guindant."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Indonesia", "Bangladesh", "Kazakhstan", "Japan"], answer: 2, fact: "The pattern down the hoist is a national ornament — the flag was designed by an artist who won an open public contest.", src: "https://en.wikipedia.org/wiki/Flag_of_Kazakhstan", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Flag_of_Kazakhstan.svg/960px-Flag_of_Kazakhstan.svg.png", "by": "Shaken Niyazbekop", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Kazakhstan.svg", "fit": "contain", "alt": "A sky-blue flag with a golden sun above a soaring eagle, and a vertical golden ornamental pattern at the hoist.", "alt_fr": "Un drapeau bleu ciel avec un soleil doré au-dessus d'un aigle planant, et un motif ornemental doré vertical au guindant."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Bhutan", "India", "Thailand", "Bangladesh"], answer: 0, fact: "The dragon is holding jewels, and it is white to represent purity rather than any of the country's peoples.", src: "https://en.wikipedia.org/wiki/Flag_of_Bhutan", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Flag_of_Bhutan.svg/960px-Flag_of_Bhutan.svg.png", "by": "See File history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Bhutan.svg", "fit": "contain", "alt": "Divided diagonally yellow and orange, with a large white dragon clutching jewels across the centre.", "alt_fr": "Divisé en diagonale, jaune et orange, avec un grand dragon blanc tenant des joyaux en travers du centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Japan", "Sri Lanka", "Thailand", "Kazakhstan"], answer: 1, fact: "The two stripes were added in 1951 to represent minorities the original lion flag had left out.", src: "https://en.wikipedia.org/wiki/Flag_of_Sri_Lanka", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Flag_of_Sri_Lanka.svg/960px-Flag_of_Sri_Lanka.svg.png", "by": "Original:  Sri Lanka\nVectorization:  Zscout370, Mike Rohsopht", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Sri_Lanka.svg", "fit": "contain", "alt": "A golden lion holding a sword on a maroon field with four leaves, beside two vertical green and orange stripes.", "alt_fr": "Un lion doré tenant une épée sur fond bordeaux avec quatre feuilles, à côté de deux bandes verticales verte et orange."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["India", "Bhutan", "Thailand", "Cambodia"], answer: 3, fact: "It is the only national flag that shows a building — and that building is Angkor Wat.", src: "https://en.wikipedia.org/wiki/Flag_of_Cambodia", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Flag_of_Cambodia.svg/960px-Flag_of_Cambodia.svg.png", "by": "Unknown authorUnknown author", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Cambodia.svg", "fit": "contain", "alt": "Blue, red and blue horizontal bands with a white three-towered temple in the centre.", "alt_fr": "Bandes horizontales bleue, rouge et bleue avec un temple blanc à trois tours au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Argentina", "Brazil", "Colombia", "Canada"], answer: 1, fact: "The stars show the sky over Rio at a precise moment: the morning the republic was proclaimed in 1889.", src: "https://en.wikipedia.org/wiki/Flag_of_Brazil", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Flag_of_Brazil.svg/960px-Flag_of_Brazil.svg.png", "by": "Raimundo Teixeira Mendes", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Brazil.svg", "fit": "contain", "alt": "A green flag with a yellow diamond and a blue globe crossed by a white banner of stars.", "alt_fr": "Un drapeau vert avec un losange jaune et un globe bleu traversé d'une banderole blanche étoilée."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Jamaica", "Argentina", "Brazil", "Peru"], answer: 1, fact: "The sun face has a name — the Sun of May — and it also appears on Uruguay's flag.", src: "https://en.wikipedia.org/wiki/Flag_of_Argentina", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Flag_of_Argentina.svg/960px-Flag_of_Argentina.svg.png", "by": "Manuel Belgrano", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Argentina.svg", "fit": "contain", "alt": "Light blue, white and light blue horizontal bands with a golden sun face in the centre.", "alt_fr": "Bandes horizontales bleu clair, blanche et bleu clair avec un visage de soleil doré au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Peru", "Cuba", "Mexico", "Jamaica"], answer: 2, fact: "The scene is a founding legend: a city was to be built where an eagle was seen on a cactus, eating a snake.", src: "https://en.wikipedia.org/wiki/Flag_of_Mexico", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Flag_of_Mexico.svg/960px-Flag_of_Mexico.svg.png", "by": "Alex Covarrubias, 9 April 2006. Based on the arms by Juan Manuel Gabin", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Mexico.svg", "fit": "contain", "alt": "Green, white and red vertical bands with an eagle on a cactus in the centre.", "alt_fr": "Bandes verticales verte, blanche et rouge avec un aigle sur un cactus au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Colombia", "Canada", "Jamaica", "Argentina"], answer: 1, fact: "It is only from 1965. Before that the country flew a flag carrying another nation's, after decades of argument.", src: "https://en.wikipedia.org/wiki/Flag_of_Canada", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Flag_of_Canada_%28Pantone%29.svg/960px-Flag_of_Canada_%28Pantone%29.svg.png", "by": "Original: George F. G. Stanley\n\nModified by: The original uploader was", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Canada_%28Pantone%29.svg", "fit": "contain", "alt": "A white centre square between two red bands, with a red eleven-pointed leaf in the middle.", "alt_fr": "Un carré blanc central entre deux bandes rouges, avec une feuille rouge à onze pointes au milieu."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Chile", "Peru", "Brazil", "Jamaica"], answer: 1, fact: "Legend says the colours come from flamingos a liberating general saw as he landed on the coast.", src: "https://en.wikipedia.org/wiki/Flag_of_Peru", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Flag_of_Peru.svg/960px-Flag_of_Peru.svg.png", "by": "David Benbennick", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Peru.svg", "fit": "contain", "alt": "Red, white and red vertical bands.", "alt_fr": "Bandes verticales rouge, blanche et rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Argentina", "Canada", "Colombia", "Chile"], answer: 2, fact: "Colombia, Ecuador and Venezuela share these colours because they were once a single country.", src: "https://en.wikipedia.org/wiki/Flag_of_Colombia", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Flag_of_Colombia.svg/960px-Flag_of_Colombia.svg.png", "by": "See File history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Colombia.svg", "fit": "contain", "alt": "Three horizontal bands: a double-height yellow band above blue and red.", "alt_fr": "Trois bandes horizontales : une bande jaune de double hauteur au-dessus du bleu et du rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Argentina", "Chile", "Canada", "Colombia"], answer: 1, fact: "Its design predates Texas's very similar flag by nearly twenty years.", src: "https://en.wikipedia.org/wiki/Flag_of_Chile", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Flag_of_Chile.svg/960px-Flag_of_Chile.svg.png", "by": "See file history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Chile.svg", "fit": "contain", "alt": "A white band above red, with a blue square at the hoist bearing a single white star.", "alt_fr": "Une bande blanche au-dessus du rouge, avec un carré bleu au guindant portant une étoile blanche."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Argentina", "Jamaica", "Uruguay", "Cuba"], answer: 2, fact: "The nine stripes are not decoration — they are the nine original departments of the country.", src: "https://en.wikipedia.org/wiki/Flag_of_Uruguay", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Flag_of_Uruguay.svg/960px-Flag_of_Uruguay.svg.png", "by": "See File history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Uruguay.svg", "fit": "contain", "alt": "Nine alternating white and blue horizontal stripes with a golden sun face in a white canton.", "alt_fr": "Neuf bandes horizontales blanches et bleues alternées avec un visage de soleil doré dans un canton blanc."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Cuba", "Argentina", "Jamaica", "Peru"], answer: 2, fact: "It is the only national flag in the world that contains neither red, white nor blue.", src: "https://en.wikipedia.org/wiki/Flag_of_Jamaica", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Flag_of_Jamaica.svg/960px-Flag_of_Jamaica.svg.png", "by": "The SVG code is valid. This vector image was created with Inkscape by ", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Jamaica.svg", "fit": "contain", "alt": "A gold diagonal cross dividing green triangles above and below from black triangles at the sides.", "alt_fr": "Une croix diagonale dorée séparant des triangles verts en haut et en bas de triangles noirs sur les côtés."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Cuba", "Mexico", "Colombia", "Peru"], answer: 0, fact: "It was designed in New York in 1849, by exiles, decades before independence.", src: "https://en.wikipedia.org/wiki/Flag_of_Cuba", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Flag_of_Cuba.svg/960px-Flag_of_Cuba.svg.png", "by": "Miguel Teurbe Tolón and Narciso López", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Cuba.svg", "fit": "contain", "alt": "Five blue and white stripes with a red triangle at the hoist bearing a white star.", "alt_fr": "Cinq bandes bleues et blanches avec un triangle rouge au guindant portant une étoile blanche."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Egypt", "Kenya", "Namibia", "Tanzania"], answer: 1, fact: "The shield and spears in the centre are Maasai, and they were added to say the freedom won would be defended.", src: "https://en.wikipedia.org/wiki/Flag_of_Kenya", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Flag_of_Kenya.svg/960px-Flag_of_Kenya.svg.png", "by": "User:Pumbaa80", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Kenya.svg", "fit": "contain", "alt": "Black, red and green horizontal bands separated by thin white lines, with a Maasai shield and spears in the centre.", "alt_fr": "Bandes horizontales noire, rouge et verte séparées par de fines lignes blanches, avec un bouclier et des lances au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Botswana", "Ghana", "Rwanda", "Nigeria"], answer: 1, fact: "Its black star was borrowed by a football team, a shipping line and, later, half a continent's flags.", src: "https://en.wikipedia.org/wiki/Flag_of_Ghana", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Flag_of_Ghana.svg/960px-Flag_of_Ghana.svg.png", "by": "Theodosia Okoh", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Ghana.svg", "fit": "contain", "alt": "Red, gold and green horizontal bands with a black five-pointed star in the centre.", "alt_fr": "Bandes horizontales rouge, or et verte avec une étoile noire à cinq branches au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Tanzania", "Nigeria", "Namibia", "Morocco"], answer: 1, fact: "The design was chosen from nearly 3,000 entries in a competition — won by a 23-year-old student.", src: "https://en.wikipedia.org/wiki/Flag_of_Nigeria", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Flag_of_Nigeria.svg/960px-Flag_of_Nigeria.svg.png", "by": "Jon Harald Søby.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Nigeria.svg", "fit": "contain", "alt": "Three vertical bands: green, white, green.", "alt_fr": "Trois bandes verticales : verte, blanche, verte."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Namibia", "Mozambique", "Rwanda", "South Africa"], answer: 3, fact: "Adopted in 1994 as an interim design meant to last five years, it was so well liked it was simply kept.", src: "https://en.wikipedia.org/wiki/Flag_of_South_Africa", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/Flag_of_South_Africa.svg/960px-Flag_of_South_Africa.svg.png", "by": "Flag design by Frederick Brownell, image by Wikimedia Commons users", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_South_Africa.svg", "fit": "contain", "alt": "Six colours in a horizontal Y shape: a green band edged in white and gold separating red above from blue below, with a black triangle at the hoist.", "alt_fr": "Six couleurs en Y horizontal : une bande verte bordée de blanc et d'or séparant le rouge du bleu, avec un triangle noir au guindant."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Morocco", "Kenya", "Ethiopia", "Ghana"], answer: 2, fact: "Its green, yellow and red were adopted across Africa as the pan-African colours — because this country was never colonised.", src: "https://en.wikipedia.org/wiki/Flag_of_Ethiopia", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Flag_of_Ethiopia.svg/960px-Flag_of_Ethiopia.svg.png", "by": "Drawn by User:SKopp", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Ethiopia.svg", "fit": "contain", "alt": "Green, yellow and red horizontal bands with a blue disc bearing a yellow star in the centre.", "alt_fr": "Bandes horizontales verte, jaune et rouge avec un disque bleu portant une étoile jaune au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Namibia", "Morocco", "South Africa", "Egypt"], answer: 3, fact: "The bird in the centre is the Eagle of Saladin, a symbol adopted by several Arab republics.", src: "https://en.wikipedia.org/wiki/Flag_of_Egypt", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Flag_of_Egypt.svg/960px-Flag_of_Egypt.svg.png", "by": "See File history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Egypt.svg", "fit": "contain", "alt": "Red, white and black horizontal bands with a golden eagle in the centre.", "alt_fr": "Bandes horizontales rouge, blanche et noire avec un aigle doré au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Ghana", "Rwanda", "Morocco", "Egypt"], answer: 2, fact: "The star was added in 1915 so the flag could be told apart at sea from other plain red ones.", src: "https://en.wikipedia.org/wiki/Flag_of_Morocco", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Flag_of_Morocco.svg/960px-Flag_of_Morocco.svg.png", "by": "Denelson83, Zscout370", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Morocco.svg", "fit": "contain", "alt": "A red flag with a green interlaced five-pointed star in the centre.", "alt_fr": "Un drapeau rouge avec une étoile verte à cinq branches entrelacée au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Mali", "Tanzania", "Senegal", "Namibia"], answer: 2, fact: "It kept the colours of a short-lived federation with a neighbour and swapped the emblem for a star.", src: "https://en.wikipedia.org/wiki/Flag_of_Senegal", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Flag_of_Senegal.svg/960px-Flag_of_Senegal.svg.png", "by": "Original upload by Nightstallion", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Senegal.svg", "fit": "contain", "alt": "Green, yellow and red vertical bands with a green five-pointed star on the yellow.", "alt_fr": "Bandes verticales verte, jaune et rouge avec une étoile verte à cinq branches sur le jaune."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Botswana", "Mali", "Namibia", "Tanzania"], answer: 3, fact: "It is a merger of two flags, because the country is a union of a mainland republic and an island one.", src: "https://en.wikipedia.org/wiki/Flag_of_Tanzania", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Flag_of_Tanzania.svg/960px-Flag_of_Tanzania.svg.png", "by": "Wikimedia Commons", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Tanzania.svg", "fit": "contain", "alt": "A green upper triangle and a blue lower triangle divided by a black diagonal edged in yellow.", "alt_fr": "Un triangle supérieur vert et un triangle inférieur bleu séparés par une diagonale noire bordée de jaune."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Mali", "Morocco", "Namibia", "Senegal"], answer: 0, fact: "A human figure was removed from the centre in 1961, a year after independence.", src: "https://en.wikipedia.org/wiki/Flag_of_Mali", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Flag_of_Mali.svg/960px-Flag_of_Mali.svg.png", "by": "SKopp", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Mali.svg", "fit": "contain", "alt": "Three vertical bands: green, yellow, red.", "alt_fr": "Trois bandes verticales : verte, jaune, rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Nigeria", "Morocco", "Tanzania", "Rwanda"], answer: 3, fact: "The flag was completely redesigned in 2001 to remove colours associated with the 1994 genocide.", src: "https://en.wikipedia.org/wiki/Flag_of_Rwanda", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Flag_of_Rwanda.svg/960px-Flag_of_Rwanda.svg.png", "by": "Original: Unknown Vector:  Zscout370", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Rwanda.svg", "fit": "contain", "alt": "Horizontal bands of sky blue, yellow and green, with a golden sun in the upper right.", "alt_fr": "Bandes horizontales bleu ciel, jaune et verte, avec un soleil doré en haut à droite."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Botswana", "Senegal", "Namibia", "Ghana"], answer: 0, fact: "The blue stands for water and the national motto is simply the word for rain.", src: "https://en.wikipedia.org/wiki/Flag_of_Botswana", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Flag_of_Botswana.svg/960px-Flag_of_Botswana.svg.png", "by": "SKopp, Gabbe, Madden", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Botswana.svg", "fit": "contain", "alt": "A light blue field crossed by a horizontal black band edged in white.", "alt_fr": "Un fond bleu clair traversé d'une bande horizontale noire bordée de blanc."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Senegal", "Mali", "Egypt", "Namibia"], answer: 3, fact: "The sun has twelve rays, one for each of the country's main communities.", src: "https://en.wikipedia.org/wiki/Flag_of_Namibia", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Flag_of_Namibia.svg/960px-Flag_of_Namibia.svg.png", "by": "SVG by Vzb83~commonswiki et al.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Namibia.svg", "fit": "contain", "alt": "A red diagonal band edged in white, with a golden sun in the blue upper triangle and a green lower triangle.", "alt_fr": "Une bande diagonale rouge bordée de blanc, avec un soleil doré dans le triangle bleu supérieur et un triangle vert en bas."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Nigeria", "Kenya", "Egypt", "Mozambique"], answer: 3, fact: "It is the only national flag showing a modern rifle, and there are regular parliamentary attempts to remove it.", src: "https://en.wikipedia.org/wiki/Flag_of_Mozambique", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Flag_of_Mozambique.svg/960px-Flag_of_Mozambique.svg.png", "by": "FRELIMO", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Mozambique.svg", "fit": "contain", "alt": "Green, black and yellow bands with white edging, and a red hoist triangle bearing a star, a book, a hoe and a rifle.", "alt_fr": "Bandes verte, noire et jaune bordées de blanc, et un triangle rouge au guindant portant une étoile, un livre, une houe et un fusil."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["France", "Albania", "Ireland", "Switzerland"], answer: 0, fact: "The three bands are not equal in the original design — blue was made narrower so they would look equal at sea.", src: "https://en.wikipedia.org/wiki/Flag_of_France", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Flag_of_France.svg/960px-Flag_of_France.svg.png", "by": "Original: Unknown Vector:  SKopp", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_France.svg", "fit": "contain", "alt": "Three vertical bands: blue, white, red.", "alt_fr": "Trois bandes verticales : bleue, blanche, rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["France", "Germany", "Switzerland", "Greece"], answer: 1, fact: "The colours come from the uniforms of volunteer soldiers in the 1810s, not from any royal house.", src: "https://en.wikipedia.org/wiki/Flag_of_Germany", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Flag_of_Germany.svg/960px-Flag_of_Germany.svg.png", "by": "User:SKopp, User:Madden, and other users", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Germany.svg", "fit": "contain", "alt": "Three horizontal bands: black, red, gold.", "alt_fr": "Trois bandes horizontales : noire, rouge, or."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Ireland", "Albania", "Finland", "Italy"], answer: 3, fact: "Napoleon's arrival is why it exists: the design copies the French tricolour with green in place of blue.", src: "https://en.wikipedia.org/wiki/Flag_of_Italy", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Flag_of_Italy.svg/960px-Flag_of_Italy.svg.png", "by": "See below.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Italy.svg", "fit": "contain", "alt": "Three vertical bands: green, white, red.", "alt_fr": "Trois bandes verticales : verte, blanche, rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Spain", "Norway", "Iceland", "France"], answer: 0, fact: "The colours were chosen in 1785 for one reason — to be visible from far away at sea.", src: "https://en.wikipedia.org/wiki/Flag_of_Spain", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Flag_of_Spain.svg/960px-Flag_of_Spain.svg.png", "by": "RelShot 263, Echando una mano; earlier version was Pedro A. Gracia Faj", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Spain.svg", "fit": "contain", "alt": "Red, a double-height yellow band, and red, with a coat of arms toward the hoist.", "alt_fr": "Rouge, une bande jaune de double hauteur, et rouge, avec des armoiries vers le guindant."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Poland", "Portugal", "Albania", "Italy"], answer: 1, fact: "The sphere in the centre is a navigation instrument, put there to credit the sailors rather than the kings.", src: "https://en.wikipedia.org/wiki/Flag_of_Portugal", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Flag_of_Portugal.svg/960px-Flag_of_Portugal.svg.png", "by": "Original: Columbano Bordalo Pinheiro (1910; generic design) Vector:  V", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Portugal.svg", "fit": "contain", "alt": "Green at the hoist and red beyond, with an armillary sphere and shield over the join.", "alt_fr": "Vert au guindant et rouge au-delà, avec une sphère armillaire et un écu sur la jonction."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Ukraine", "Greece", "Iceland", "Norway"], answer: 1, fact: "The nine stripes are widely said to be the nine syllables of a revolutionary war cry.", src: "https://en.wikipedia.org/wiki/Flag_of_Greece", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Flag_of_Greece.svg/960px-Flag_of_Greece.svg.png", "by": "Unknown authorUnknown author", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Greece.svg", "fit": "contain", "alt": "Nine blue and white horizontal stripes with a white cross on blue in the canton.", "alt_fr": "Neuf bandes bleues et blanches avec une croix blanche sur fond bleu dans le canton."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Finland", "Belgium", "Sweden", "Netherlands"], answer: 2, fact: "The off-centre cross is a Nordic pattern: every flag using it points the cross toward the flagpole.", src: "https://en.wikipedia.org/wiki/Flag_of_Sweden", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Flag_of_Sweden.svg/960px-Flag_of_Sweden.svg.png", "by": "Jon Harald Søby and others.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Sweden.svg", "fit": "contain", "alt": "A yellow off-centre cross on blue.", "alt_fr": "Une croix jaune décentrée sur fond bleu."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Sweden", "France", "Norway", "Spain"], answer: 2, fact: "It carries two crosses, one inside the other, recording rule by two different neighbours.", src: "https://en.wikipedia.org/wiki/Flag_of_Norway", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Flag_of_Norway.svg/960px-Flag_of_Norway.svg.png", "by": "Original: Fredrik Meltzer Vector:  Gutten på Hemsen", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Norway.svg", "fit": "contain", "alt": "A blue off-centre cross outlined in white, on red.", "alt_fr": "Une croix bleue décentrée bordée de blanc, sur fond rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Spain", "Finland", "France", "Belgium"], answer: 1, fact: "The blue is for the country's tens of thousands of lakes, the white for snow.", src: "https://en.wikipedia.org/wiki/Flag_of_Finland", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Flag_of_Finland.svg/960px-Flag_of_Finland.svg.png", "by": "Unknown", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Finland.svg", "fit": "contain", "alt": "A blue off-centre cross on white.", "alt_fr": "Une croix bleue décentrée sur fond blanc."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Iceland", "Poland", "Ukraine", "Italy"], answer: 0, fact: "Its colours are a landscape: red for volcanic fire, white for ice, blue for the ocean around it.", src: "https://en.wikipedia.org/wiki/Flag_of_Iceland", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Flag_of_Iceland.svg/960px-Flag_of_Iceland.svg.png", "by": "Original: Matthías Þórðarson Vector:  Árni Dagur and Magasjukur2", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Iceland.svg", "fit": "contain", "alt": "A red off-centre cross outlined in white, on blue.", "alt_fr": "Une croix rouge décentrée bordée de blanc, sur fond bleu."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Greece", "Belgium", "Poland", "Switzerland"], answer: 2, fact: "Hung the other way up it becomes Monaco's and Indonesia's — the order of the two bands is the whole difference.", src: "https://en.wikipedia.org/wiki/Flag_of_Poland", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Flag_of_Poland.svg/960px-Flag_of_Poland.svg.png", "by": "See below.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Poland.svg", "fit": "contain", "alt": "Two horizontal bands, white above red.", "alt_fr": "Deux bandes horizontales, blanche au-dessus de rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Switzerland", "Spain", "Finland", "Netherlands"], answer: 0, fact: "It is one of only two square national flags in the world; the other belongs to the Vatican.", src: "https://en.wikipedia.org/wiki/Flag_of_Switzerland", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Flag_of_Switzerland.svg/960px-Flag_of_Switzerland.svg.png", "by": "Original: Unknown\nVector:\nUser:Marc Mongenet\nCredits:\n\nUser:-xfi-\nUser", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Switzerland.svg", "fit": "contain", "alt": "A square red flag with a bold white cross in the centre.", "alt_fr": "Un drapeau carré rouge portant une large croix blanche au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Iceland", "Germany", "Netherlands", "Romania"], answer: 3, fact: "It is nearly identical to Chad's, and the two countries have argued about it at the United Nations.", src: "https://en.wikipedia.org/wiki/Flag_of_Romania", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Flag_of_Romania.svg/960px-Flag_of_Romania.svg.png", "by": "AdiJapan", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Romania.svg", "fit": "contain", "alt": "Three vertical bands: blue, yellow, red.", "alt_fr": "Trois bandes verticales : bleue, jaune, rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Sweden", "Italy", "Norway", "Ireland"], answer: 3, fact: "The white band is the point of it: it was designed to stand for peace between the two traditions on either side.", src: "https://en.wikipedia.org/wiki/Flag_of_Ireland", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Flag_of_Ireland.svg/960px-Flag_of_Ireland.svg.png", "by": "Éire", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Ireland.svg", "fit": "contain", "alt": "Three vertical bands: green, white, orange.", "alt_fr": "Trois bandes verticales : verte, blanche, orange."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["France", "Romania", "Iceland", "Netherlands"], answer: 3, fact: "The top band used to be orange, and it was changed to red — most likely because orange dye faded at sea.", src: "https://en.wikipedia.org/wiki/Flag_of_the_Netherlands", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Flag_of_the_Netherlands.svg/960px-Flag_of_the_Netherlands.svg.png", "by": "Zscout370", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_the_Netherlands.svg", "fit": "contain", "alt": "Three horizontal bands: red, white, blue.", "alt_fr": "Trois bandes horizontales : rouge, blanche, bleue."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Albania", "Belgium", "Ukraine", "Iceland"], answer: 1, fact: "Its proportions are unusually tall and narrow, and it is the only national flag whose stripes run this way with these colours.", src: "https://en.wikipedia.org/wiki/Flag_of_Belgium", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Flag_of_Belgium.svg/960px-Flag_of_Belgium.svg.png", "by": "Dbenbenn and others", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Belgium.svg", "fit": "contain", "alt": "Three vertical bands: black, yellow, red.", "alt_fr": "Trois bandes verticales : noire, jaune, rouge."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Ukraine", "Albania", "Poland", "Portugal"], answer: 0, fact: "The two bands are meant to be read as a picture: sky above, ripe wheat below.", src: "https://en.wikipedia.org/wiki/Flag_of_Ukraine", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Flag_of_Ukraine.svg/960px-Flag_of_Ukraine.svg.png", "by": "Government of Ukraine", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Ukraine.svg", "fit": "contain", "alt": "Two horizontal bands, blue above yellow.", "alt_fr": "Deux bandes horizontales, bleue au-dessus de jaune."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 1, kids: true, q: "Which country's flag is this?", options: ["Ukraine", "Ireland", "Albania", "Greece"], answer: 2, fact: "The two-headed eagle comes from a 15th-century leader's seal, and the country's own name for itself means 'land of the eagles'.", src: "https://en.wikipedia.org/wiki/Flag_of_Albania", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Flag_of_Albania.svg/960px-Flag_of_Albania.svg.png", "by": "Sadik Kaceli", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Albania.svg", "fit": "contain", "alt": "A red flag with a black two-headed eagle in the centre.", "alt_fr": "Un drapeau rouge portant un aigle noir à deux têtes au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["United Arab Emirates", "Jordan", "Turkey", "Qatar"], answer: 2, fact: "The crescent and star were on Ottoman flags long before, and the design was fixed by law in 1936.", src: "https://en.wikipedia.org/wiki/Flag_of_Turkey", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Flag_of_Turkey.svg/960px-Flag_of_Turkey.svg.png", "by": "David Benbennick (original author)", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Turkey.svg", "fit": "contain", "alt": "A red flag with a white crescent and a white five-pointed star.", "alt_fr": "Un drapeau rouge avec un croissant blanc et une étoile blanche à cinq branches."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Qatar", "Turkey", "Israel", "Jordan"], answer: 2, fact: "The design is taken from a prayer shawl, with the star placed between its two stripes.", src: "https://en.wikipedia.org/wiki/Flag_of_Israel", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Flag_of_Israel.svg/960px-Flag_of_Israel.svg.png", "by": "Israel Belkind and Fanny Abramovitch (original)\n“The Provisional Counc", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Israel.svg", "fit": "contain", "alt": "A white flag with two horizontal blue stripes and a blue six-pointed star in the centre.", "alt_fr": "Un drapeau blanc à deux bandes horizontales bleues et une étoile bleue à six branches au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Iran", "United Arab Emirates", "Jordan", "Saudi Arabia"], answer: 3, fact: "Because the script is sacred, the flag is never flown at half-mast and is printed on both sides so it reads correctly either way.", src: "https://en.wikipedia.org/wiki/Flag_of_Saudi_Arabia", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Flag_of_Saudi_Arabia.svg/960px-Flag_of_Saudi_Arabia.svg.png", "by": "The Shura Council", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Saudi_Arabia.svg", "fit": "contain", "alt": "A green flag with white Arabic script above a horizontal white sword.", "alt_fr": "Un drapeau vert portant une inscription arabe blanche au-dessus d'un sabre blanc horizontal."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Iran", "Lebanon", "Saudi Arabia", "Turkey"], answer: 0, fact: "The thin decorative borders are not decoration: the same phrase is repeated 22 times, for a date in the revolution.", src: "https://en.wikipedia.org/wiki/Flag_of_Iran", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Flag_of_Iran.svg/960px-Flag_of_Iran.svg.png", "by": "SVG file: SiBr4Designer: Hamid NadimiConstruction: ISIRI", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Iran.svg", "fit": "contain", "alt": "Green, white and red horizontal bands with a red emblem in the centre and repeated white script along the band edges.", "alt_fr": "Bandes horizontales verte, blanche et rouge avec un emblème rouge au centre et une inscription blanche répétée le long des bordures."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Turkey", "Lebanon", "Iran", "Israel"], answer: 1, fact: "The tree in the centre is a species named after the country, and it is mentioned repeatedly in the Bible.", src: "https://en.wikipedia.org/wiki/Flag_of_Lebanon", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Flag_of_Lebanon.svg/960px-Flag_of_Lebanon.svg.png", "by": "Henri Pharaon", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Lebanon.svg", "fit": "contain", "alt": "Red, a double-height white band, and red, with a green cedar tree in the centre.", "alt_fr": "Rouge, une bande blanche de double hauteur, et rouge, avec un cèdre vert au centre."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Qatar", "Turkey", "Jordan", "Lebanon"], answer: 2, fact: "The star's seven points stand for the seven verses of the opening chapter of the Quran.", src: "https://en.wikipedia.org/wiki/Flag_of_Jordan", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Flag_of_Jordan.svg/960px-Flag_of_Jordan.svg.png", "by": "Unknown", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Jordan.svg", "fit": "contain", "alt": "Black, white and green horizontal bands with a red hoist triangle bearing a white seven-pointed star.", "alt_fr": "Bandes horizontales noire, blanche et verte avec un triangle rouge au guindant portant une étoile blanche à sept branches."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Israel", "Qatar", "Saudi Arabia", "Jordan"], answer: 1, fact: "Its colour started as plain red dye that turned purple-brown in the sun — and the country kept the accident.", src: "https://en.wikipedia.org/wiki/Flag_of_Qatar", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Flag_of_Qatar.svg/960px-Flag_of_Qatar.svg.png", "by": "See File history below for details.", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Qatar.svg", "fit": "contain", "alt": "A maroon field with a white serrated band at the hoist.", "alt_fr": "Un fond bordeaux avec une bande blanche dentelée au guindant."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Israel", "Jordan", "Qatar", "United Arab Emirates"], answer: 3, fact: "Its four colours appear in a 13th-century Arabic poem about the ideal qualities of a people.", src: "https://en.wikipedia.org/wiki/Flag_of_the_United_Arab_Emirates", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Flag_of_the_United_Arab_Emirates.svg/960px-Flag_of_the_United_Arab_Emirates.svg.png", "by": "Abdulla Mohammed Al Maainah", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_the_United_Arab_Emirates.svg", "fit": "contain", "alt": "A vertical red band at the hoist beside green, white and black horizontal bands.", "alt_fr": "Une bande verticale rouge au guindant à côté de bandes horizontales verte, blanche et noire."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Fiji", "Australia", "New Zealand", "Papua New Guinea"], answer: 1, fact: "The design was chosen in 1901 from a competition with over 32,000 entries; five people were judged to have won it jointly.", src: "https://en.wikipedia.org/wiki/Flag_of_Australia", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Flag_of_Australia_%28converted%29.svg/960px-Flag_of_Australia_%28converted%29.svg.png", "by": "Unknown  (Vector graphics image by Ian Fieggen) (only minor code chang", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Australia_%28converted%29.svg", "fit": "contain", "alt": "A blue flag with another country's flag in the canton, a large seven-pointed star below it, and five stars of the Southern Cross at the fly.", "alt_fr": "Un drapeau bleu portant le drapeau d'un autre pays dans le canton, une grande étoile à sept branches en dessous, et cinq étoiles de la Croix du Sud au battant."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Fiji", "New Zealand", "Papua New Guinea", "Australia"], answer: 1, fact: "A 2016 referendum asked whether to replace it. The country voted to keep it.", src: "https://en.wikipedia.org/wiki/Flag_of_New_Zealand", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Flag_of_New_Zealand.svg/960px-Flag_of_New_Zealand.svg.png", "by": "Original: Albert Hastings Markham Vector:  Zscout370, Hugh Jass, s. Fi", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_New_Zealand.svg", "fit": "contain", "alt": "A blue flag with another country's flag in the canton and four red stars outlined in white at the fly.", "alt_fr": "Un drapeau bleu portant le drapeau d'un autre pays dans le canton et quatre étoiles rouges bordées de blanc au battant."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Australia", "New Zealand", "Papua New Guinea", "Fiji"], answer: 3, fact: "A plan to remove the other country's flag from the corner was announced in 2015 and then quietly dropped.", src: "https://en.wikipedia.org/wiki/Flag_of_Fiji", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Flag_of_Fiji.svg/960px-Flag_of_Fiji.svg.png", "by": "Tessa Mackenzie", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Fiji.svg", "fit": "contain", "alt": "A light blue flag with another country's flag in the canton and a shield at the fly.", "alt_fr": "Un drapeau bleu clair portant le drapeau d'un autre pays dans le canton et un écu au battant."} },
  { cat: "Geography", sub: "Countries & Flags", diff: 2, kids: true, q: "Which country's flag is this?", options: ["Australia", "Papua New Guinea", "New Zealand", "Fiji"], answer: 1, fact: "It was designed by a teenager, whose entry won a national competition in 1971.", src: "https://en.wikipedia.org/wiki/Flag_of_Papua_New_Guinea", img: {"u": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Flag_of_Papua_New_Guinea.svg/960px-Flag_of_Papua_New_Guinea.svg.png", "by": "User:Nightstallion", "lic": "Public domain", "p": "https://commons.wikimedia.org/wiki/File:Flag_of_Papua_New_Guinea.svg", "fit": "contain", "alt": "Divided diagonally: a black upper triangle with the Southern Cross in white, and a red lower triangle with a golden bird of paradise.", "alt_fr": "Divisé en diagonale : un triangle noir supérieur avec la Croix du Sud en blanc, et un triangle rouge inférieur avec un oiseau de paradis doré."} },

  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "Builders check that a corner is truly square by measuring a triangle with sides of 3, 4 and 5. Which theorem are they using?", options: ["Pythagoras' theorem", "Thales' theorem", "Euclid's parallel postulate", "Ptolemy's theorem"], answer: 0, fact: "The 3-4-5 triangle was already known in Egypt and Babylon over a thousand years before Pythagoras was born.", src: "https://en.wikipedia.org/wiki/Pythagorean_theorem" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "Before his 1962 orbit of Earth, astronaut John Glenn refused to fly until a mathematician had checked the computer's numbers by hand. For which organisation did she work?", options: ["NASA", "The US Navy", "IBM", "The Smithsonian Institution"], answer: 0, fact: "Katherine Johnson had already worked out the trajectory for Alan Shepard's 1961 flight, the first American in space.", src: "https://en.wikipedia.org/wiki/Katherine_Johnson" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "Around 240 BCE a scholar in Alexandria compared the shadows cast at noon in two Egyptian cities. What did he manage to measure?", options: ["The size of the whole Earth", "The distance to the Sun", "The height of the Great Pyramid", "The depth of the Nile"], answer: 0, fact: "Eratosthenes' figure was within about 1% of the Earth's true circumference — and two of his mistakes happened to cancel out.", src: "https://en.wikipedia.org/wiki/Eratosthenes" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "Florence Nightingale is remembered as a nurse. In which other field was she a pioneer?", options: ["Statistics", "Chemistry", "Geology", "Architecture"], answer: 0, fact: "She turned death records into diagrams to persuade officials, and in 1859 became the first woman elected to the Royal Statistical Society.", src: "https://en.wikipedia.org/wiki/Florence_Nightingale" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "The Ishango bone, one of the oldest known objects covered in tally marks, was found on which continent?", options: ["Africa", "Europe", "Asia", "South America"], answer: 0, fact: "Carved about 20,000 years ago near the Semliki River in the Democratic Republic of the Congo, its 168 notches run in three columns.", src: "https://en.wikipedia.org/wiki/Ishango_bone" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "The Maya wrote numbers with dots and bars. Which symbol did they use for zero?", options: ["A shell", "A star", "A feather", "An open hand"], answer: 0, fact: "Maya counting works in twenties, not tens — so one dot above a shell means twenty, the way '10' means ten to us.", src: "https://en.wikipedia.org/wiki/Maya_numerals" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "Leonardo of Pisa's 1202 book 'Liber Abaci' helped Europe adopt which way of writing numbers?", options: ["Hindu-Arabic numerals", "Roman numerals", "Greek letter numerals", "Egyptian hieroglyphic numerals"], answer: 0, fact: "He learned the digits as a boy in Bugia (Béjaïa, Algeria), where his father ran a trading post, and sold them to Europe as a merchant's tool.", src: "https://en.wikipedia.org/wiki/Fibonacci" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "In 1843 Ada Lovelace wrote that a calculating machine might one day do what, besides handle numbers?", options: ["Compose music", "Cook a meal", "Predict the weather perfectly", "Read a person's thoughts"], answer: 0, fact: "She reasoned that if harmony could be written as symbols, the machine could work on those symbols too — a century before computers existed.", src: "https://en.wikipedia.org/wiki/Ada_Lovelace" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "A QR code still scans even when part of it is torn or dirty. What lets it do that?", options: ["Extra maths built in that repairs missing pieces", "A second copy of the code printed underneath", "The camera guessing the missing squares at random", "A special reflective ink in the black squares"], answer: 0, fact: "The same Reed–Solomon codes, published in 1960, protect CDs from scratches and carried Voyager's photos back from the outer planets.", src: "https://en.wikipedia.org/wiki/Reed%E2%80%93Solomon_error_correction" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "The best-known mathematics book from ancient Egypt is packed with problems about sharing out which two things among workers?", options: ["Bread and beer", "Gold and silver", "Papyrus and ink", "Cattle and horses"], answer: 0, fact: "Copied by the scribe Ahmes around 1550 BCE, it finds a circle's area by squaring eight-ninths of the diameter — within 1% of the truth.", src: "https://en.wikipedia.org/wiki/Rhind_Mathematical_Papyrus" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "In 1736 Leonhard Euler proved that no walk could cross all seven bridges of Königsberg exactly once. Which branch of maths did his answer create?", options: ["Graph theory", "Trigonometry", "Calculus", "Algebra"], answer: 0, fact: "Euler's trick was to ignore distance and shape, keeping only what connects to what — the idea behind route planners and social networks.", src: "https://en.wikipedia.org/wiki/Seven_Bridges_of_K%C3%B6nigsberg" },
  { cat: "Science", sub: "Mathematics", diff: 1, kids: true, q: "Writing around 499 CE, the Indian mathematician Aryabhata explained the nightly march of the stars across the sky by saying what?", options: ["The Earth turns on its own axis", "The stars ride on a rotating crystal shell", "The Sun drags the stars along behind it", "The sky is a river that slowly flows"], answer: 0, fact: "He compared it to a boat: a passenger moving downstream sees the still riverbank slide backwards.", src: "https://en.wikipedia.org/wiki/Aryabhata" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "In 2014 the Iranian mathematician Maryam Mirzakhani became the first woman to win which prize?", options: ["The Fields Medal", "The Abel Prize", "The Turing Award", "The Wolf Prize"], answer: 0, fact: "She had already won gold at the International Mathematical Olympiad twice as a teenager, with a perfect score in 1995.", src: "https://en.wikipedia.org/wiki/Maryam_Mirzakhani" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "Fourier analysis breaks any signal into simple waves — it is how MP3s, JPEGs and MRI scans work. What was Joseph Fourier studying when he devised it?", options: ["How heat spreads through a solid object", "How planets move around the Sun", "How bridges carry weight", "How gases behave under pressure"], answer: 0, fact: "Fourier presented his heat work in Paris in 1807; a descendant of the same maths now decides which parts of a photo a JPEG can discard.", src: "https://en.wikipedia.org/wiki/Joseph_Fourier" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "How many satellites must a GPS receiver pick up to fix its position in three dimensions?", options: ["Four", "One", "Two", "Twelve"], answer: 0, fact: "Clocks on GPS satellites run about 38 microseconds a day faster than ours, exactly as relativity predicts — the system corrects for it.", src: "https://en.wikipedia.org/wiki/Global_Positioning_System" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "In the Yoruba language of West Africa, counting works in twenties and uses subtraction. How is 'fifteen' literally expressed?", options: ["Five from twenty", "Ten and five", "Three fives", "Half of twenty plus five"], answer: 0, fact: "Sixteen, seventeen, eighteen and nineteen are said the same way — as four, three, two and one taken away from twenty.", src: "https://en.wikipedia.org/wiki/Yoruba_numerals" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "Chokwe elders in Angola trace 'sona' pictures in the sand around a grid of dots. What rule makes them remarkable?", options: ["Most are drawn with one unbroken line", "They must be drawn with the left hand", "They use exactly seven colours", "They must be finished before sunrise"], answer: 0, fact: "About 60% of recorded sona are monolinear — one continuous line — and the drawings carry proverbs, fables and riddles.", src: "https://en.wikipedia.org/wiki/Lusona" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "The padlock in your browser's address bar relies on public-key cryptography. What is its central idea?", options: ["Two different keys: one to lock, another to unlock", "One key that both people memorise in advance", "A single key that changes every second", "A key hidden inside the message itself"], answer: 0, fact: "Diffie and Hellman published it in 1976, building on Ralph Merkle's ideas — unaware that James Ellis had conceived it secretly at GCHQ in 1970.", src: "https://en.wikipedia.org/wiki/Public-key_cryptography" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "The RSA system that guards online payments is safe because one task stays extremely slow, even for computers. Which?", options: ["Splitting a huge number into the two primes that made it", "Multiplying two huge prime numbers together", "Testing whether a large number is prime at all", "Adding a long list of prime numbers together"], answer: 0, fact: "Rivest, Shamir and Adleman published RSA in 1977; Clifford Cocks had found the same scheme at GCHQ in 1973, kept secret until 1997.", src: "https://en.wikipedia.org/wiki/RSA_cryptosystem" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "To show how a lunar eclipse works, the Qing-dynasty astronomer Wang Zhenyi built a model in a garden pavilion out of which everyday objects?", options: ["A round table, a hanging lamp and a mirror", "A drum, a candle and a folding fan", "A bucket of water, a rope and a stone", "A kite, a lantern and a bamboo pole"], answer: 0, fact: "She also rewrote a difficult maths textbook in plainer language so beginners could learn multiplication and division; she died at 29.", src: "https://en.wikipedia.org/wiki/Wang_Zhenyi_(astronomer)" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "In the 5th century the Chinese mathematician Zu Chongzhi pinned down the value of which number more precisely than anyone would manage for nearly 900 years?", options: ["Pi", "The square root of two", "The golden ratio", "The speed of sound"], answer: 0, fact: "He fixed π between 3.1415926 and 3.1415927, and offered the handy fraction 355/113 — accurate enough for almost any everyday job.", src: "https://en.wikipedia.org/wiki/Zu_Chongzhi" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "Besides his famous poetry, the Persian scholar Omar Khayyam solved cubic equations using which geometric shapes?", options: ["Conic sections such as parabolas and circles", "Regular polygons", "Spirals", "Grids of triangles"], answer: 0, fact: "He also helped reform the Persian calendar in 1079; its 33-year cycle tracks the year even better than the Gregorian calendar we use.", src: "https://en.wikipedia.org/wiki/Omar_Khayyam" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "The word 'sine' reached Europe through a mistranslation. What did the original Sanskrit word mean?", options: ["Bow-string", "Shadow", "Mountain", "Wheel"], answer: 0, fact: "Sanskrit jya, 'bow-string', was copied into Arabic as jb, misread as jayb ('fold'), then rendered in Latin as sinus — our 'sine'.", src: "https://en.wikipedia.org/wiki/Sine_and_cosine" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "The Chinese classic 'The Nine Chapters on the Mathematical Art' solves systems of equations by a method Europe would later name after which mathematician?", options: ["Gauss", "Newton", "Descartes", "Euler"], answer: 0, fact: "Chinese scribes solved them by laying out counting rods in columns, some 1,700 years before Gauss was born.", src: "https://en.wikipedia.org/wiki/The_Nine_Chapters_on_the_Mathematical_Art" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "Benjamin Banneker, born free in 1730s Maryland, taught himself astronomy and then published six years of what?", options: ["Almanacs, whose star tables he calculated himself", "Newspapers reporting on the tobacco trade", "Sea charts of the Atlantic coastline", "Dictionaries of the English language"], answer: 0, fact: "The astronomer David Rittenhouse called his ephemeris 'a very extraordinary performance'; Banneker sent a copy to Thomas Jefferson.", src: "https://en.wikipedia.org/wiki/Benjamin_Banneker" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "Hypatia, the earliest woman mathematician whose life is well recorded, taught in which city?", options: ["Alexandria", "Athens", "Rome", "Antioch"], answer: 0, fact: "She edited Book III of Ptolemy's Almagest and taught pupils to build astrolabes; in 415 a mob in the city murdered her.", src: "https://en.wikipedia.org/wiki/Hypatia" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: false, q: "Seki Takakazu was the leading figure of wasan, the mathematics developed in Edo-period Japan. What did he set out in 1683, almost exactly when Leibniz did in Europe?", options: ["Determinants, for solving systems of equations", "The law of gravity", "Logarithms", "The pendulum clock"], answer: 0, fact: "He also pinned π to ten decimal places using an acceleration trick only rediscovered in the 20th century, now named after Aitken.", src: "https://en.wikipedia.org/wiki/Seki_Takakazu" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: false, q: "A Babylonian clay tablet written around 1800 BCE lists column after column of what?", options: ["Whole-number triples that fit right-angled triangles", "The names of the Babylonian kings", "Rainfall records for the Euphrates", "Recipes for glazing pottery"], answer: 0, fact: "Plimpton 322 predates Pythagoras by well over a thousand years, and its triples are far too large to have been stumbled upon.", src: "https://en.wikipedia.org/wiki/Plimpton_322" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: false, q: "Around 1400, Madhava of Sangamagrama and the Kerala school in India worked out infinite series for pi and for the sine — ideas Europe would only reach with what?", options: ["Calculus", "Logarithms", "Analytic geometry", "The abacus"], answer: 0, fact: "The series π/4 = 1 − 1/3 + 1/5 − 1/7 … is often credited to Leibniz and Gregory; Madhava had it about 250 years earlier.", src: "https://en.wikipedia.org/wiki/Madhava_of_Sangamagrama" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: false, q: "In 9th-century Baghdad, al-Kindi worked out how to break a secret code without the key. What did he count?", options: ["How often each letter appears", "How many words the message has", "The gaps between the lines", "The number of pages"], answer: 0, fact: "Counting letter frequencies is now regarded as the earliest known use of statistical inference — and the birth of codebreaking.", src: "https://en.wikipedia.org/wiki/Al-Kindi" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: false, q: "Emmy Noether's most famous theorem links conservation laws — of energy, of momentum — to what?", options: ["Symmetries of a physical system", "The mass of the particles involved", "The temperature of the system", "The distance between the objects"], answer: 0, fact: "Göttingen let her lecture only under Hilbert's name for four years — one professor asked what soldiers would think of learning at a woman's feet.", src: "https://en.wikipedia.org/wiki/Emmy_Noether" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: false, q: "The compression at the heart of ZIP files and JPEGs was devised in 1951 by David Huffman in what circumstances?", options: ["As a student, doing a class term paper", "In a wartime codebreaking unit", "While working for a telephone company", "During a NASA mission"], answer: 0, fact: "His professor Robert Fano had set the problem and had his own solution; the student's method turned out to be provably better.", src: "https://en.wikipedia.org/wiki/Huffman_coding" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: false, q: "Probability theory began in 1654 with a gambler's question put to Blaise Pascal. What did he want to know?", options: ["How to split the pot if a game is stopped early", "How to spot a loaded pair of dice", "How many cards make a fair deck", "Why the house always wins in the end"], answer: 0, fact: "Pascal and Fermat's answer — judge it by what could still happen, not what already had — gave us expected value, the basis of insurance.", src: "https://en.wikipedia.org/wiki/Problem_of_points" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: false, q: "In 628 CE the Indian mathematician Brahmagupta set out the first known rules for calculating with what?", options: ["Negative numbers", "Prime numbers", "Imaginary numbers", "Decimal fractions"], answer: 0, fact: "He also tackled zero — but on dividing an ordinary number by zero he would not commit, and maths still leaves it undefined.", src: "https://en.wikipedia.org/wiki/Brahmagupta" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which is the smallest bone in the human body?", options: ["The stapes, in the middle ear", "The smallest finger bone", "The tailbone", "The kneecap"], answer: 0, fact: "The stapes is only about 2–3 mm long, and it rocks against a membrane to pass sound into the inner ear.", src: "https://en.wikipedia.org/wiki/Stapes" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which is the single largest muscle in the human body?", options: ["The gluteus maximus, in the buttock", "The heart", "The muscle of the calf", "The muscle of the upper arm"], answer: 0, fact: "It is the muscle that straightens your hip — the one that pulls you upright again every time you stand up from a stoop.", src: "https://en.wikipedia.org/wiki/Gluteus_maximus" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "The Achilles tendon joins your calf muscles to which bone?", options: ["The heel bone", "The kneecap", "The shin bone", "The big toe"], answer: 0, fact: "It is the thickest tendon in the body — every step you take pulls on it to lift your heel off the ground.", src: "https://en.wikipedia.org/wiki/Achilles_tendon" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which muscle does most of the work when you breathe in?", options: ["The diaphragm", "The muscles of the tongue", "The muscles of the abdomen", "The muscles of the throat"], answer: 0, fact: "The diaphragm is a curved sheet of muscle under the lungs; when it pulls flat, air rushes in to fill the extra space.", src: "https://en.wikipedia.org/wiki/Thoracic_diaphragm" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which metal sits at the centre of haemoglobin, the molecule that carries oxygen in your blood?", options: ["Iron", "Copper", "Zinc", "Magnesium"], answer: 0, fact: "Each iron atom picks up one oxygen molecule in the lungs and lets it go again in the tissues that need it.", src: "https://en.wikipedia.org/wiki/Hemoglobin" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which part of the digestive tract absorbs most of the nutrients from your food?", options: ["The small intestine", "The stomach", "The large intestine", "The oesophagus"], answer: 0, fact: "Folds and finger-like villi pack about 30 square metres of absorbing surface into a tube only 3–5 m long.", src: "https://en.wikipedia.org/wiki/Small_intestine" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "What is the large intestine's main job?", options: ["Absorbing water and salts from what is left of food", "Breaking down fats with bile", "Making digestive enzymes", "Adding acid to kill bacteria"], answer: 0, fact: "It is only about 1.5 m long — a fifth of the gut — yet it is where what you could not digest gives up its water.", src: "https://en.wikipedia.org/wiki/Large_intestine" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which acid does your stomach produce to help break down food?", options: ["Hydrochloric acid", "Sulfuric acid", "Citric acid", "Carbonic acid"], answer: 0, fact: "Stomach acid runs at a pH of 1 to 3 — far more acidic than in most animals — and comes from parietal cells in the lining.", src: "https://en.wikipedia.org/wiki/Gastric_acid" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which human organ can grow back after a large part of it is removed?", options: ["The liver", "The heart", "The kidney", "The brain"], answer: 0, fact: "As little as a quarter of a liver can regrow into a whole one; it weighs about 1.5 kg and sits under your right ribs.", src: "https://en.wikipedia.org/wiki/Liver" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which pigment gives human skin, hair and eyes their colour?", options: ["Melanin", "Keratin", "Collagen", "Elastin"], answer: 0, fact: "Made by cells called melanocytes, melanin absorbs ultraviolet light and safely disperses over 99.9% of that energy.", src: "https://en.wikipedia.org/wiki/Melanin" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which snail-shaped part of the inner ear turns sound vibrations into nerve signals?", options: ["The cochlea", "The eardrum", "The ear canal", "The earlobe"], answer: 0, fact: "'Cochlea' is Latin for snail shell — the human one coils 2.75 turns, and tiny hairs inside it convert the vibrations.", src: "https://en.wikipedia.org/wiki/Cochlea" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Three fluid-filled loops in each inner ear give you which sense?", options: ["Balance", "Smell", "Taste", "Touch"], answer: 0, fact: "The three canals sit at right angles to one another, so between them they register a head turn in any direction.", src: "https://en.wikipedia.org/wiki/Semicircular_canals" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "The glands that release adrenaline sit directly on top of which organs?", options: ["The kidneys", "The lungs", "The liver", "The intestines"], answer: 0, fact: "Their name says where they are: 'ad-renal' means 'on the kidney'. They also make cortisol and help set blood pressure.", src: "https://en.wikipedia.org/wiki/Adrenal_gland" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "The first X-ray picture of a human body part, taken in 1895, showed whose hand?", options: ["The hand of the discoverer's wife", "The hand of a patient in a Vienna hospital", "The hand of the young Marie Curie", "The hand of the German emperor"], answer: 0, fact: "Wilhelm Röntgen noticed the strange rays on 8 November 1895 and photographed his wife Anna Bertha's hand bones six weeks later.", src: "https://en.wikipedia.org/wiki/Wilhelm_R%C3%B6ntgen" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "How many vertebrae are in the human neck?", options: ["Seven", "Three", "Twelve", "Twenty-four"], answer: 0, fact: "A giraffe's neck contains the same seven vertebrae as yours — each one is simply enormous.", src: "https://en.wikipedia.org/wiki/Cervical_vertebrae" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "Where are new blood cells made in an adult human?", options: ["In the bone marrow", "In the lining of the stomach", "In the liver", "In the lymph nodes"], answer: 0, fact: "Marrow in the pelvis, ribs, breastbone and spine turns out roughly 500 billion blood cells every day.", src: "https://en.wikipedia.org/wiki/Bone_marrow" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "Oxygen crosses from your lungs into your blood at millions of tiny air sacs. What are they called?", options: ["Alveoli", "Villi", "Nephrons", "Follicles"], answer: 0, fact: "A pair of lungs holds about 480 million alveoli — 70 to 80 square metres of surface, folded up inside your chest.", src: "https://en.wikipedia.org/wiki/Pulmonary_alveolus" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "Which blood vessels are thin enough for oxygen to pass straight through their walls?", options: ["Capillaries", "Arteries", "Veins", "Lymph vessels"], answer: 0, fact: "A capillary is 5 to 10 micrometres across — thinner than a hair — with a wall just one flat cell thick.", src: "https://en.wikipedia.org/wiki/Capillary" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "What do mature human red blood cells lack that nearly every other cell in the body has?", options: ["A nucleus", "A cell membrane", "Proteins", "Water"], answer: 0, fact: "They survive about 120 days in circulation, and your bone marrow replaces them at some 2.4 million every second.", src: "https://en.wikipedia.org/wiki/Red_blood_cell" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "In 1628 William Harvey published a book showing that blood does what?", options: ["Circulates in a loop, pumped by the heart", "Is made fresh in the liver each day", "Flows outward once and is then used up", "Moves because the lungs squeeze it along"], answer: 0, fact: "Harvey worked out how much blood the heart pushes out in an hour and showed no body could make that much — it must be recycled.", src: "https://en.wikipedia.org/wiki/William_Harvey" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "Which part of the brain, tucked under the back of the skull, fine-tunes balance and precise movement?", options: ["The cerebellum", "The hippocampus", "The frontal lobe", "The thalamus"], answer: 0, fact: "Its name means 'little brain': it fills a tenth of the brain's volume yet holds more neurons than all the rest combined.", src: "https://en.wikipedia.org/wiki/Cerebellum" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "Which is the longest and widest single nerve in the human body?", options: ["The sciatic nerve, in the back of the leg", "The optic nerve, behind the eye", "The vagus nerve, in the chest", "The median nerve, in the arm"], answer: 0, fact: "It leaves the lower back, passes the hip and runs down the back of the thigh before branching out to the lower leg and foot.", src: "https://en.wikipedia.org/wiki/Sciatic_nerve" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "Which part of the brain is essential for turning experiences into long-term memories?", options: ["The hippocampus", "The cerebellum", "The thalamus", "The brainstem"], answer: 0, fact: "Its name is Greek for 'seahorse' — the anatomist who named it likened its curled shape to the sea creature.", src: "https://en.wikipedia.org/wiki/Hippocampus" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "Which organ, tucked behind the stomach, makes the insulin that controls blood sugar?", options: ["The pancreas", "The spleen", "The gallbladder", "The liver"], answer: 0, fact: "Insulin comes from cell clusters called the islets of Langerhans, inside a gland that also pours enzymes into the gut.", src: "https://en.wikipedia.org/wiki/Pancreas" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "How does the number of bacterial cells in and on your body compare with the number of your own cells?", options: ["About the same", "About a hundredth as many", "About a thousand times more", "Almost none in a healthy person"], answer: 0, fact: "Roughly 38 trillion bacteria live in you, most of them in the gut, against about 30 to 40 trillion human cells.", src: "https://en.wikipedia.org/wiki/Human_microbiome" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "What is the name of the outermost layer of human skin?", options: ["The epidermis", "The dermis", "The cortex", "The pleura"], answer: 0, fact: "It contains no blood vessels at all — it takes oxygen straight from the air — and renews itself about every 48 days.", src: "https://en.wikipedia.org/wiki/Epidermis" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "The clear dome at the front of the eye does most of its focusing. What is it called?", options: ["The cornea", "The retina", "The iris", "The pupil"], answer: 0, fact: "The cornea bends about two-thirds of the light entering your eye, and has no blood vessels — it takes oxygen from your tears.", src: "https://en.wikipedia.org/wiki/Cornea" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "Which organ in the upper left of the abdomen filters blood and clears out worn-out red cells?", options: ["The spleen", "The liver", "The gallbladder", "The left kidney"], answer: 0, fact: "The spleen also holds a reserve of blood and helps launch immune responses against invaders in the bloodstream.", src: "https://en.wikipedia.org/wiki/Spleen" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "Which butterfly-shaped gland sits in the neck, just below the Adam's apple?", options: ["The thyroid", "The pancreas", "The thymus", "The pituitary"], answer: 0, fact: "The thyroid needs iodine to build its hormones — which is why table salt in many countries has iodine added to it.", src: "https://en.wikipedia.org/wiki/Thyroid" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "What sets the rhythm of your heartbeat?", options: ["The sinoatrial node, a patch of cells in the heart", "A steady signal sent down from the brain", "The rhythm of the lungs filling and emptying", "The snapping shut of the heart's four valves"], answer: 0, fact: "The node's cells re-fire all by themselves, without any nerve telling them to; nerves only speed the beat up or slow it down.", src: "https://en.wikipedia.org/wiki/Sinoatrial_node" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "Around 1242, the Damascus physician Ibn al-Nafis was the first to describe blood taking which route?", options: ["From the heart through the lungs and back", "From the liver straight to the brain", "From the stomach into the kidneys", "From the spine out to the fingertips"], answer: 0, fact: "He argued there is no opening between the heart's two sides, so blood must take the long way round — nearly 400 years before Harvey.", src: "https://en.wikipedia.org/wiki/Ibn_al-Nafis" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "The vagus nerve takes its name from the Latin for 'wandering'. How far does it wander from the brain?", options: ["All the way down to the colon", "Only as far as the ears", "Only as far as the shoulders", "All the way down to the feet"], answer: 0, fact: "It leaves the brainstem, runs down the neck and chest and supplies the heart, lungs and most of the digestive tract.", src: "https://en.wikipedia.org/wiki/Vagus_nerve" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "Each kidney contains over a million tiny filtering units. What are they called?", options: ["Nephrons", "Alveoli", "Neurons", "Villi"], answer: 0, fact: "A healthy adult has 1 to 1.5 million nephrons per kidney; each filters blood, then takes back the water and salts you still need.", src: "https://en.wikipedia.org/wiki/Nephron" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "Why does each of your eyes have a small blind spot?", options: ["No light-sensing cells sit where the optic nerve leaves the eye", "The eyelid casts a shadow across the retina", "The lens is thinner at one of its edges", "Blood vessels cover the centre of the pupil"], answer: 0, fact: "The retina carries about 7 million cones for colour and 75 to 150 million rods for dim light — but none on the optic disc.", src: "https://en.wikipedia.org/wiki/Retina" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "In which organ, sitting behind the breastbone, do the immune system's T cells mature?", options: ["The thymus", "The spleen", "The liver", "The pancreas"], answer: 0, fact: "The thymus is busiest in childhood; from the early teens it shrinks and is slowly replaced by fatty tissue.", src: "https://en.wikipedia.org/wiki/Thymus" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "Andreas Vesalius's 1543 anatomy book overturned centuries of teaching because he based it on what?", options: ["His own dissections of human bodies", "Newly translated Greek manuscripts", "Drawings brought back from Egypt", "Measurements taken on living volunteers"], answer: 0, fact: "The old authority was Galen, who had dissected animals; Vesalius showed the human lower jaw is one bone, not two.", src: "https://en.wikipedia.org/wiki/Andreas_Vesalius" },
  { cat: "Tech", diff: 1, kids: true, q: "The internet and the World Wide Web are not the same thing. What is the Web?", options: ["The physical network of cables and computers", "A collection of linked pages that runs on top of that network", "Another name for the search engines people use", "The system that delivers email around the world"], answer: 1, fact: "Berners-Lee proposed the Web in 1989 at CERN, on an internet that had been carrying other kinds of traffic for years.", src: "https://en.wikipedia.org/wiki/World_Wide_Web" },
  { cat: "Tech", diff: 1, kids: true, q: "When you send a photo over the internet, how does it actually travel?", options: ["In one unbroken stream along a single wire", "Cut into small pieces that travel separately and are put back together", "As sound waves through the phone's speaker", "Copied onto every computer on the network"], answer: 1, fact: "Those pieces are called packets, they can take different routes, and they are put back in order at the far end using their numbers.", src: "https://en.wikipedia.org/wiki/Packet_switching" },
  { cat: "Tech", diff: 3, kids: false, q: "Cutting messages into packets was worked out in the 1960s by Paul Baran in the United States and, independently, by which British scientist?", options: ["Donald Davies", "Alan Turing", "Charles Babbage", "Michael Faraday"], answer: 0, fact: "Davies chose the word 'packet' after consulting a linguist, wanting a term that would translate well into other languages.", src: "https://en.wikipedia.org/wiki/Donald_Davies" },
  { cat: "Tech", diff: 2, kids: false, q: "Vint Cerf and Robert Kahn wrote the rules that let separate networks pass messages to one another — the Transmission Control Protocol and Internet Protocol. What are those rules called?", options: ["TCP/IP", "Bluetooth", "Ethernet", "Wi-Fi"], answer: 0, fact: "Cerf is hard of hearing and has long campaigned for accessible technology; he now works with NASA on an internet for spacecraft.", src: "https://en.wikipedia.org/wiki/Vint_Cerf" },
  { cat: "Tech", diff: 1, kids: true, q: "Every device on the internet is given an IP address — an Internet Protocol address. What is it for?", options: ["It says where the device is on the network, so replies can find it", "It stores the files and photos on the device", "It is the password for your Wi-Fi network", "It measures how fast the connection is running"], answer: 0, fact: "The older scheme allows about 4.3 billion addresses — fewer than there are people — so a far larger one, IPv6, was designed in 1995.", src: "https://en.wikipedia.org/wiki/IP_address" },
  { cat: "Tech", diff: 2, kids: false, q: "What does the Domain Name System do each time you type a website's name?", options: ["It turns the name into the number address of a computer", "It checks that your password is correct", "It shrinks the images so the page loads faster", "It decides which browser you will use"], answer: 0, fact: "Domain names are read right to left: in en.wikipedia.org, .org is the top level and 'en' is a sub-domain inside wikipedia.", src: "https://en.wikipedia.org/wiki/Domain_Name_System" },
  { cat: "Tech", diff: 3, kids: false, q: "Before it was automated, the master list of every computer name on the early internet was kept by hand. Who ran the team that kept it?", options: ["Elizabeth Feinler", "Grace Hopper", "Katherine Johnson", "Hedy Lamarr"], answer: 0, fact: "Feinler's group at SRI International became the internet's naming authority and suggested the categories .com, .gov, .edu and .org.", src: "https://en.wikipedia.org/wiki/Elizabeth_J._Feinler" },
  { cat: "Tech", diff: 3, kids: false, q: "Radia Perlman invented the protocol that stops data circling forever between the switches of a network. What is it called?", options: ["The Spanning Tree Protocol", "The Simple Mail Transfer Protocol", "The Domain Name System", "The File Transfer Protocol"], answer: 0, fact: "Perlman also wrote a poem about her algorithm, 'Algorhyme' — and she dislikes the nickname 'Mother of the Internet'.", src: "https://en.wikipedia.org/wiki/Radia_Perlman" },
  { cat: "Tech", diff: 2, kids: true, q: "Nii Quaynor set up some of Africa's first internet connections and helped many countries on the continent get online. Where is he from?", options: ["Ghana", "Kenya", "Senegal", "Egypt"], answer: 0, fact: "Quaynor was the founding chairman of AFRINIC, the body that hands out internet addresses across the African continent.", src: "https://en.wikipedia.org/wiki/Nii_Quaynor" },
  { cat: "Tech", diff: 1, kids: true, q: "Most of the data travelling between continents goes through what?", options: ["Satellites in orbit", "Cables lying on the sea floor", "Radio masts on mountain tops", "Aircraft carrying hard drives"], answer: 1, fact: "These cables carry 99% of the data crossing the oceans, and the Atlantic alone needs more than 50 repairs a year.", src: "https://en.wikipedia.org/wiki/Submarine_communications_cable" },
  { cat: "Tech", diff: 1, kids: true, q: "Inside a fibre-optic cable, what actually carries your data?", options: ["Pulses of light", "Compressed air", "Warm water", "Magnets"], answer: 0, fact: "The light reflects off the boundary inside the glass and cannot escape; in long-distance fibre the core is about 10 micrometres wide.", src: "https://en.wikipedia.org/wiki/Optical_fiber" },
  { cat: "Tech", diff: 1, kids: true, q: "In computing, what is a server?", options: ["A computer that answers requests from other computers", "A person who repairs broken laptops", "A kind of cable used in offices", "A screen that displays adverts in shops"], answer: 0, fact: "Most servers run with no monitor and no keyboard at all, bolted flat into racks and managed from somewhere else entirely.", src: "https://en.wikipedia.org/wiki/Server_(computing)" },
  { cat: "Tech", diff: 1, kids: true, q: "Your browser shows a padlock and the address begins with https. What does that actually tell you?", options: ["The connection is encrypted, so others along the way cannot read it", "The website has been checked and is safe to trust", "The page will load more quickly than usual", "The site carries no advertising at all"], answer: 0, fact: "Many people read the padlock as 'this site is safe'. It only means the journey is private — not that the destination is honest.", src: "https://en.wikipedia.org/wiki/HTTPS" },
  { cat: "Tech", diff: 2, kids: true, q: "Your Wi-Fi symbol is showing, but no website will load. What does that suggest?", options: ["Your device reached the router, but the router's link to the internet is down", "Wi-Fi and the internet are the same thing, so both have failed at once", "Your screen has broken and needs replacing", "Every website in the world has shut down"], answer: 0, fact: "The name Wi-Fi was invented by a branding firm in 1999, to be catchier than the standard's real name: IEEE 802.11b Direct Sequence.", src: "https://en.wikipedia.org/wiki/Wi-Fi" },
  { cat: "Tech", diff: 2, kids: true, q: "What is a web browser's main job?", options: ["To fetch the files that make up a page and draw them on your screen", "To store every website in the world on your device", "To create the internet connection your home uses", "To write the websites that you visit"], answer: 0, fact: "A page arrives as instructions, not as a picture — which is why the same site can look different in two different browsers.", src: "https://en.wikipedia.org/wiki/Web_browser" },
  { cat: "Tech", diff: 2, kids: false, q: "Data crossing the internet passes through machines called routers. What does a router decide?", options: ["Which network to hand each packet to next", "What the message inside actually says", "Who owns the website being visited", "How much the connection will cost"], answer: 0, fact: "A router reads only the destination written on a packet, then passes it to the next network — the packet crosses the world in hops.", src: "https://en.wikipedia.org/wiki/Router_(computing)" },
  { cat: "Tech", diff: 1, kids: true, q: "Who invented the World Wide Web, and gave it away rather than patenting it?", options: ["Tim Berners-Lee", "Bill Gates", "Steve Jobs", "Mark Zuckerberg"], answer: 0, fact: "He built it at CERN, a physics laboratory, so scientists could share documents — and released it with no patent and no royalties.", src: "https://en.wikipedia.org/wiki/Tim_Berners-Lee" },
  { cat: "Tech", diff: 2, kids: false, q: "How does a search engine already know what is on a page before you search for it?", options: ["Programs called crawlers visit pages in advance and index them", "It searches the whole internet the moment you press enter", "Website owners must submit every page to it by hand", "Your browser quietly sends it your browsing history"], answer: 0, fact: "A crawler hops from link to link; a small file named robots.txt asks it which parts of a site to leave alone.", src: "https://en.wikipedia.org/wiki/Web_crawler" },
  { cat: "Tech", diff: 1, kids: true, q: "In artificial intelligence, what is a 'model'?", options: ["A program that has worked out patterns from many examples", "A small physical replica of a computer system", "A person who tests new apps before release", "A type of screen used in laboratories"], answer: 0, fact: "Nobody writes the rules by hand: the program is shown examples, finds the pattern itself, then applies it to things it has never seen.", src: "https://en.wikipedia.org/wiki/Machine_learning" },
  { cat: "Tech", diff: 2, kids: false, q: "When an AI model is trained, why is part of the data deliberately kept back?", options: ["To test the model on examples it has never seen", "To save space on the storage system", "To sell that part of the data later on", "To make the training run finish faster"], answer: 0, fact: "That held-back portion is called the test set; without it, a model that had simply memorised its examples would look perfect.", src: "https://en.wikipedia.org/wiki/Training,_validation,_and_test_data_sets" },
  { cat: "Tech", diff: 2, kids: true, q: "A large language model — an LLM — is doing what when it writes you an answer?", options: ["Choosing the next piece of text, again and again", "Looking the answer up in a database of facts", "Asking a human being on the other end", "Copying the nearest matching web page"], answer: 0, fact: "These models are trained by hiding the next word in vast amounts of text and making the system guess it, over and over.", src: "https://en.wikipedia.org/wiki/Large_language_model" },
  { cat: "Tech", diff: 3, kids: false, q: "Before a language model reads your sentence, the text is chopped into pieces called tokens. What does that mean in practice?", options: ["One long word may become two or three tokens", "Every single letter becomes its own token", "Each whole sentence becomes one token", "Only the nouns are turned into tokens"], answer: 0, fact: "The usual method, byte-pair encoding, began in 1994 as a file-compression trick; the version behind GPT-4 knows about 100 000 tokens.", src: "https://en.wikipedia.org/wiki/Byte-pair_encoding" },
  { cat: "Tech", diff: 1, kids: true, q: "Why can a chatbot state something completely false with total confidence?", options: ["It produces plausible-sounding text and has no built-in check on truth", "It is deliberately lying to the person asking", "It has run out of memory while answering", "Someone typed the wrong answer into it"], answer: 0, fact: "In 2023 a New York lawyer cited six court decisions invented by a chatbot; the judge called one 'gibberish' and fined the lawyers 5 000 dollars.", src: "https://en.wikipedia.org/wiki/Hallucination_(artificial_intelligence)" },
  { cat: "Tech", diff: 1, kids: false, q: "An API — an application programming interface — is best described as what?", options: ["An agreed way for one program to ask another for something", "A type of computer chip used inside phones", "A program that stores all of your passwords", "The home page of a company's website"], answer: 0, fact: "It is often called a contract: it hides how a system works inside and exposes only the parts another program actually needs.", src: "https://en.wikipedia.org/wiki/API" },
  { cat: "Tech", diff: 3, kids: false, q: "The Model Context Protocol, published in 2024, was created to solve which problem?", options: ["Every AI tool needed its own custom connector to each data source", "Screens were too small to display long AI answers", "Models could not be trained on photographs at all", "Web pages were loading far too slowly for users"], answer: 0, fact: "Anthropic released it as an open standard, so any company can implement it — one shared connector instead of one built per tool.", src: "https://en.wikipedia.org/wiki/Model_Context_Protocol" },
  { cat: "Tech", diff: 2, kids: false, q: "'Vibe coding' describes which practice?", options: ["Describing what you want in ordinary language and letting an AI write the code", "Programming while listening to music", "Choosing a website's colours by feel", "Writing code with pen and paper"], answer: 0, fact: "Andrej Karpathy coined the phrase in February 2025; by the end of that year the Collins dictionary had made it its word of the year.", src: "https://en.wikipedia.org/wiki/Vibe_coding" },
  { cat: "Tech", diff: 1, kids: false, q: "What does it mean when software is called 'open source'?", options: ["Its source code can be read, changed and shared by anyone", "It is always free of charge to everyone", "It only works while you are connected", "It belongs to nobody and carries no licence"], answer: 0, fact: "'Free' here means freedom, not price — open-source software can be sold, and computers ship with Linux already installed.", src: "https://en.wikipedia.org/wiki/Open-source_software" },
  { cat: "Tech", diff: 2, kids: true, q: "Fei-Fei Li's team built ImageNet, a huge collection of labelled photographs. Why did it change artificial intelligence?", options: ["It gave image-recognition systems enough examples to learn from", "It made digital cameras far cheaper to produce", "It was the first website ever to show photographs", "It removed the need for any training at all"], answer: 0, fact: "More than 14 million photographs were labelled by hand — 49 000 people in 167 countries did the sorting.", src: "https://en.wikipedia.org/wiki/ImageNet" },
  { cat: "Tech", diff: 2, kids: true, q: "Joy Buolamwini tested commercial face-recognition systems. Whose faces did they get wrong most often?", options: ["Darker-skinned women", "Older men", "People wearing glasses", "Young children"], answer: 0, fact: "In the 2018 Gender Shades study with Timnit Gebru, errors reached 34.7% for darker-skinned women and under 1% for lighter-skinned men.", src: "https://en.wikipedia.org/wiki/Joy_Buolamwini" },
  { cat: "Tech", diff: 3, kids: false, q: "Data centres running AI use a great deal of water. Where does most of it actually go?", options: ["Into generating the electricity they consume", "Into the chips themselves as they are made", "Into washing and cleaning the servers", "Into moulding the plastic casings"], answer: 0, fact: "Data centres used roughly 560 billion litres of water in 2023 — about two thirds tied to power generation, a quarter to cooling.", src: "https://en.wikipedia.org/wiki/Environmental_impact_of_AI" },
  { cat: "Tech", diff: 1, kids: true, q: "Most AI training runs on graphics processing units — chips originally built to do what?", options: ["Draw the images in video games", "Store files safely for years", "Print photographs on paper", "Play music through speakers"], answer: 0, fact: "A modern one packs thousands of small calculation units working at once; built for pixels, they turned out to suit training AI models.", src: "https://en.wikipedia.org/wiki/Graphics_processing_unit" },
  { cat: "Tech", diff: 2, kids: true, q: "In the 1960s Joseph Weizenbaum wrote ELIZA, one of the first chatbots. What did its best-known script do?", options: ["Turned what you typed back into a question, like a therapist", "Solved long arithmetic problems", "Translated Russian into English", "Played games of chess"], answer: 0, fact: "Weizenbaum's own secretary asked him to leave the room so she could talk to ELIZA privately, though the program understood nothing.", src: "https://en.wikipedia.org/wiki/ELIZA" },
  { cat: "Tech", diff: 1, kids: true, q: "In 1997 the world chess champion Garry Kasparov lost a match to which machine?", options: ["Deep Blue", "Watson", "AlphaGo", "ENIAC"], answer: 0, fact: "It examined 200 million positions a second — power, not understanding. IBM dismantled it afterwards and refused Kasparov a rematch.", src: "https://en.wikipedia.org/wiki/Deep_Blue_(chess_computer)" },
  { cat: "Tech", diff: 2, kids: true, q: "In 2016 the program AlphaGo played five games of Go against Lee Sedol, one of the world's best players. What was the result?", options: ["AlphaGo won four games to one", "Lee Sedol won four games to one", "AlphaGo won all five games", "Lee Sedol won three games to two"], answer: 0, fact: "Lee Sedol's game-four win — via move 78, dubbed the 'divine move' — remains the only official game AlphaGo ever lost to a human.", src: "https://en.wikipedia.org/wiki/AlphaGo" },
  { cat: "Tech", diff: 3, kids: false, q: "Nearly every modern language model is built on one design published in 2017. What is it called?", options: ["The transformer", "The perceptron", "The compiler", "The spreadsheet"], answer: 0, fact: "The paper introducing it was titled 'Attention Is All You Need' — its attention step weighs which earlier words matter most.", src: "https://en.wikipedia.org/wiki/Transformer_(deep_learning)" },
  { cat: "Tech", diff: 2, kids: true, q: "Why does rewording your request often change what an AI gives back?", options: ["The wording is part of the input, so it shifts what the model produces", "The model has moods and sometimes gets bored", "A completely different model answers each time", "The internet itself changed in between"], answer: 0, fact: "Simply adding 'let's think step by step' was found to improve a model's answers on reasoning problems, with nothing else changed.", src: "https://en.wikipedia.org/wiki/Prompt_engineering" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "The oldest known large terracotta sculptures in West Africa are named after the village of Nok, in which country?", options: ["Senegal", "Nigeria", "Kenya", "Morocco"], answer: 1, fact: "The Nok culture began around 1500 BCE, and iron-working may have developed there between roughly 750 and 550 BCE.", src: "https://en.wikipedia.org/wiki/Nok_culture" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "Which West African kingdom's most sacred object is a golden stool that, by tradition, came down from the sky?", options: ["The Zulu kingdom", "Buganda", "The Asante (Ashanti) kingdom", "The Kingdom of Kongo"], answer: 2, fact: "The Golden Stool must never touch bare ground and nobody sits on it — a new Asante king is only lowered over it.", src: "https://en.wikipedia.org/wiki/Golden_Stool" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "How many months does the Ethiopian calendar, still in everyday use in Ethiopia, have?", options: ["10", "12", "13", "14"], answer: 2, fact: "Twelve months of exactly 30 days plus a short 13th month of five or six days; the Ethiopian year runs 7 to 8 years behind ours.", src: "https://en.wikipedia.org/wiki/Ethiopian_calendar" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "The carved birds found at Great Zimbabwe are now the national emblem of Zimbabwe. What stone are they carved from?", options: ["Marble", "Soapstone", "Obsidian", "Granite"], answer: 1, fact: "Eight of the birds are known; four were returned to Zimbabwe in 1981, and the bird now appears on the country's flag and coins.", src: "https://en.wikipedia.org/wiki/Zimbabwe_Bird" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "The kingdom of Buganda, led by a king called the Kabaka, lies inside which modern country?", options: ["Kenya", "Zambia", "Senegal", "Uganda"], answer: 3, fact: "Buganda was founded between the 1100s and the 1300s, and its people call Lake Victoria Nalubaale, 'mother of the gods'.", src: "https://en.wikipedia.org/wiki/Buganda" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "A small rhinoceros covered in gold foil was buried with a ruler at Mapungubwe, a kingdom in which country today?", options: ["South Africa", "Egypt", "Ghana", "Somalia"], answer: 0, fact: "The rhino is carved wood wrapped in gold; Mapungubwe flourished about 1220–1300 where the Shashe and Limpopo rivers meet.", src: "https://en.wikipedia.org/wiki/Mapungubwe" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "Shaka, famous for reorganising his army into regiments by age group, was king of which southern African kingdom?", options: ["The Asante kingdom", "The Zulu kingdom", "Buganda", "The Mutapa kingdom"], answer: 1, fact: "His 'bull horn' formation sent fast young regiments round both flanks while veterans in the 'chest' pinned the enemy in place.", src: "https://en.wikipedia.org/wiki/Shaka" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "Queen Amina, who led armies and ringed her towns with earth walls, ruled the Hausa state of Zazzau in what is now which country?", options: ["Sudan", "Angola", "Tunisia", "Nigeria"], answer: 3, fact: "Many of those ramparts are still called ganuwar Amina — 'Amina's walls' — and some of them survive today.", src: "https://en.wikipedia.org/wiki/Amina_of_Zazzau" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "The Merina kingdom, ruled from Antananarivo, came to dominate which large island off Africa's south-east coast?", options: ["Zanzibar", "Mauritius", "The Comoros", "Madagascar"], answer: 3, fact: "Merina rulers kept two capitals: Antananarivo for government, and the hilltop town of Ambohimanga as their sacred royal seat.", src: "https://en.wikipedia.org/wiki/Merina_Kingdom" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "The Kanem-Bornu empire, which lasted around a thousand years, grew up around which African lake?", options: ["Lake Chad", "Lake Victoria", "Lake Tanganyika", "Lake Malawi"], answer: 0, fact: "It ran from about 700 CE to 1902 — among the longest-lived states in world history — and its lands lie in seven countries today.", src: "https://en.wikipedia.org/wiki/Kanem%E2%80%93Bornu_Empire" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "Kilwa Kisiwani, a wealthy Swahili trading city of coral-stone palaces, lies off the coast of which country today?", options: ["Ghana", "Namibia", "Tanzania", "Egypt"], answer: 2, fact: "Passing through in 1331, the traveller Ibn Battuta called Kilwa one of the most beautiful cities in the world.", src: "https://en.wikipedia.org/wiki/Kilwa_Kisiwani" },
  { cat: "History", region: "Africa", diff: 1, kids: true, q: "The kingdom of Dahomey had an army regiment made up entirely of women. Its Fon name, Mino, means what?", options: ["Our mothers", "The lionesses", "The king's shield", "Daughters of iron"], answer: 0, fact: "At their height in the 1800s they numbered between 1,000 and 6,000 — about a third of Dahomey's whole army.", src: "https://en.wikipedia.org/wiki/Dahomey_Amazons" },
  { cat: "History", region: "Africa", diff: 2, kids: true, q: "In the 300s CE the kingdom of Aksum became one of the first states anywhere to adopt which religion officially?", options: ["Buddhism", "Christianity", "Islam", "Zoroastrianism"], answer: 1, fact: "The 3rd-century teacher Mani ranked Aksum among the world's four great powers, alongside Rome, Persia and China.", src: "https://en.wikipedia.org/wiki/Kingdom_of_Aksum" },
  { cat: "History", region: "Africa", diff: 2, kids: true, q: "Akan craftworkers in West Africa cast tiny brass figures of animals, people and scenes. What were they used for?", options: ["Weighing gold dust", "Playing a board game", "Fastening cloaks", "Marking graves"], answer: 0, fact: "Around four million were cast between about 1400 and 1900, many shaped as symbols and scenes that stand for Akan proverbs.", src: "https://en.wikipedia.org/wiki/Akan_goldweights" },
  { cat: "History", region: "Africa", diff: 2, kids: false, q: "The strikingly lifelike royal heads made at Ile-Ife between about 1200 and 1400 were the work of which people?", options: ["The Zulu", "The Amhara", "The Wolof", "The Yoruba"], answer: 3, fact: "Ife artists often gave rulers and gods oversized heads, holding that a person's ase — life force and authority — sits in the head.", src: "https://en.wikipedia.org/wiki/Ife" },
  { cat: "History", region: "Africa", diff: 2, kids: false, q: "Around Benin City the Edo dug vast ditch-and-rampart earthworks called iya. What record do they hold?", options: ["Oldest stone bridge in Africa", "Longest earthworks of the pre-machine era", "Tallest earthen tower on Earth", "Widest medieval canal"], answer: 1, fact: "The earthworks total roughly 16,000 km — Guinness calls them the longest of the pre-mechanical era; the inner-city moat alone runs 12 km.", src: "https://en.wikipedia.org/wiki/Walls_of_Benin" },
  { cat: "History", region: "Africa", diff: 2, kids: false, q: "Yaa Asantewaa led the Asante to war in 1900 after a British governor demanded what?", options: ["The kingdom's gold mines", "The royal palace at Kumasi", "The Golden Stool", "The Asante crown jewels"], answer: 2, fact: "Queen Mother of Ejisu, she is the only woman ever chosen to command an Asante army, leading some 5,000 fighters.", src: "https://en.wikipedia.org/wiki/Yaa_Asantewaa" },
  { cat: "History", region: "Africa", diff: 2, kids: false, q: "Sundiata Keita, who founded the Mali Empire after winning the Battle of Kirina, was the first ruler to take which title?", options: ["Oba", "Askia", "Kabaka", "Mansa"], answer: 3, fact: "His story is still performed by griots as the Epic of Sundiata, carried by word of mouth for nearly eight centuries.", src: "https://en.wikipedia.org/wiki/Sundiata_Keita" },
  { cat: "History", region: "Africa", diff: 2, kids: true, q: "The Timbuktu Manuscripts, hundreds of thousands of documents kept in Malian family libraries, are mostly written in which script?", options: ["Arabic script", "Latin script", "Greek script", "Chinese characters"], answer: 0, fact: "Some are in Ajami — Songhay, Fula or Tamasheq written with Arabic letters — and they cover astronomy, medicine and law.", src: "https://en.wikipedia.org/wiki/Timbuktu_Manuscripts" },
  { cat: "History", region: "Africa", diff: 2, kids: true, q: "Around 730 BCE, kings from the Kushite city of Napata conquered Egypt and ruled it as its 25th Dynasty. Where was Napata?", options: ["In present-day Libya", "In present-day Sudan", "In present-day Israel", "In present-day Chad"], answer: 1, fact: "Piye had his victory carved on a great stela set up at Napata, and his family went on to rule Egypt as pharaohs.", src: "https://en.wikipedia.org/wiki/Piye" },
  { cat: "History", region: "Africa", diff: 2, kids: true, q: "Harar, a walled city of narrow lanes packed with mosques and shrines, is in which country?", options: ["Mali", "Mozambique", "Ethiopia", "Algeria"], answer: 2, fact: "UNESCO counts 82 mosques and 102 shrines behind Harar's 16th-century walls, which are pierced by five ancient gates.", src: "https://en.wikipedia.org/wiki/Harar" },
  { cat: "History", region: "Africa", diff: 2, kids: true, q: "Emperor Fasilides built a walled compound of stone castles and palaces at Gondar in the 1600s. Gondar is in which country?", options: ["Egypt", "Namibia", "Senegal", "Ethiopia"], answer: 3, fact: "Each later emperor added his own castle inside the same walls, so Fasil Ghebbi grew into a royal city of towers and churches.", src: "https://en.wikipedia.org/wiki/Fasil_Ghebbi" },
  { cat: "History", region: "Africa", diff: 2, kids: false, q: "The Kingdom of Kongo, whose capital was Mbanza Kongo, chose its kings in which way?", options: ["By the eldest son only", "By a council of electors", "By lottery", "By single combat"], answer: 1, fact: "The royal title manikongo comes from Mwene Kongo, 'lord of Kongo'; the kingdom's lands are now split between four countries.", src: "https://en.wikipedia.org/wiki/Kingdom_of_Kongo" },
  { cat: "History", region: "Africa", diff: 2, kids: false, q: "Nzinga Mbande ruled the kingdoms of Ndongo and Matamba, in what is now which country?", options: ["Kenya", "Morocco", "Angola", "Niger"], answer: 2, fact: "She urged people held on Portuguese plantations to escape to her lands, where she granted them land and titles.", src: "https://en.wikipedia.org/wiki/Nzinga_of_Ndongo_and_Matamba" },
  { cat: "History", region: "Africa", diff: 2, kids: false, q: "The Kilwa Sultanate grew immensely rich after taking control of Sofala around 1178. What flowed through Sofala?", options: ["Silk from China", "Amber from the Baltic", "Tin from Britain", "Gold from the Zimbabwe plateau"], answer: 3, fact: "Kilwa minted its own coins — some have turned up as far away as the Wessel Islands off northern Australia.", src: "https://en.wikipedia.org/wiki/Kilwa_Sultanate" },
  { cat: "History", region: "Africa", diff: 2, kids: false, q: "The Shona rulers of the Mutapa empire held the title Mwene Mutapa. What does it mean?", options: ["Keeper of the cattle", "Son of the river", "Lord of the conquered lands", "Voice of the ancestors"], answer: 2, fact: "Mutapa rose in the 1400s as Great Zimbabwe declined, and controlled the gold reaching the Indian Ocean ports.", src: "https://en.wikipedia.org/wiki/Kingdom_of_Mutapa" },
  { cat: "History", region: "Africa", diff: 2, kids: false, q: "At its height the Almoravid empire reached from the Sahara across the strait into which part of Europe?", options: ["Sicily", "Greece", "Provence", "Iberia (Spain and Portugal)"], answer: 3, fact: "Almoravid rule stretched from the Sahara to Zaragoza, tying West African gold routes and Iberian cities under one government.", src: "https://en.wikipedia.org/wiki/Almoravid_dynasty" },
  { cat: "History", region: "Africa", diff: 2, kids: true, q: "Bronze vessels and ornaments of astonishing delicacy, cast around 850 CE, were excavated at Igbo-Ukwu in which country?", options: ["Ghana", "Cameroon", "Mali", "Nigeria"], answer: 3, fact: "Its smiths used the lost-wax method, and the burials held glass beads brought in from far away by long-distance trade.", src: "https://en.wikipedia.org/wiki/Igbo-Ukwu" },
  { cat: "History", region: "Africa", diff: 3, kids: false, q: "Imam Ahmad ibn Ibrahim al-Ghazi, who led the Adal Sultanate's armies in the 1500s, was nicknamed Gragn and Gurey. What do those names mean?", options: ["The left-handed", "The lion", "The wanderer", "The young one"], answer: 0, fact: "His war with the Ethiopian empire ran from 1529 to 1543 and reshaped the Horn of Africa; Ethiopians and Somalis still recall it.", src: "https://en.wikipedia.org/wiki/Ahmad_ibn_Ibrahim_al-Ghazi" },
  { cat: "History", region: "Africa", diff: 3, kids: false, q: "Court historians of the Luba empire recited kings, migrations and laws while reading a lukasa. What is a lukasa?", options: ["A carved drum", "A knotted cord", "A beaded wooden board", "A painted clay tablet"], answer: 2, fact: "Luba 'men of memory' ran their fingers over its beads and shells; each colour and pattern cued a part of the story.", src: "https://en.wikipedia.org/wiki/Lukasa" },
  { cat: "History", region: "Africa", diff: 3, kids: false, q: "Which town on the Niger River in Mali, first settled around 250 BCE, is among the oldest known cities in West Africa?", options: ["Gao", "Kano", "Djenné-Djenno", "Ouagadougou"], answer: 2, fact: "Its people smelted iron, grew rice and traded far afield centuries before any Arab contact, showing West African cities grew locally.", src: "https://en.wikipedia.org/wiki/Djenn%C3%A9-Djenno" },
  { cat: "History", region: "Africa", diff: 3, kids: false, q: "In the Yoruba empire of Oyo, the council known as the Oyo Mesi could force the ruler, the Alaafin, to do what?", options: ["Take his own life", "Marry abroad", "Lead every battle", "Move the capital"], answer: 0, fact: "The seven councillors sent him an empty calabash or a dish of parrot's eggs — a silent verdict that his reign was over.", src: "https://en.wikipedia.org/wiki/Oyo_Empire" },
  { cat: "History", region: "Africa", diff: 3, kids: false, q: "Nana Asma'u organised a women's education network known as the yan-taru across which West African state?", options: ["The Asante kingdom", "The Sokoto Caliphate", "The Kingdom of Kongo", "The Adal Sultanate"], answer: 1, fact: "She wrote more than sixty works in Arabic, Fula and Hausa, and her travelling teachers, the jajis, carried lessons village to village.", src: "https://en.wikipedia.org/wiki/Nana_Asma%27u" },
  { cat: "History", region: "Africa", diff: 3, kids: false, q: "Which ruling queen of Kush fought a three-year war against Roman Egypt in the 20s BCE?", options: ["Hatshepsut", "Nefertiti", "Amanirenas", "Dido"], answer: 2, fact: "Her soldiers cut the head from a bronze statue of Augustus and buried it beneath a temple's steps at Meroë, preserving it intact.", src: "https://en.wikipedia.org/wiki/Amanirenas" },
  { cat: "History", region: "Africa", diff: 3, kids: false, q: "The Kingdom of Kush set aside Egyptian hieroglyphs and wrote its own language in its own alphabet. What is that script called?", options: ["Meroitic", "Ge'ez", "Tifinagh", "Nsibidi"], answer: 0, fact: "It was cracked in 1909 using Egyptian names, so the words can be sounded out — yet the language itself is still barely understood.", src: "https://en.wikipedia.org/wiki/Meroitic_script" },
  { cat: "History", region: "Africa", diff: 3, kids: false, q: "The Baqt, one of the longest-lasting treaties in history, was agreed around 652 between Egypt's new Muslim rulers and which Nubian kingdom?", options: ["Aksum", "Kanem", "Makuria", "Mutapa"], answer: 2, fact: "It held for roughly 700 years: each year Nubia sent 360 enslaved people to Egypt, and Egypt sent back wheat and lentils.", src: "https://en.wikipedia.org/wiki/Baqt" },

  { cat: "Nature", diff: 1, kids: true, q: "Which of these mammals lays eggs?", options: ["The platypus", "The otter", "The beaver", "The water vole"], answer: 0, fact: "A platypus hunts with eyes, ears and nose shut — its bill senses the faint electric fields of prey buried in the mud.", src: "https://en.wikipedia.org/wiki/Platypus" },
  { cat: "Nature", diff: 1, kids: true, q: "What does a dromedary camel store in its hump?", options: ["Water", "Fat", "Air", "Milk"], answer: 1, fact: "A dromedary can drink over 100 litres in one session — about a bathtub's worth, in roughly ten minutes.", src: "https://en.wikipedia.org/wiki/Dromedary" },
  { cat: "Nature", diff: 1, kids: true, q: "Why are flamingos pink?", options: ["They hatch that way", "Because of pigments in the food they eat", "Because they stand in the sun all day", "Because of minerals in the water"], answer: 1, fact: "Chicks hatch grey and take years to turn pink; adults even preen carotenoid-rich oil onto their feathers to deepen the colour.", src: "https://en.wikipedia.org/wiki/Greater_flamingo" },
  { cat: "Nature", diff: 1, kids: true, q: "How often does a three-toed sloth climb down from the trees to go to the toilet?", options: ["Several times a day", "About once a week", "Only in the rainy season", "About once a year"], answer: 1, fact: "Almost every mammal has seven neck bones, giraffes included — three-toed sloths break the rule with up to nine.", src: "https://en.wikipedia.org/wiki/Three-toed_sloth" },
  { cat: "Nature", diff: 1, kids: true, q: "In emperor penguins, who keeps the single egg warm through the Antarctic winter?", options: ["The mother alone", "The father alone", "Both parents in turns", "The whole colony together"], answer: 1, fact: "He balances the egg on his feet for over two months in −40 °C winds, eating nothing until it hatches.", src: "https://en.wikipedia.org/wiki/Emperor_penguin" },
  { cat: "Nature", diff: 1, kids: true, q: "A coral reef is built by which kind of living thing?", options: ["Underwater plants", "Tiny animals", "Giant clams", "Shell-forming bacteria"], answer: 1, fact: "Coral polyps farm algae inside their own cells; when the sea gets too warm they expel them and turn bone white.", src: "https://en.wikipedia.org/wiki/Coral" },
  { cat: "Nature", diff: 1, kids: true, q: "What does a female common cuckoo do with her eggs?", options: ["She buries them in warm sand", "She lays them in other birds' nests", "She nests in a hole in a tree", "She keeps them tucked under her wings"], answer: 1, fact: "Over 100 species are targeted, and each female cuckoo lineage lays eggs matching the colour and pattern of just one host's.", src: "https://en.wikipedia.org/wiki/Common_cuckoo" },
  { cat: "Nature", diff: 2, kids: true, q: "Monarch butterflies travel thousands of kilometres from Canada to Mexico. How many generations does the full round trip take?", options: ["One", "Three or four", "Twelve", "Fifty"], answer: 1, fact: "No monarch lives long enough to make the round trip — the ones that reach the Mexican fir forests have never been there before.", src: "https://en.wikipedia.org/wiki/Monarch_butterfly_migration" },
  { cat: "Nature", diff: 2, kids: false, q: "The seeds of many mangrove trees do something almost no other tree's seeds do. What?", options: ["They germinate while still attached to the parent tree", "They are pollinated only by bats", "They survive being burnt in a fire", "They grow entirely underground"], answer: 0, fact: "The dagger-shaped seedling drops into the sea and can drift, alive, for up to a year before rooting on a new shore.", src: "https://en.wikipedia.org/wiki/Mangrove" },
  { cat: "Nature", diff: 2, kids: true, q: "The axolotl, an amphibian from the lakes of Mexico City, is famous for being able to do what?", options: ["Change colour to match the lake bed", "Regrow lost legs and parts of its brain", "Survive months frozen solid", "Produce venom from its skin"], answer: 1, fact: "Axolotls never grow up: they keep their feathery gills, stay in the water for life and breed as overgrown larvae.", src: "https://en.wikipedia.org/wiki/Axolotl" },
  { cat: "Nature", diff: 2, kids: true, q: "Tardigrades, or 'water bears', are under a millimetre long. What did they survive in 2007?", options: ["A trip into the vacuum of space", "A volcanic eruption", "A year sealed inside a glacier", "A pass through a jet engine"], answer: 0, fact: "A tardigrade dries into a barrel-shaped 'tun' with almost no water and near-zero metabolism, then rehydrates years later.", src: "https://en.wikipedia.org/wiki/Tardigrade" },
  { cat: "Nature", diff: 2, kids: true, q: "What is the mantis shrimp's most famous weapon?", options: ["A cloud of black ink", "A punching claw", "A venomous sting", "An electric shock"], answer: 1, fact: "The claw hits at 23 metres a second, tearing vapour bubbles into the water that collapse against the prey a second time.", src: "https://en.wikipedia.org/wiki/Mantis_shrimp" },
  { cat: "Nature", diff: 2, kids: true, q: "The world's largest single flower, up to a metre across, attracts its pollinators by smelling of what?", options: ["Rotting meat", "Vanilla", "Fresh rain", "Burnt sugar"], answer: 0, fact: "Rafflesia has no leaves, no stem and no roots — it lives hidden inside a jungle vine and surfaces only to flower.", src: "https://en.wikipedia.org/wiki/Rafflesia_arnoldii" },
  { cat: "Nature", diff: 2, kids: true, q: "A pangolin's overlapping scales are made of the same material as what?", options: ["Human fingernails", "Sea shells", "Bone", "Tooth enamel"], answer: 0, fact: "Pangolins are the most trafficked wild mammals on Earth, hunted for those scales across Africa and Asia.", src: "https://en.wikipedia.org/wiki/Pangolin" },
  { cat: "Nature", diff: 2, kids: true, q: "The okapi of the Congo rainforest has striped legs like a zebra. Which animal is its closest living relative?", options: ["The zebra", "The giraffe", "The antelope", "The tapir"], answer: 1, fact: "Its tongue is about 46 cm long — enough to reach around and groom its own eyes and ears.", src: "https://en.wikipedia.org/wiki/Okapi" },
  { cat: "Nature", diff: 2, kids: true, q: "What do leafcutter ants do with the pieces of leaf they carry home?", options: ["Eat them", "Feed a fungus they farm", "Build walls with them", "Trade them with other colonies"], answer: 1, fact: "The ants carry antibiotic-producing bacteria on their bodies to keep moulds out of the fungus garden.", src: "https://en.wikipedia.org/wiki/Leafcutter_ant" },
  { cat: "Nature", diff: 2, kids: true, q: "How does an archerfish knock insects off leaves hanging above the water?", options: ["It leaps up and grabs them", "It spits a jet of water at them", "It slaps the branch with its tail", "It stuns them with flashes of light"], answer: 1, fact: "It corrects for the way light bends at the surface, aiming at where the insect really is, not where it appears to be.", src: "https://en.wikipedia.org/wiki/Archerfish" },
  { cat: "Nature", diff: 2, kids: true, q: "The electric eel is not actually an eel. What kind of fish is it?", options: ["A knifefish", "A catfish", "A lamprey", "A ray"], answer: 0, fact: "One species, Electrophorus voltai, has been measured at 860 volts — the strongest shock produced by any animal.", src: "https://en.wikipedia.org/wiki/Electric_eel" },
  { cat: "Nature", diff: 2, kids: true, q: "What does a bombardier beetle spray at an attacker?", options: ["A sticky glue", "A boiling hot chemical jet", "A cloud of pollen", "A jet of sea water"], answer: 1, fact: "It mixes two harmless chemicals in a reinforced chamber; the reaction nears 100 °C and fires with an audible pop.", src: "https://en.wikipedia.org/wiki/Bombardier_beetle" },
  { cat: "Nature", diff: 2, kids: true, q: "The smallest bird in the world, barely 6 cm long, lives on which island?", options: ["Cuba", "Madagascar", "Sri Lanka", "Iceland"], answer: 0, fact: "The bee hummingbird lays eggs about the size of a coffee bean and beats its wings up to 200 times a second.", src: "https://en.wikipedia.org/wiki/Bee_hummingbird" },
  { cat: "Nature", diff: 2, kids: true, q: "On Christmas Island in the Indian Ocean, millions of red crabs march to the sea each year. What has been built for them?", options: ["Bridges and tunnels around the roads", "Floating rafts", "Heated shelters", "Artificial rivers"], answer: 0, fact: "Aluminium barriers funnel them into underpasses, and a five-metre-high crab bridge lifts them over Murray Road.", src: "https://en.wikipedia.org/wiki/Christmas_Island_red_crab" },
  { cat: "Nature", diff: 2, kids: true, q: "The dodo lived only on the island of Mauritius. Which living bird is its closest relative?", options: ["The ostrich", "The pigeon", "The penguin", "The pelican"], answer: 1, fact: "Its closest known living cousin is the Nicobar pigeon, an iridescent green bird of South East Asian islands.", src: "https://en.wikipedia.org/wiki/Dodo" },
  { cat: "Nature", diff: 2, kids: false, q: "In meteorology, what defines a monsoon?", options: ["A seasonal reversal of the prevailing winds", "A single very heavy rainstorm", "A cold current rising from the deep ocean", "A dust storm blown off nearby deserts"], answer: 0, fact: "Meteorologists no longer see monsoons as giant sea breezes; they track the yearly north-south swing of the Intertropical Convergence Zone.", src: "https://en.wikipedia.org/wiki/Monsoon" },
  { cat: "Nature", diff: 2, kids: true, q: "Six of the world's eight baobab species grow naturally on just one island. Which one?", options: ["Madagascar", "Sri Lanka", "Borneo", "Cuba"], answer: 0, fact: "A baobab trunk can hold up to 120,000 litres of water — enough to carry the tree through years of drought.", src: "https://en.wikipedia.org/wiki/Adansonia" },
  { cat: "Nature", diff: 2, kids: true, q: "The superb lyrebird of Australia is famous for which ability?", options: ["Copying almost any sound it hears", "Flying backwards", "Diving deeper than any other bird", "Changing the colour of its feathers"], answer: 0, fact: "Up to 80% of a male's song is borrowed from other birds — and captive lyrebirds have copied chainsaws and camera shutters.", src: "https://en.wikipedia.org/wiki/Superb_lyrebird" },
  { cat: "Nature", diff: 2, kids: true, q: "The leatherback is the only sea turtle that lacks what?", options: ["A hard bony shell", "Flippers", "Lungs", "A tail"], answer: 0, fact: "It chases jellyfish down to 1,280 m and can hold its body 18 °C warmer than the cold water around it.", src: "https://en.wikipedia.org/wiki/Leatherback_sea_turtle" },
  { cat: "Nature", diff: 3, kids: false, q: "Most land plants trade with fungi at their roots. What does the plant hand over in return for water and minerals?", options: ["Sugars made by photosynthesis", "Oxygen", "Seeds", "Nitrogen taken from the air"], answer: 0, fact: "These root-fungus partnerships, called mycorrhizas, are found in about 80% of plant species — soil is a trading floor.", src: "https://en.wikipedia.org/wiki/Mycorrhiza" },
  { cat: "Nature", diff: 3, kids: false, q: "The naked mole-rat of East Africa was the first mammal found to live like which insects?", options: ["Termites, with a single breeding queen", "Butterflies, migrating in swarms", "Fireflies, signalling with light", "Cicadas, emerging every 17 years"], answer: 0, fact: "It also feels no pain from acid or chilli, strongly resists cancer, and can survive 18 minutes with no oxygen at all.", src: "https://en.wikipedia.org/wiki/Naked_mole-rat" },
  { cat: "Nature", diff: 3, kids: false, q: "In 2022 a young bar-tailed godwit flew non-stop from Alaska to Tasmania. How long was it in the air without landing?", options: ["11 days", "20 hours", "3 days", "40 days"], answer: 0, fact: "It covered at least 13,560 km without once stopping to eat, drink or rest — the longest flight ever recorded.", src: "https://en.wikipedia.org/wiki/Bar-tailed_godwit" },
  { cat: "Nature", diff: 3, kids: false, q: "The jellyfish Turritopsis dohrnii is nicknamed 'immortal' because, when injured or starving, it can do what?", options: ["Turn back into its young polyp stage", "Split into two identical adults", "Freeze itself for decades", "Regrow from a single tentacle"], answer: 0, fact: "Its cells switch identity — transdifferentiation — so the adult rebuilds itself as a colony of polyps that buds new jellyfish.", src: "https://en.wikipedia.org/wiki/Turritopsis_dohrnii" },
  { cat: "Nature", diff: 3, kids: true, q: "In Oregon's Malheur National Forest, a single organism spreads across 9 km² and is thought to be about 8,000 years old. What is it?", options: ["A fungus", "A stand of pine trees", "A cushion of moss", "A colony of ants"], answer: 0, fact: "Nearly all of it is a hidden web of threads through the soil; above ground you only see honey mushrooms in autumn.", src: "https://en.wikipedia.org/wiki/Armillaria_ostoyae" },
  { cat: "Nature", diff: 3, kids: false, q: "El Niño, the Pacific warming that shifts weather worldwide, was named by sailors and fishermen of which country?", options: ["Peru", "Japan", "Indonesia", "Australia"], answer: 0, fact: "They called it 'the Christ Child' because the warm current arrived around Christmas — and drove the fish away.", src: "https://en.wikipedia.org/wiki/El_Ni%C3%B1o" },
  { cat: "Nature", diff: 3, kids: true, q: "The aye-aye, a lemur of Madagascar, finds grubs hidden inside wood using which method?", options: ["Tapping the wood and listening for hollows", "Smelling them through the bark", "Following ant trails", "Watching for woodpecker holes"], answer: 0, fact: "It then gnaws a hole and hooks the grub out with a skeletal middle finger that swivels on a ball-and-socket joint.", src: "https://en.wikipedia.org/wiki/Aye-aye" },
  { cat: "Nature", diff: 3, kids: false, q: "In Mozambique, Yao honey-hunters call out and a wild bird answers, then leads them to a bees' nest. Which bird?", options: ["The greater honeyguide", "The African grey parrot", "The hornbill", "The secretarybird"], answer: 0, fact: "Neither partner is tamed: the bird gets beeswax it cannot reach alone, and Yao hunters find nests far faster.", src: "https://en.wikipedia.org/wiki/Greater_honeyguide" },
  { cat: "Nature", diff: 3, kids: false, q: "In a clownfish group, what happens when the breeding female dies?", options: ["Her male partner changes sex and replaces her", "The group abandons its anemone", "A female from a neighbouring group moves in", "The group stops breeding for a year"], answer: 0, fact: "The switch takes months or years: his brain feminises first, then his body — and the largest youngster becomes the new male.", src: "https://en.wikipedia.org/wiki/Clownfish" },
  { cat: "Nature", diff: 3, kids: false, q: "In many deep-sea anglerfish, what happens to the tiny male when he finds a female?", options: ["He bites on and fuses into her body", "He is eaten straight away", "He guards the eggs alone", "He carries her up to the surface"], answer: 0, fact: "In one species the male is 6 mm long beside a 50 mm female — their immune systems are altered so the tissues can merge.", src: "https://en.wikipedia.org/wiki/Anglerfish" },
  { cat: "Nature", diff: 3, kids: true, q: "Welwitschia, a plant of the Namib Desert that can live over 1,000 years, grows how many leaves in its entire life?", options: ["Two", "None", "Twelve", "A new one each year"], answer: 0, fact: "Those two leaves never stop growing — they split and fray into a tangle sprawling several metres across the sand.", src: "https://en.wikipedia.org/wiki/Welwitschia" },
  { cat: "Nature", diff: 3, kids: true, q: "The fungus Ophiocordyceps unilateralis takes over an infected ant's behaviour. What does the ant then do?", options: ["Clamps its jaws onto a leaf vein and dies there", "Returns to the nest to infect the queen", "Buries itself deep in the soil", "Attacks a neighbouring colony"], answer: 0, fact: "The fungus then grows a stalk out of the dead ant's head and rains spores down onto the trail below.", src: "https://en.wikipedia.org/wiki/Ophiocordyceps_unilateralis" },
  { cat: "Nature", diff: 3, kids: true, q: "African dung beetles roll their dung balls in a straight line at night by steering with what?", options: ["The Milky Way", "The Earth's magnetic field", "Scent trails", "The sound of the wind"], answer: 0, fact: "A cousin, Scarabaeus zambesianus, was the first animal ever found to navigate by the polarised light of the Moon.", src: "https://en.wikipedia.org/wiki/Dung_beetle" },
  { cat: "Nature", diff: 3, kids: false, q: "In 1938 museum curator Marjorie Courtenay-Latimer spotted a strange fish on a South African quayside. What had she found?", options: ["A coelacanth, believed long extinct", "A newborn great white shark", "An unknown species of whale", "A living trilobite"], answer: 0, fact: "Coelacanths have fleshy, limb-like fins and were known only from fossils until that day; a second species turned up in Indonesia in 1997.", src: "https://en.wikipedia.org/wiki/Coelacanth" },
  { cat: "Arts", diff: 1, kids: true, q: "The kora, a 21-string instrument played across West Africa, has a sound box made from what?", options: ["A large gourd covered with cow skin", "An elephant tusk hollowed from end to end", "A clay pot sealed with beeswax", "A coconut shell carved in half"], answer: 0, fact: "Kora players traditionally come from jali families — historians, genealogists and storytellers who carry a people's memory in song.", src: "https://en.wikipedia.org/wiki/Kora_(instrument)" },
  { cat: "Arts", diff: 2, kids: false, q: "Nigerian musician Fela Kuti named the style he built from Yoruba music, highlife, jazz and funk. What did he call it?", options: ["Afrobeat", "Soukous", "Highlife", "Kwaito"], answer: 0, fact: "His Lagos commune, the Kalakuta Republic, declared itself independent of military rule; 1,000 soldiers stormed and burnt it down in 1977.", src: "https://en.wikipedia.org/wiki/Fela_Kuti" },
  { cat: "Arts", diff: 3, kids: false, q: "Malian guitarist Ali Farka Touré was often nicknamed 'the African John Lee Hooker'. How did he describe the link with American blues?", options: ["He said the blues had travelled out of Africa, not into it", "He said he had copied Hooker's records note for note", "He said the two kinds of music shared nothing at all", "He said the blues had begun in Mali in the 1950s"], answer: 0, fact: "'Ali and Toumani', his duet album with kora master Toumani Diabaté, came out four years after his death and won a Grammy.", src: "https://en.wikipedia.org/wiki/Ali_Farka_Tour%C3%A9" },
  { cat: "Arts", diff: 1, kids: true, q: "Ghanaian kente cloth is assembled from what, before being sewn into one large cloth?", options: ["Narrow woven strips", "Squares of printed cotton", "Panels of knotted rope", "Sheets of beaten bark"], answer: 0, fact: "Asante tradition credits weavers at Bonwire who studied a spider's web — the web of Anansi, the trickster of Akan stories.", src: "https://en.wikipedia.org/wiki/Kente_cloth" },
  { cat: "Arts", diff: 3, kids: false, q: "Malian bògòlanfini cloth gets its dark patterns from a paint made of what?", options: ["River mud fermented for up to a year", "Crushed charcoal mixed with palm oil", "Ground indigo seeds", "Powdered iron ore and honey"], answer: 0, fact: "The cloth is dyed yellow with n'gallama leaves first; at the end the unpainted areas are bleached white, leaving the pattern behind.", src: "https://en.wikipedia.org/wiki/B%C3%B2g%C3%B2lanfini" },
  { cat: "Arts", diff: 3, kids: false, q: "Senegal's Ousmane Sembène was already a novelist when he turned to cinema. Why did he switch?", options: ["Film could reach people who did not read", "Novels had been banned across Senegal", "The French government asked him to switch", "He lost his sight and could no longer write"], answer: 0, fact: "His 1966 film 'Black Girl' was the first feature released by a director from sub-Saharan Africa; he called cinema 'the people's night school'.", src: "https://en.wikipedia.org/wiki/Ousmane_Semb%C3%A8ne" },
  { cat: "Arts", diff: 2, kids: false, q: "Malian photographer Malick Sidibé became famous for pictures of what?", options: ["Young people at Bamako's night parties", "Wildlife along the Niger river", "Ruins of abandoned desert cities", "Storm clouds building over the Sahara"], answer: 0, fact: "In 2007 he became the first African, and the first photographer, to win the Venice Biennale's Golden Lion for lifetime achievement.", src: "https://en.wikipedia.org/wiki/Malick_Sidib%C3%A9" },
  { cat: "Arts", diff: 2, kids: true, q: "In much of the Islamic world, which art form has long been ranked the most prestigious of all?", options: ["Calligraphy", "Oil portraiture", "Bronze casting", "Mosaic flooring"], answer: 0, fact: "The angular Kufic script copied the Qur'an from the 8th to 10th century; a proverb runs: 'purity of writing is purity of the soul'.", src: "https://en.wikipedia.org/wiki/Islamic_calligraphy" },
  { cat: "Arts", diff: 3, kids: false, q: "How did Persian miniature painters show that something was far away in a scene?", options: ["By placing far-off figures higher up the page", "By painting long shadows stretching to the edge", "By blurring everything behind the main figures", "By squeezing the sky into a thin band at the top"], answer: 0, fact: "Their light is even and shadowless — these pictures were made to be held close, as illustrations inside books, not hung on a wall.", src: "https://en.wikipedia.org/wiki/Persian_miniature" },
  { cat: "Arts", diff: 2, kids: false, q: "Egyptian singer Umm Kulthum gave a live broadcast concert on what schedule for about forty years?", options: ["The first Thursday of every month", "Every Sunday morning", "Twice a year at the new moon", "The last day of each year"], answer: 0, fact: "Her broadcasts were said to empty the streets of Arab cities; about four million people lined Cairo's streets for her funeral in 1975.", src: "https://en.wikipedia.org/wiki/Umm_Kulthum" },
  { cat: "Arts", diff: 2, kids: false, q: "Egyptian novelist Naguib Mahfouz wrote his books while holding down what other career?", options: ["A government civil servant", "A doctor in a Cairo hospital", "A judge in the religious courts", "An engineer on the Aswan Dam"], answer: 0, fact: "In the 1950s the future Nobel laureate ran state film censorship, as Egypt's Director of Censorship in the Bureau of Arts.", src: "https://en.wikipedia.org/wiki/Naguib_Mahfouz" },
  { cat: "Arts", diff: 1, kids: true, q: "The four minarets of the Taj Mahal were deliberately built leaning slightly outwards. Why?", options: ["So that if they fell, they would fall away from the tomb", "To make them look taller from the main gate", "To let more sunlight reach the garden below", "To catch the wind and cool the building"], answer: 0, fact: "Shah Jahan had it built for Mumtaz Mahal; its inlaid flowers use stones brought from as far as Afghanistan, Tibet and Sri Lanka.", src: "https://en.wikipedia.org/wiki/Taj_Mahal" },
  { cat: "Arts", diff: 3, kids: false, q: "In Hindustani (North Indian) classical music, many ragas are traditionally tied to what?", options: ["A particular time of day or season", "A particular city where it must be played", "A fixed number of musicians on stage", "A single tempo that may never change"], answer: 0, fact: "A raga is more than a scale: it carries characteristic phrases, the pakad, that let a listener recognise it within a few notes.", src: "https://en.wikipedia.org/wiki/Raga" },
  { cat: "Arts", diff: 2, kids: false, q: "The classical dance Bharatanatyam comes from which Indian state?", options: ["Tamil Nadu", "Punjab", "Assam", "Gujarat"], answer: 0, fact: "British authorities in the Madras Presidency banned temple dancing in 1910; dancers rebuilt the form, and it was renamed Bharatanatyam in 1932.", src: "https://en.wikipedia.org/wiki/Bharatanatyam" },
  { cat: "Arts", diff: 3, kids: false, q: "Zhang Zeduan's 'Along the River During the Qingming Festival' was painted in what format?", options: ["A handscroll more than five metres long", "A fresco painted across a temple ceiling", "A folding screen covered in gold leaf", "A wall of glazed ceramic tiles"], answer: 0, fact: "Its 25 cm-high strip holds 814 people, 60 animals and 28 boats; writers have called this Song dynasty scroll 'China's Mona Lisa'.", src: "https://en.wikipedia.org/wiki/Along_the_River_During_the_Qingming_Festival" },
  { cat: "Arts", diff: 1, kids: true, q: "In the Japanese practice of kintsugi, a broken bowl is mended with what?", options: ["Lacquer dusted with powdered gold", "Melted glass poured into the cracks", "Stitches of fine silver wire", "Coloured wax pressed into the joins"], answer: 0, fact: "The repair is left visible on purpose: the break becomes part of the bowl's history rather than a flaw to hide.", src: "https://en.wikipedia.org/wiki/Kintsugi" },
  { cat: "Arts", diff: 3, kids: false, q: "Akira Kurosawa's film 'Rashomon' gave its name to an effect. What is it?", options: ["Several witnesses give contradictory accounts of one event", "A whole film shot in a single unbroken take", "A story told without any spoken dialogue", "A camera pointed straight into the sun"], answer: 0, fact: "It won the Golden Lion at Venice in 1951 and became the first Japanese film to reach a large audience abroad.", src: "https://en.wikipedia.org/wiki/Rashomon" },
  { cat: "Arts", diff: 3, kids: false, q: "A traditional Korean pansori performance is carried by how many performers?", options: ["Two: one singer and one drummer", "Twelve singers in unison", "One singer with a full orchestra", "One drummer playing alone"], answer: 0, fact: "A full pansori can run eight hours, and listeners shout encouragement — chuimsae — throughout; only five of the twelve old stories survive.", src: "https://en.wikipedia.org/wiki/Pansori" },
  { cat: "Arts", diff: 1, kids: true, q: "Indonesian batik patterns are made by putting what on the cloth before it is dyed?", options: ["Hot wax", "Salt water", "Chalk dust", "Tree-sap glue"], answer: 0, fact: "The finest batik is drawn by hand with a canting, a tiny copper spout that trickles molten wax; UNESCO listed the craft in 2009.", src: "https://en.wikipedia.org/wiki/Batik" },
  { cat: "Arts", diff: 2, kids: true, q: "After the Mexican Revolution, why did the government pay artists to paint huge murals on public walls?", options: ["So that people who could not read could see the country's story", "Because canvas had been banned by law", "To hide the damage left by the fighting", "Because murals cost less than street lighting"], answer: 0, fact: "Education minister José Vasconcelos launched the scheme in the 1920s; Rivera, Orozco and Siqueiros became known as los tres grandes.", src: "https://en.wikipedia.org/wiki/Mexican_muralism" },
  { cat: "Arts", diff: 3, kids: false, q: "In 1945 Chilean poet Gabriela Mistral became the first Latin American writer to receive what?", options: ["The Nobel Prize in Literature", "An Academy Award", "The Booker Prize", "The Pulitzer Prize"], answer: 0, fact: "Gabriela Mistral was a pen name: she was born Lucila Godoy Alcayaga, and worked as a rural schoolteacher before becoming a diplomat.", src: "https://en.wikipedia.org/wiki/Gabriela_Mistral" },
  { cat: "Arts", diff: 2, kids: false, q: "'Bossa nova', the Brazilian style that grew out of samba, translates roughly as what?", options: ["New wave, or new trend", "Slow drum, or heavy beat", "Song of the night", "Dance of the beach"], answer: 0, fact: "João Gilberto's soft guitar pulse and near-whispered singing were the key: he pulled samba's rhythm onto a nylon-string guitar.", src: "https://en.wikipedia.org/wiki/Bossa_nova" },
  { cat: "Arts", diff: 1, kids: true, q: "The steelpan, national instrument of Trinidad and Tobago, is made from what?", options: ["An industrial oil drum", "A hollowed-out log", "A stretched goat hide", "A sheet of moulded glass"], answer: 0, fact: "The drum end is hammered into a bowl, then grooved into areas each tuned to its own note; the steelpan appears on the national coat of arms.", src: "https://en.wikipedia.org/wiki/Steelpan" },
  { cat: "Arts", diff: 3, kids: false, q: "The Western Desert painting movement began in 1971 at Papunya, Australia, when senior men did what?", options: ["Painted a Honey Ant Dreaming mural on a school wall", "Carved a set of totem poles for the town square", "Founded Australia's first national art gallery", "Set up a printing press to make posters"], answer: 0, fact: "With no canvas to hand, the Papunya painters worked on scraps of board, car bonnets and matchboxes, in acrylic instead of sand and ochre.", src: "https://en.wikipedia.org/wiki/Papunya_Tula" },
  { cat: "Arts", diff: 1, kids: true, q: "The blues grew up among African Americans in which part of the United States?", options: ["The Deep South", "New England", "The Pacific Northwest", "The Rocky Mountains"], answer: 0, fact: "Its 'blue notes' — thirds, fifths and sevenths bent flat — give the music its sound; scholars trace them to West African Sahel traditions.", src: "https://en.wikipedia.org/wiki/Blues" },
  { cat: "Arts", diff: 3, kids: false, q: "For the album 'Kind of Blue', Miles Davis handed his band what instead of written chord changes?", options: ["Sets of scales to improvise on", "Full orchestral scores to read", "Recordings of other bands to copy", "Solos written out note by note"], answer: 0, fact: "The story that the whole album was caught in one pass is a myth — only 'Flamenco Sketches' came out complete on the first take.", src: "https://en.wikipedia.org/wiki/Kind_of_Blue" },
  { cat: "Arts", diff: 2, kids: false, q: "DJ Kool Herc laid the foundation of hip hop by using two turntables to do what?", options: ["Loop the drum break of a record over and over", "Play two different songs at the same time", "Slow every record down to half speed", "Record the crowd singing along"], answer: 0, fact: "Born in Kingston, Jamaica, he was 18 when he DJed his sister Cindy's back-to-school party in the Bronx on 11 August 1973.", src: "https://en.wikipedia.org/wiki/DJ_Kool_Herc" },
  { cat: "Arts", diff: 3, kids: false, q: "The oldest surviving photograph made in a camera was produced by coating a pewter plate with what?", options: ["Bitumen of Judea", "Silver paint", "Beeswax", "Powdered charcoal"], answer: 0, fact: "Nicéphore Niépce made it at Saint-Loup-de-Varennes in 1827; research suggests the exposure ran not for hours but for several days.", src: "https://en.wikipedia.org/wiki/View_from_the_Window_at_Le_Gras" },
  { cat: "Arts", diff: 1, kids: true, q: "Georges Méliès's 1902 film 'A Trip to the Moon' is best remembered for which image?", options: ["A capsule landing in the Moon's eye", "A rocket circling the rings of Saturn", "An astronaut planting a flag in dust", "A comet crashing down onto Paris"], answer: 0, fact: "A hand-coloured print, painted frame by frame, turned up in Barcelona in 1993 and took until 2011 to restore.", src: "https://en.wikipedia.org/wiki/A_Trip_to_the_Moon" },
  { cat: "Arts", diff: 1, kids: true, q: "What does a flying buttress do for a Gothic cathedral?", options: ["Carries the outward push of the vault to an outer pier", "Holds up the weight of the bells in the tower", "Drains rainwater away from the roof and walls", "Supports the stone floor of the crypt below"], answer: 0, fact: "Taking the load off the walls let builders swap stone for glass — which is why Gothic churches have such enormous windows.", src: "https://en.wikipedia.org/wiki/Flying_buttress" },
  { cat: "Arts", diff: 2, kids: false, q: "Auguste Rodin's 'The Thinker' was first made as one figure within which larger work?", options: ["The Gates of Hell", "The Burghers of Calais", "The Kiss", "The Walking Man"], answer: 0, fact: "Rodin first called the figure 'The Poet'; some see Dante brooding over his own Inferno, others a self-portrait.", src: "https://en.wikipedia.org/wiki/The_Thinker" },
  { cat: "Arts", diff: 3, kids: false, q: "Stravinsky's 'The Rite of Spring' premiered in Paris in 1913. What is that night remembered for?", options: ["The audience erupted in an uproar", "It was the first ballet lit by electricity", "The whole ballet was staged underwater", "The ballet was performed with no music"], answer: 0, fact: "The noise drowned out Nijinsky, who stood in the wings shouting step counts; about forty people were ejected and the dancers carried on.", src: "https://en.wikipedia.org/wiki/The_Rite_of_Spring" },
  { cat: "Arts", diff: 3, kids: false, q: "In buon fresco, why must the painter finish a section within a single day?", options: ["The pigment only binds while the plaster is still wet", "The paint turns poisonous after about a day", "The scaffolding has to be taken down each night", "The colours darken badly if left overnight"], answer: 0, fact: "Each day's patch is called a giornata; fresh plaster gives about seven to nine working hours, and fixing a mistake means chipping it out.", src: "https://en.wikipedia.org/wiki/Fresco" },
  { cat: "Arts", diff: 2, kids: false, q: "A hostile critic looked at Monet's 'Impression, Sunrise' in 1874 and coined which word?", options: ["Impressionism", "Cubism", "Fauvism", "Surrealism"], answer: 0, fact: "Louis Leroy meant it as an insult in the paper Le Charivari; the painters took the name anyway. The scene is the port of Le Havre.", src: "https://en.wikipedia.org/wiki/Impression,_Sunrise" },
  { cat: "Arts", diff: 3, kids: false, q: "While Cervantes was still writing part two of 'Don Quixote', a stranger published a fake sequel. How did he reply?", options: ["He had his characters meet the impostors and denounce them", "He rewrote the whole of part one from scratch", "He abandoned the book and never finished it", "He took the publisher to court and won damages"], answer: 0, fact: "Part one appeared in 1605 and part two in 1615; a 2002 poll of 100 writers voted it the greatest work of fiction ever written.", src: "https://en.wikipedia.org/wiki/Don_Quixote" },
  { cat: "Arts", diff: 3, kids: false, q: "The sonnet — fourteen lines — was invented at whose court?", options: ["Frederick II, in Palermo", "Elizabeth I, in London", "Louis XIV, at Versailles", "Charlemagne, at Aachen"], answer: 0, fact: "Giacomo da Lentini devised it in 13th-century Sicily; 'sonetto' means little song. Petrarch and Shakespeare came centuries later.", src: "https://en.wikipedia.org/wiki/Sonnet" },
  { cat: "Arts", diff: 3, kids: false, q: "Italian commedia dell'arte troupes of the 1500s were unusual in European theatre because they did what?", options: ["They employed women to play the women's parts", "They performed only at first light, before dawn", "They played entirely without costumes or props", "They allowed no comedy, only tragic scenes"], answer: 0, fact: "Their masked stock characters spread across Europe: Arlecchino became Harlequin, and Pulcinella became the puppet Mr Punch.", src: "https://en.wikipedia.org/wiki/Commedia_dell%27arte" },
  { cat: "Arts", diff: 2, kids: false, q: "Picasso painted 'Guernica' in 1937 in response to what?", options: ["The bombing of a Basque town", "A famine spreading across Andalusia", "An earthquake that levelled Lisbon", "A shipwreck off the coast of Cádiz"], answer: 0, fact: "Picasso refused to let the painting go to Spain while Franco ruled; it finally arrived in 1981 and hangs in Madrid today.", src: "https://en.wikipedia.org/wiki/Guernica_(Picasso)" },
  { cat: "Arts", diff: 2, kids: false, q: "What makes the stained glass of Chartres Cathedral in France exceptional?", options: ["Most of its medieval windows still hold the original glass", "It is the only stained glass ever made without lead", "Every window is clear, with no colour at all", "All of its glass was painted fresh in the 1900s"], answer: 0, fact: "The cathedral has 167 windows, and the main rebuild after the fire of 1194 was largely finished in about twenty-five years.", src: "https://en.wikipedia.org/wiki/Chartres_Cathedral" },
  { cat: "Arts", diff: 2, kids: true, q: "Why does a symphony orchestra tune to the oboe?", options: ["Its pitch is stable and its sound carries clearly", "It is the oldest instrument on the stage", "It is always the loudest player in the hall", "It cannot be retuned once it is assembled"], answer: 0, fact: "Professional oboists usually carve their own double reeds — two blades of cane tied to a metal tube — to control tone and tuning.", src: "https://en.wikipedia.org/wiki/Oboe" },
  { cat: "Tech", diff: 2, kids: true, q: "Your phone finds where it is using GPS, the Global Positioning System. What does it send up to the satellites?", options: ["A short radio ping every second", "Your phone number", "Nothing at all — it only listens", "A photo of the sky above it"], answer: 2, fact: "Until 2000 the US deliberately blurred the civilian signal; switching that off sharpened typical accuracy from about 100 metres to five.", src: "https://en.wikipedia.org/wiki/Global_Positioning_System" },
  { cat: "Tech", diff: 2, kids: true, q: "Gladys West spent decades programming computers to model the exact shape of the Earth. Which everyday technology depends on that model?", options: ["The microwave oven", "Satellite navigation (GPS)", "The barcode scanner", "The lithium battery"], answer: 1, fact: "Her work stayed unknown — even to her own children — until a sorority sister read a short biography she had submitted for an alumni event.", src: "https://en.wikipedia.org/wiki/Gladys_West" },
  { cat: "Tech", diff: 1, kids: true, q: "A phone's touchscreen ignores a gloved finger but answers a bare one. What is it actually detecting?", options: ["The heat of your fingertip", "The pressure of your push", "The pattern of your fingerprint", "Your body's ability to conduct electricity"], answer: 3, fact: "The glass carries a faint electric field, and a finger — mostly salty water — distorts it enough for the phone to place the touch.", src: "https://en.wikipedia.org/wiki/Capacitive_sensing" },
  { cat: "Tech", diff: 2, kids: false, q: "What actually moves inside a lithium-ion battery as it charges and discharges?", options: ["Lithium ions travelling between the two electrodes", "Drops of liquid lithium metal", "Tiny magnets flipping over", "Air pumped from one end to the other"], answer: 0, fact: "The 2019 chemistry Nobel went to Whittingham, Goodenough and Yoshino — Goodenough, at 97, the oldest Nobel laureate ever.", src: "https://en.wikipedia.org/wiki/Lithium-ion_battery" },
  { cat: "Tech", diff: 2, kids: true, q: "A fridge does not make cold. What does it actually do?", options: ["It turns electricity directly into cold air", "It pumps cold air in from outdoors", "It moves heat from inside to the coils outside", "It freezes the air trapped inside it"], answer: 2, fact: "The refrigerant boils inside and soaks up heat, then is squeezed back into a liquid outside — which is why a fridge's back is warm.", src: "https://en.wikipedia.org/wiki/Vapor-compression_refrigeration" },
  { cat: "Tech", diff: 1, kids: true, q: "A microwave oven heats food by doing what to the water molecules in it?", options: ["Making them twist back and forth very fast", "Splitting them into hydrogen and oxygen", "Freezing them and then thawing them", "Pushing them all to the edge of the plate"], answer: 0, fact: "Percy Spencer found the effect in 1945 when a radar set he was working on melted the candy bar in his pocket.", src: "https://en.wikipedia.org/wiki/Microwave_oven" },
  { cat: "Tech", diff: 2, kids: true, q: "The stripes of a barcode were inspired by which older code?", options: ["Braille", "Roman numerals", "Morse code", "Semaphore flags"], answer: 2, fact: "Joseph Woodland traced the first one in beach sand, pulling Morse dots and dashes downwards into narrow and wide lines.", src: "https://en.wikipedia.org/wiki/Barcode" },
  { cat: "Tech", diff: 2, kids: true, q: "The QR code — the 'quick response' code — was invented in 1994 by Masahiro Hara's team in Japan. What were they trying to keep track of?", options: ["Library books", "Train tickets", "Hospital patients", "Car parts on a factory line"], answer: 3, fact: "The black-and-white grid was inspired by the stones on a Go board.", src: "https://en.wikipedia.org/wiki/QR_code" },
  { cat: "Tech", diff: 1, kids: true, q: "Elisha Otis did not invent the lift. What did he invent in 1852 that made tall buildings practical?", options: ["The electric motor that pulls the lift", "A brake that grips if the cable snaps", "The sliding doors on each floor", "The button panel inside the car"], answer: 1, fact: "At the New York Crystal Palace in 1854 he had the rope above his own head cut — the platform held, and the orders came in.", src: "https://en.wikipedia.org/wiki/Elisha_Otis" },
  { cat: "Tech", diff: 2, kids: false, q: "Red and green LEDs had existed for decades. Why did the blue LED win a Nobel Prize in 2014?", options: ["It was the first LED of any colour", "It was the first light bright enough for daylight", "It completed the set needed for white light", "It ran on no electricity at all"], answer: 2, fact: "Isamu Akasaki, Hiroshi Amano and Shuji Nakamura cracked it in the early 1990s; a blue LED under a phosphor coat gives white light.", src: "https://en.wikipedia.org/wiki/Light-emitting_diode" },
  { cat: "Tech", diff: 1, kids: true, q: "A solar panel turns sunlight into electricity through which effect?", options: ["The greenhouse effect", "The photovoltaic effect", "The Doppler effect", "The magnetic effect"], answer: 1, fact: "Edmond Becquerel built the first photovoltaic cell in 1839, aged 19, in his father's laboratory.", src: "https://en.wikipedia.org/wiki/Solar_cell" },
  { cat: "Tech", diff: 3, kids: false, q: "In a four-stroke petrol engine, how many of the four strokes actually drive the car forward?", options: ["One", "Two", "Three", "All four"], answer: 0, fact: "Intake, compression, power, exhaust — only the third does the work, and one full cycle takes two turns of the crankshaft.", src: "https://en.wikipedia.org/wiki/Four-stroke_engine" },
  { cat: "Tech", diff: 1, kids: true, q: "Radio waves and the light you see are both what?", options: ["Vibrations of the air", "Streams of tiny magnets", "Electromagnetic waves", "Ripples in water vapour"], answer: 2, fact: "Radio waves sit at the long-wavelength end of the very same spectrum as light, and in a vacuum both travel at exactly the same speed.", src: "https://en.wikipedia.org/wiki/Electromagnetic_radiation" },
  { cat: "Tech", diff: 1, kids: true, q: "Bluetooth is named after a 10th-century Scandinavian king. What does its logo show?", options: ["A single blue tooth", "Two radio masts side by side", "A Viking longship under sail", "His initials, written as two runes"], answer: 3, fact: "Harald 'Bluetooth' Gormsson united the Danish tribes; the engineers chose the name because their standard united rival devices.", src: "https://en.wikipedia.org/wiki/Bluetooth" },
  { cat: "Tech", diff: 2, kids: true, q: "A contactless bank card has no battery. Where does its chip get the power to answer the reader?", options: ["From a tiny solar cell in the plastic", "From the radio field the reader gives off", "From the warmth of your hand", "From static built up in your pocket"], answer: 1, fact: "Near-field communication reaches only about 10 cm — outside the reader's field, the card gets no power at all.", src: "https://en.wikipedia.org/wiki/Near-field_communication" },
  { cat: "Tech", diff: 2, kids: true, q: "Noise-cancelling headphones quieten an aircraft's rumble by playing what?", options: ["Loud white noise over the top", "A very high-pitched tone", "The same sound, flipped upside down", "Nothing — they only seal your ears"], answer: 2, fact: "Two opposite waves cancel out. It works best on low, steady rumbles; high darting sounds are far harder to catch in time.", src: "https://en.wikipedia.org/wiki/Active_noise_control" },
  { cat: "Tech", diff: 2, kids: false, q: "The memory inside a USB stick or a phone was invented at Toshiba in 1980. Why is it called 'flash'?", options: ["It was invented in a single flash of insight", "The first chips glowed when written to", "It was named after a comic-book hero", "Erasing it reminded a colleague of a camera flash"], answer: 3, fact: "Fujio Masuoka invented it; the name came from his colleague Shoji Ariizumi, watching the memory wipe itself in an instant.", src: "https://en.wikipedia.org/wiki/Flash_memory" },
  { cat: "Tech", diff: 3, kids: false, q: "Public-key cryptography lets two strangers agree a secret over an open line. Who published the idea first?", options: ["Alan Turing, in 1948", "Whitfield Diffie and Martin Hellman, in 1976", "Claude Shannon, in 1962", "Tim Berners-Lee, in 1990"], answer: 1, fact: "James Ellis and Clifford Cocks had found the same idea in secret at Britain's GCHQ years earlier; it stayed classified until 1997.", src: "https://en.wikipedia.org/wiki/Public-key_cryptography" },
  { cat: "Tech", diff: 2, kids: true, q: "Film actor Hedy Lamarr co-patented a wartime idea in 1942 that lives on in Bluetooth and early Wi-Fi. What was it?", options: ["Storing sound on magnetic tape", "Sending pictures down a telephone line", "Hopping a radio signal between frequencies", "Beaming power without wires"], answer: 2, fact: "Her co-inventor George Antheil took the timing mechanism from player pianos, which he had already synchronised for a music piece.", src: "https://en.wikipedia.org/wiki/Hedy_Lamarr" },
  { cat: "Tech", diff: 2, kids: false, q: "Grace Hopper argued that programs should be written in something close to English. What did she build to make that possible?", options: ["A faster kind of transistor for the machine's memory", "A compiler, which turns readable code into machine instructions", "The first keyboard built for a computer terminal", "A machine that punched programs onto paper tape"], answer: 1, fact: "She handed out wires 11.8 inches long — the distance light travels in one nanosecond — so people could see where delays come from.", src: "https://en.wikipedia.org/wiki/Grace_Hopper" },
  { cat: "Tech", diff: 2, kids: false, q: "As NASA moved to electronic computers, Dorothy Vaughan taught herself a programming language and then taught it to her whole team. Which one?", options: ["Python", "COBOL", "JavaScript", "FORTRAN"], answer: 3, fact: "Back in 1949, when the agency was still NACA, she became its first Black supervisor, leading a team made up entirely of African American women.", src: "https://en.wikipedia.org/wiki/Dorothy_Vaughan" },
  { cat: "Tech", diff: 2, kids: false, q: "Margaret Hamilton led the flight-software team for the Apollo missions. Which term did she start using for her line of work?", options: ["Machine learning", "Software engineering", "Cloud computing", "Open source"], answer: 1, fact: "Minutes from the Moon her software hit an overload, shed the less urgent tasks and let the landing carry on.", src: "https://en.wikipedia.org/wiki/Margaret_Hamilton_(software_engineer)" },
  { cat: "Tech", diff: 3, kids: false, q: "Mark Dean holds three of the nine original IBM PC patents. What did he and Dennis Moeller create that lets you plug extra cards into a computer?", options: ["The floppy disc drive", "The dot-matrix printer", "The ISA expansion bus", "The electronic spreadsheet"], answer: 2, fact: "In 1999 Dean led the team that built the first computer chip to run at one gigahertz — a billion cycles every second.", src: "https://en.wikipedia.org/wiki/Mark_Dean_(computer_scientist)" },
  { cat: "Tech", diff: 3, kids: false, q: "Clarence Ellis pioneered the technique that lets two people type into the same document at once without their edits clashing. What is it called?", options: ["Garbage collection", "Two-phase commit", "Operational transformation", "Round-robin scheduling"], answer: 2, fact: "In 1969 Ellis became the first African American with a PhD in computer science; at Xerox PARC he helped build OfficeTalk, early groupware.", src: "https://en.wikipedia.org/wiki/Clarence_Ellis_(computer_scientist)" },
  { cat: "Tech", diff: 2, kids: true, q: "Sophie Wilson co-designed the instruction set of the ARM processor. Where are you most likely to find one today?", options: ["In a smartphone", "In a car tyre", "In a washing machine drum", "In a television aerial"], answer: 0, fact: "By 2012 ARM designs were in 95% of smartphones; Wilson also wrote BBC BASIC, which taught a generation in Britain to program.", src: "https://en.wikipedia.org/wiki/Sophie_Wilson" },
  { cat: "Tech", diff: 3, kids: false, q: "Karen Spärck Jones's 1972 idea still ranks search results: rare words in a query count for more than common ones. What is it called?", options: ["Packet switching", "Binary search", "Inverse document frequency", "Public-key exchange"], answer: 2, fact: "Her slogan was blunt: 'Computing is too important to be left to men.'", src: "https://en.wikipedia.org/wiki/Karen_Sp%C3%A4rck_Jones" },
  { cat: "Tech", diff: 3, kids: false, q: "Colossus, the world's first programmable electronic computer, was built during the Second World War by an engineer working for which organisation?", options: ["The Royal Navy", "The University of Cambridge", "The BBC", "The British Post Office"], answer: 3, fact: "Tommy Flowers put some of his own money into it and could not speak about it for decades; his work was acknowledged only in the 1970s.", src: "https://en.wikipedia.org/wiki/Tommy_Flowers" },
  { cat: "Tech", diff: 3, kids: false, q: "Who first worked out the inner workings of the German military Enigma cipher machine, in late 1932, without ever seeing inside one?", options: ["Alan Turing, in England", "Marian Rejewski, in Poland", "William Friedman, in the United States", "Georges Painvin, in France"], answer: 1, fact: "Poland handed its Enigma methods to France and Britain at a meeting near Warsaw on 25 July 1939, five weeks before the war began.", src: "https://en.wikipedia.org/wiki/Marian_Rejewski" },
  { cat: "Tech", diff: 2, kids: true, q: "Chieko Asakawa, blind since her teens, built a system at IBM in 1997 that did what?", options: ["Printed web pages in colour", "Translated web pages into Japanese", "Read web pages aloud", "Made web pages load faster"], answer: 2, fact: "Her Home Page Reader became the most used web-to-speech system within five years; she has since built a robot suitcase to guide blind travellers.", src: "https://en.wikipedia.org/wiki/Chieko_Asakawa" },
  { cat: "Tech", diff: 1, kids: true, q: "An email says your account closes today unless you 'confirm your password' on a linked page. What is this?", options: ["A routine security check by your bank", "Phishing — a trick to get your details", "A notice that software needs updating", "A parcel delivery notification"], answer: 1, fact: "The odd English spelling 'phishing' comes from 'phreaking', 1970s slang for hacking telephone systems.", src: "https://en.wikipedia.org/wiki/Phishing" },
  { cat: "Tech", diff: 2, kids: true, q: "Which of these passwords is hardest for a computer to guess?", options: ["P@ssw0rd!", "Xk9$q", "1234abcd", "seven purple tractors sing"], answer: 3, fact: "Length beats symbols: the US standards body NIST no longer advises forcing special characters, and calls length the key ingredient.", src: "https://en.wikipedia.org/wiki/Password_strength" },
  { cat: "Tech", diff: 1, kids: true, q: "Two-factor authentication asks for a second proof of who you are. Which of these is a genuinely different kind of proof from your password?", options: ["A longer version of the same password", "Your email address", "A code sent to your phone", "Your username"], answer: 2, fact: "The three factors are something you know, something you have and something you are — a password, a phone, a fingerprint.", src: "https://en.wikipedia.org/wiki/Multi-factor_authentication" },
  { cat: "Tech", diff: 2, kids: true, q: "A website 'cookie' is what, exactly?", options: ["A program that runs on your computer", "A small file the site asks your browser to keep", "A copy of your password stored by the site", "An image saved to make the page load faster"], answer: 1, fact: "Lou Montulli invented them at Netscape in 1994 so a shopping basket could survive from one page to the next.", src: "https://en.wikipedia.org/wiki/HTTP_cookie" },
  { cat: "Tech", diff: 1, kids: true, q: "When a photo is 'in the cloud', where is it really?", options: ["Floating in the air around you", "Inside your phone's own memory", "On a satellite in orbit", "On a hard drive in a company's data centre"], answer: 3, fact: "Cloud providers run vast halls of machines; you rarely learn which building — or even which country — holds your file.", src: "https://en.wikipedia.org/wiki/Cloud_computing" },
  { cat: "Tech", diff: 2, kids: false, q: "Private or 'incognito' browsing hides your activity from whom?", options: ["Your internet provider", "The websites you visit", "Other people using the same device", "Your employer's network staff"], answer: 2, fact: "It wipes local history and cookies when you close it — nothing more. Sites and providers still see your address and your traffic.", src: "https://en.wikipedia.org/wiki/Private_browsing" },
  { cat: "Tech", diff: 1, kids: true, q: "The word 'deepfake' blends 'fake' with which other term?", options: ["Deep learning", "Deep sea", "Deep focus", "Deep web"], answer: 0, fact: "Many are made by two neural networks trained against each other — one inventing images, the other trying to spot the fakes.", src: "https://en.wikipedia.org/wiki/Deepfake" },
  { cat: "Tech", diff: 2, kids: true, q: "Why does a software update often matter for your safety, not just for new features?", options: ["It makes the battery last longer", "It deletes old files to free up space", "It closes security holes attackers already know", "It resets your password automatically"], answer: 2, fact: "The English word 'patch' is literal: suppliers once posted punched tape, and you cut out the faulty stretch and spliced the fix in.", src: "https://en.wikipedia.org/wiki/Patch_(computing)" },
  { cat: "Tech", diff: 2, kids: false, q: "A shopping site you use suffers a data breach. Why does that put your other accounts at risk?", options: ["The breach spreads through your Wi-Fi", "Attackers try the same email and password elsewhere", "Your bank uses the same servers", "Your phone number changes automatically"], answer: 1, fact: "One survey found 81% of people reuse a password on two or more sites; attackers automate the retries and up to 2% succeed.", src: "https://en.wikipedia.org/wiki/Credential_stuffing" },
  { cat: "Tech", diff: 3, kids: false, q: "In an end-to-end encrypted chat, who else can read your message besides you and the person you sent it to?", options: ["The company running the app", "Your internet provider", "Anyone on the same Wi-Fi", "Nobody, not even the company running the app"], answer: 3, fact: "The message is scrambled on your device and unscrambled on theirs; the service carries a package it holds no key to.", src: "https://en.wikipedia.org/wiki/End-to-end_encryption" },
  { cat: "Science", sub: "Physics", diff: 1, kids: true, q: "In a rainbow, which colour sits on the outer edge of the arc?", options: ["Violet", "Red", "Green", "Yellow"], answer: 1, fact: "Newton first counted five colours, then added orange and indigo to make seven — matching the notes of a musical scale.", src: "https://en.wikipedia.org/wiki/Rainbow" },
  { cat: "Science", sub: "Physics", diff: 1, kids: true, q: "A television or phone screen builds every colour it shows by mixing just three colours of light. Which three?", options: ["Red, yellow and blue", "Cyan, magenta and yellow", "Red, green and blue", "Orange, green and violet"], answer: 2, fact: "Hold a magnifier to a white patch of screen and there is no white there at all — only tiny red, green and blue dots.", src: "https://en.wikipedia.org/wiki/RGB_color_model" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "On a hot road a shimmering 'puddle' appears ahead, then vanishes as you get closer. What are you actually seeing?", options: ["Water evaporating off the warm tarmac", "An illusion created inside your own eye", "Heat glowing upward from the road surface", "A patch of sky, bent upwards by hot air"], answer: 3, fact: "A mirage is not in your head — a camera photographs it too, because the light really is being bent.", src: "https://en.wikipedia.org/wiki/Mirage" },
  { cat: "Science", sub: "Physics", diff: 2, kids: false, q: "Around 1015, working in Cairo, the scholar Ibn al-Haytham showed that we see because:", options: ["the eye sends out rays that touch objects", "light travels from objects into the eye", "the air carries images along to the eye", "the mind projects pictures onto the world"], answer: 1, fact: "He set out the argument in a seven-volume Book of Optics, written by legend while he was confined after feigning madness.", src: "https://en.wikipedia.org/wiki/Ibn_al-Haytham" },
  { cat: "Science", sub: "Physics", diff: 3, kids: false, q: "In 1676 Ole Rømer timed the eclipses of Io, a moon of Jupiter. What did his timings prove?", options: ["That Jupiter has more than one moon", "That light is bent as it passes planets", "That light travels at a finite speed", "That Jupiter's orbit is not circular"], answer: 2, fact: "His figure came out about a quarter too low, but it was the first proof that light takes time to cross space.", src: "https://en.wikipedia.org/wiki/R%C3%B8mer%27s_determination_of_the_speed_of_light" },
  { cat: "Science", sub: "Physics", diff: 1, kids: true, q: "Why does an ambulance siren sound higher as it comes towards you and lower once it has passed?", options: ["The sound waves bunch up ahead of it and stretch out behind", "The driver switches the siren to a different setting", "Sound travels faster when it is heading towards a listener", "Your ears gradually adjust to the very loud noise"], answer: 0, fact: "Weather radar uses the same shift: the returning signal shows which way rain inside a storm is moving.", src: "https://en.wikipedia.org/wiki/Doppler_effect" },
  { cat: "Science", sub: "Physics", diff: 2, kids: false, q: "What produces the sonic boom heard when an aircraft flies faster than sound?", options: ["The engines backfiring as the aircraft passes the speed of sound", "Pressure waves piling into a shock wave that sweeps over the ground", "A solid barrier in the air being physically broken apart", "Air freezing and then shattering in the wake of the wings"], answer: 1, fact: "The boom is not a single bang at the moment of breaking through — it trails the aircraft like a wake, all along its path.", src: "https://en.wikipedia.org/wiki/Sonic_boom" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "A metal spoon and a wooden spoon have sat in the same room all night. Why does the metal one feel colder?", options: ["The metal really is at a lower temperature", "Wood quietly gives off a little heat of its own", "Metal carries heat away from your hand much faster", "Metal reflects your body heat straight back at you"], answer: 2, fact: "Skin does not sense temperature, only heat flowing in or out — so good conductors always feel cold.", src: "https://en.wikipedia.org/wiki/Thermal_conduction" },
  { cat: "Science", sub: "Physics", diff: 3, kids: false, q: "The Indian physicist C. V. Raman won the 1930 Nobel Prize in Physics for showing that light passing through a material can do what?", options: ["Stop completely", "Change colour slightly", "Split into two beams of equal brightness", "Become magnetic"], answer: 1, fact: "He was the first Asian to win the physics Nobel, and it began with a question: why is the Mediterranean so blue?", src: "https://en.wikipedia.org/wiki/C._V._Raman" },
  { cat: "Science", sub: "Physics", diff: 2, kids: false, q: "What happens when a magnet is moved in and out of a coil of wire?", options: ["The wire becomes permanently magnetic", "The wire heats up and nothing more", "Absolutely nothing happens at all", "An electric current flows in the wire"], answer: 3, fact: "Michael Faraday found this in 1831; nearly every power station still makes electricity by spinning magnets past coils.", src: "https://en.wikipedia.org/wiki/Electromagnetic_induction" },
  { cat: "Science", sub: "Physics", diff: 2, kids: false, q: "In 1800 Alessandro Volta stacked discs of zinc and copper separated by brine-soaked cloth. What had he built?", options: ["The first electric motor", "The first electric light bulb", "The first electric telegraph", "The first electric battery"], answer: 3, fact: "Until then electricity came only in sudden sparks; the same year, chemists used Volta's steady current to split water.", src: "https://en.wikipedia.org/wiki/Voltaic_pile" },
  { cat: "Science", sub: "Physics", diff: 2, kids: false, q: "The magnetic compass was invented in China. What was it first used for?", options: ["Steering ships out at sea", "Divination and aligning buildings", "Measuring the passing of time", "Finding metal ore underground"], answer: 1, fact: "Archaeologists have never actually dug up one of the famous lodestone spoons; compasses only began steering ships around 1088.", src: "https://en.wikipedia.org/wiki/Compass" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "On the Moon in 1971, astronaut David Scott dropped a hammer and a falcon feather at the same moment. What happened?", options: ["The feather reached the ground first", "The hammer landed well before the feather", "They hit the ground together", "The feather drifted away sideways"], answer: 2, fact: "With no air to slow the feather, gravity pulls everything down at the same rate — Galileo's claim, tested live on television.", src: "https://en.wikipedia.org/wiki/Apollo_15" },
  { cat: "Science", sub: "Physics", diff: 2, kids: false, q: "In 1654 Otto von Guericke pumped the air out of two metal hemispheres pressed together. What could two teams of horses not do?", options: ["Lift them clear off the ground", "Crush the hemispheres flat", "Pull the two halves apart", "Roll them across the square"], answer: 2, fact: "Thirty horses failed, yet only the weight of the outside air held the halves together — open a valve and they came apart by hand.", src: "https://en.wikipedia.org/wiki/Magdeburg_hemispheres" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "Why does a steel ship float when a steel nail sinks?", options: ["Steel behaves as a lighter material in very large pieces", "The hull pushes aside a weight of water equal to the whole ship", "Seawater is denser than the steel the hull is made of", "The ship's engines constantly push it upwards in the water"], answer: 1, fact: "Archimedes set it out over 2,200 years ago: the upward push equals the weight of the fluid the object shoves aside.", src: "https://en.wikipedia.org/wiki/Archimedes%27_principle" },
  { cat: "Science", sub: "Physics", diff: 3, kids: false, q: "Albert Einstein's Nobel Prize in Physics was not awarded for relativity. What was it awarded for?", options: ["Discovering the atomic nucleus", "Predicting the existence of black holes", "Deriving the equation E = mc²", "Explaining the photoelectric effect"], answer: 3, fact: "No matter how bright a red light is, it knocks no electrons out of some metals — the clue that told Einstein light comes in packets.", src: "https://en.wikipedia.org/wiki/Photoelectric_effect" },
  { cat: "Science", sub: "Physics", diff: 3, kids: false, q: "In 1801 Thomas Young described sending light through two narrow slits side by side. What appears on the screen behind them?", options: ["Two bright lines", "A pattern of bright and dark bands", "A single bright spot", "Nothing at all"], answer: 1, fact: "The bands come from waves cancelling and reinforcing, and the pattern still builds up when particles are sent one at a time.", src: "https://en.wikipedia.org/wiki/Double-slit_experiment" },
  { cat: "Science", sub: "Physics", diff: 3, kids: false, q: "In 1971 two researchers flew caesium atomic clocks around the world on ordinary passenger flights. What did they find on landing?", options: ["Every clock had stayed perfectly in step", "The clocks had stopped while at high altitude", "The travelling clocks disagreed with the clocks left behind", "The clocks ran fast only while over the poles"], answer: 2, fact: "Flying east the clocks lost about 59 billionths of a second; flying west they gained about 273 — close to relativity's prediction.", src: "https://en.wikipedia.org/wiki/Hafele%E2%80%93Keating_experiment" },
  { cat: "Science", sub: "Physics", diff: 3, kids: false, q: "During the total solar eclipse of 29 May 1919, teams in Brazil and on the island of Príncipe photographed stars close to the Sun. What were they testing?", options: ["Whether the Sun has a solid surface", "Whether gravity bends starlight", "Whether light has a top speed", "Whether the Moon has an atmosphere"], answer: 1, fact: "The stars appeared shifted by roughly the amount Einstein predicted, twice Newton's figure, and he was world-famous overnight.", src: "https://en.wikipedia.org/wiki/Eddington_experiment" },
  { cat: "Science", sub: "Physics", diff: 3, kids: false, q: "In 1911 Heike Kamerlingh Onnes cooled mercury to 4.2 degrees above absolute zero. What happened to its electrical resistance?", options: ["It doubled", "It rose very sharply", "It stayed exactly the same", "It vanished completely"], answer: 3, fact: "A current started in a superconducting loop keeps circulating with no battery and no measurable loss.", src: "https://en.wikipedia.org/wiki/Superconductivity" },
  { cat: "Science", sub: "Earth & Space", diff: 1, kids: true, q: "The Ring of Fire, where about 90% of the world's earthquakes happen, runs around the edge of which ocean?", options: ["The Atlantic Ocean", "The Pacific Ocean", "The Indian Ocean", "The Arctic Ocean"], answer: 1, fact: "It also holds around two-thirds of the world's active volcanoes, strung along 40,000 km of colliding plate edges.", src: "https://en.wikipedia.org/wiki/Ring_of_Fire" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: false, q: "In 1912 Alfred Wegener argued that the continents had once been joined and had since drifted apart. Why did most geologists reject the idea?", options: ["He had gathered no fossil evidence at all", "He could not explain what force would move a continent", "The coastlines plainly did not fit together", "He never published the idea in his lifetime"], answer: 1, fact: "Proof came from the seabed in the 1960s: stripes of magnetised rock beside mid-ocean ridges show new crust spreading outwards.", src: "https://en.wikipedia.org/wiki/Continental_drift" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: false, q: "Working from ship soundings in the 1950s, which scientist mapped a deep rift valley running down the middle of the Atlantic seafloor?", options: ["Rachel Carson", "Inge Lehmann", "Marie Tharp", "Sylvia Earle"], answer: 2, fact: "Her collaborator first dismissed the rift as 'girl talk'; it is in fact where new ocean floor is made.", src: "https://en.wikipedia.org/wiki/Marie_Tharp" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: false, q: "In 132 CE the Han-dynasty scholar Zhang Heng built a bronze instrument that could do what?", options: ["Predict eclipses a year in advance", "Measure the height of distant mountains", "Weigh a sealed container of air", "Show the direction of a distant earthquake"], answer: 3, fact: "Eight dragons held bronze balls; a tremor dropped one into a toad's mouth before any messenger could ride the 500 km with the news.", src: "https://en.wikipedia.org/wiki/Zhang_Heng" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "The 1883 eruption of Krakatoa, in what is now Indonesia, made what is thought to be the loudest sound in recorded history. How far away was it heard?", options: ["About 120 km", "About 480 km", "About 4,800 km", "About 15,000 km"], answer: 2, fact: "On Rodrigues Island, near Mauritius, it was mistaken for distant gunfire; barometers tracked the pressure wave circling the globe.", src: "https://en.wikipedia.org/wiki/1883_eruption_of_Krakatoa" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: false, q: "The eruption of Mount Tambora in Indonesia in 1815 was followed, half a world away, by what in 1816?", options: ["A decade of record warmth", "A 'year without a summer' and failed harvests", "The draining of the Great Lakes", "A complete halt to Atlantic storms"], answer: 1, fact: "It was the largest eruption in recorded history: the ash cooled the whole planet and crops failed across the northern hemisphere.", src: "https://en.wikipedia.org/wiki/Mount_Tambora" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "Which layer of the atmosphere holds the ozone that absorbs most of the Sun's ultraviolet light?", options: ["The troposphere", "The mesosphere", "The thermosphere", "The stratosphere"], answer: 3, fact: "The 1987 Montreal Protocol phased out the chemicals thinning it, and the Antarctic ozone hole is slowly closing.", src: "https://en.wikipedia.org/wiki/Ozone_layer" },
  { cat: "Science", sub: "Earth & Space", diff: 1, kids: true, q: "What creates the aurora — the northern and southern lights?", options: ["Sunlight bouncing off the polar ice and back into the sky", "Charged particles from the Sun striking gases high above us", "Lightning storms flashing inside very high clouds", "Moonlight scattered by ice crystals in the upper air"], answer: 1, fact: "North and south can light up as near mirror images at the same moment, on the same magnetic field lines — usually near the equinoxes.", src: "https://en.wikipedia.org/wiki/Aurora" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: false, q: "El Niño, the warm Pacific event that shifts weather worldwide, was named by fishermen of which country?", options: ["Japan", "Australia", "Portugal", "Peru"], answer: 3, fact: "They called the warm current 'the Christ Child' because it showed up around Christmas.", src: "https://en.wikipedia.org/wiki/El_Ni%C3%B1o" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: false, q: "Ice ages come and go with slow changes in Earth's orbit and tilt. Which scientist worked out the cycles behind them?", options: ["Alfred Wegener", "Charles Lyell", "Milutin Milanković", "Louis Agassiz"], answer: 2, fact: "He did much of the mathematics by hand while interned in Budapest during the First World War.", src: "https://en.wikipedia.org/wiki/Milutin_Milankovi%C4%87" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "Why do we always see the same face of the Moon from Earth?", options: ["It does not rotate at all", "It turns once on its axis for every orbit it makes", "It is not really a sphere", "Earth's shadow hides the far side"], answer: 1, fact: "Its orbit is slightly oval and tilted, so over time we glimpse about 59% of the surface, not just half.", src: "https://en.wikipedia.org/wiki/Tidal_locking" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: false, q: "Apollo astronauts and Soviet rovers left mirrors on the Moon. What are scientists on Earth still doing with them?", options: ["Reflecting sunlight to light up future landing sites", "Sending coded signals onward to other spacecraft", "Bouncing laser beams off them to measure the Moon's distance", "Watching for the flashes of meteorite impacts"], answer: 2, fact: "The measurements show the Moon drifting about 3.8 cm farther away each year — roughly the rate fingernails grow.", src: "https://en.wikipedia.org/wiki/Lunar_Laser_Ranging_experiments" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: false, q: "A total solar eclipse is only possible thanks to a coincidence. What is it?", options: ["The Moon and the Sun are almost exactly the same true size", "The Moon's orbit around Earth happens to be a perfect circle", "The Sun is about 400 times wider than the Moon, and 400 times farther", "Earth and the Moon happen to spin at exactly the same rate"], answer: 2, fact: "Because the Moon is slowly moving away, total eclipses will stop between 650 million and 1.4 billion years from now.", src: "https://en.wikipedia.org/wiki/Solar_eclipse" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: false, q: "In 1054 Chinese astronomers logged a 'guest star' bright enough to be seen in broad daylight. What do we call its remains today?", options: ["The Orion Nebula", "The Andromeda Galaxy", "The Pleiades", "The Crab Nebula"], answer: 3, fact: "At its centre spins a pulsar: a star barely 30 km across, turning about 30 times every second.", src: "https://en.wikipedia.org/wiki/Crab_Nebula" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: false, q: "In 964 the Persian astronomer Abd al-Rahman al-Sufi described a 'small cloud' in the night sky. What was it?", options: ["Halley's Comet", "The Andromeda Galaxy", "The planet Saturn", "A total lunar eclipse"], answer: 1, fact: "It is the first galaxy beyond our own ever written down — more than six centuries before the telescope existed.", src: "https://en.wikipedia.org/wiki/Abd_al-Rahman_al-Sufi" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "Many Aboriginal Australian peoples see an emu in the night sky. What is that constellation made of?", options: ["An alignment of seven especially bright stars", "Dark dust clouds silhouetted against the Milky Way", "A tight cluster of unusually red giant stars", "The glowing trail left behind by a bright comet"], answer: 1, fact: "For the Yamatji, when the emu sits low on the horizon at sunset it is time to harvest emu eggs — a calendar in the sky's dark patches.", src: "https://en.wikipedia.org/wiki/Australian_Aboriginal_astronomy" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: false, q: "The Vrihat Samrat Yantra, completed at Jaipur in India in 1734, is the world's largest stone example of which instrument?", options: ["A telescope", "A water clock", "A sundial", "A celestial globe"], answer: 2, fact: "Its 27-metre gnomon casts a shadow that creeps about a millimetre a second: you can stand there and watch time move.", src: "https://en.wikipedia.org/wiki/Jantar_Mantar,_Jaipur" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "The crater left by the asteroid impact linked to the extinction of the dinosaurs lies buried beneath which region?", options: ["The Sahara, in Algeria", "Siberia, in Russia", "Western Australia", "The Yucatán Peninsula, Mexico"], answer: 3, fact: "About 200 km across, it was found not by fossil hunters but by geophysicists surveying the ground for oil.", src: "https://en.wikipedia.org/wiki/Chicxulub_crater" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "Which spacecraft, launched in 1977, became the first human-made object to reach interstellar space?", options: ["Pioneer 10", "Voyager 1", "Cassini", "New Horizons"], answer: 1, fact: "It carries a gold-plated record of greetings in 55 languages, whale song and music, in case anyone ever finds it.", src: "https://en.wikipedia.org/wiki/Voyager_1" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: false, q: "In August 2023, which country's mission made the first soft landing near the Moon's south pole?", options: ["Japan", "Israel", "India", "Brazil"], answer: 2, fact: "Its rover Pragyan found sulphur in the soil, and India became the fourth nation to land softly on the Moon.", src: "https://en.wikipedia.org/wiki/Chandrayaan-3" },

  // ---------- HUMAN BODY (added 2026-08-12) ----------
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which is the only bone in the human body not joined to any other bone?", options: ["The kneecap","The collarbone","The hyoid, in the throat","The tailbone"], answer: 2, fact: "The hyoid hangs in a sling of muscle above the voice box and anchors the tongue — that freedom is part of how we shape speech.", src: "https://en.wikipedia.org/wiki/Hyoid_bone" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "Which is the smallest skeletal muscle in the human body?", options: ["A muscle in the eyelid","The stapedius, in the middle ear","A muscle in the little finger","A muscle in the lower lip"], answer: 1, fact: "About a millimetre long, it tightens against loud noise to damp the vibration of the ear's smallest bone.", src: "https://en.wikipedia.org/wiki/Stapedius_muscle" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "For the force it can produce relative to its size, which is the strongest muscle in the human body?", options: ["The calf muscle","The thigh muscle","The muscle of the upper arm","The masseter, in the jaw"], answer: 3, fact: "Bite force at the back teeth can exceed 70 kg — far more than the front teeth ever deliver.", src: "https://en.wikipedia.org/wiki/Masseter_muscle" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which is the longest bone in the human body?", options: ["The femur, in the thigh","The humerus, in the upper arm","The tibia, in the shin","The longest vertebra of the spine"], answer: 0, fact: "The femur carries several times your body weight, and its length is roughly a quarter of your height.", src: "https://en.wikipedia.org/wiki/Femur" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: false, q: "Which protein is the most abundant in the human body?", options: ["Haemoglobin","Collagen","Insulin","Keratin"], answer: 1, fact: "Collagen is the scaffolding of skin, bone, tendon and cartilage — roughly a third of all the protein you are made of.", src: "https://en.wikipedia.org/wiki/Collagen" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "Long dismissed as useless, the appendix is now thought to act as what?", options: ["A second stomach for tough food","A store of spare blood","A safe reservoir for helpful gut bacteria","A gland that makes digestive acid"], answer: 2, fact: "After an illness clears the gut out, the appendix appears to help repopulate it — which would explain why evolution kept it.", src: "https://en.wikipedia.org/wiki/Appendix_(anatomy)" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "Smell is unusual among the senses. What does it do that sight and hearing do not?", options: ["It reaches the brain's emotion and memory areas almost directly","It works only while you are awake","It uses no nerves at all","It is processed entirely inside the nose"], answer: 0, fact: "Smell signals skip the brain's usual relay station, which is why a scent can pull up a memory before you can name it.", src: "https://en.wikipedia.org/wiki/Olfactory_system" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "Your gut holds its own network of hundreds of millions of neurons. What is it often nicknamed?", options: ["The blood engine","The third lung","The inner mind","The second brain"], answer: 3, fact: "The enteric nervous system can run digestion on its own, even when its line to the brain is cut.", src: "https://en.wikipedia.org/wiki/Enteric_nervous_system" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "Which thick bundle of nerve fibres carries messages between the brain's left and right halves?", options: ["The brain stem","The corpus callosum","The cerebellum","The spinal cord"], answer: 1, fact: "It holds around 200 million fibres; when surgeons cut it to stop severe seizures, the two halves can start acting almost independently.", src: "https://en.wikipedia.org/wiki/Corpus_callosum" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "The windpipe is held open by rings of cartilage shaped like a C rather than a full circle. Why?", options: ["So the food pipe behind it can bulge as you swallow","So it can be opened quickly in surgery","So sound can escape when you speak","So it can fold flat when you hold your breath"], answer: 0, fact: "The open side of every ring faces backwards, leaving the oesophagus room to widen with each mouthful.", src: "https://en.wikipedia.org/wiki/Trachea" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which flap of cartilage folds down over your windpipe every time you swallow?", options: ["The uvula","The tonsil","The epiglottis","The larynx"], answer: 2, fact: "It shuts the airway for about a second at a time; when the timing slips you cough — that is food 'going down the wrong way'.", src: "https://en.wikipedia.org/wiki/Epiglottis" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "The old diagram putting sweet at the tip of the tongue and bitter at the back is:", options: ["Correct for adults but not for children","A misreading of an old study, and wrong","Correct only for some people","A recent discovery"], answer: 1, fact: "It came from a misread German paper of 1901; every part of the tongue that tastes at all can detect every basic taste.", src: "https://en.wikipedia.org/wiki/Tongue_map" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "What makes the popping sound when a knuckle cracks?", options: ["Two bones knocking together","A tendon snapping over bone","Cartilage tearing very slightly","A bubble forming in the joint's fluid"], answer: 3, fact: "Pulling the joint drops the pressure until a gas bubble appears in the lubricating fluid — and it cannot crack again until that dissolves.", src: "https://en.wikipedia.org/wiki/Joint_cracking" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "Which body-wide network drains fluid from your tissues and carries immune cells, yet has no pump of its own?", options: ["The lymphatic system","The nervous system","The endocrine system","The digestive system"], answer: 0, fact: "It is pushed along by your own movement, muscles squeezing the vessels — one reason sitting still all day makes legs swell.", src: "https://en.wikipedia.org/wiki/Lymphatic_system" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "In the human eye, light passes through the retina's nerve cells before reaching the cells that actually detect it. This arrangement is:", options: ["Unique to humans","The reason we see in colour","Backwards compared with an octopus eye","Found only in night-active animals"], answer: 2, fact: "The octopus eye evolved separately and is wired the other way round, with the light-detecting cells facing the light.", src: "https://en.wikipedia.org/wiki/Retina" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Fingernails grow at roughly what rate compared with toenails?", options: ["About ten times faster","About twice as fast","About the same","About half as fast"], answer: 1, fact: "Nails on your dominant hand, and on the longer fingers, grow fastest — blood supply and everyday knocks both seem to speed them up.", src: "https://en.wikipedia.org/wiki/Nail_(anatomy)" },
  { cat: "Science", sub: "Life Sciences", diff: 2, kids: true, q: "Which narrow tube equalises the pressure behind your eardrum as a plane takes off?", options: ["The Eustachian tube","The ear canal","The cochlear duct","The optic canal"], answer: 0, fact: "It opens when you swallow or yawn, letting air up from the back of the nose — which is why chewing helps on the way down.", src: "https://en.wikipedia.org/wiki/Eustachian_tube" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Why is the surface of the human brain so deeply wrinkled?", options: ["It helps the brain cool down","It makes the brain lighter","It cushions against knocks","It fits far more surface area inside the skull"], answer: 3, fact: "Spread flat, the cortex would cover about 2,500 square centimetres — roughly a large table napkin.", src: "https://en.wikipedia.org/wiki/Cerebral_cortex" },
  { cat: "Science", sub: "Life Sciences", diff: 1, kids: true, q: "Which is the largest artery in the human body?", options: ["The carotid artery","The femoral artery","The aorta","The pulmonary artery"], answer: 2, fact: "About as wide as a garden hose, it arches straight out of the heart and runs the length of the trunk before dividing towards the legs.", src: "https://en.wikipedia.org/wiki/Aorta" },
  { cat: "Science", sub: "Life Sciences", diff: 3, kids: false, q: "What speeds up the signals travelling along your nerves?", options: ["A fatty sheath wrapped around the nerve fibre","A stronger electrical charge","A wider channel through the bone","Extra blood flow to the nerve"], answer: 0, fact: "Myelin lets the signal jump from gap to gap instead of crawling, carrying nerve impulses at over 100 metres a second.", src: "https://en.wikipedia.org/wiki/Myelin" },

  // ---------- BATCH 2026-08-13 · thin sub-topics first ----------
  { cat: "Science", sub: "Chemistry", diff: 3, kids: true, q: "Across Mesoamerica, maize is soaked and cooked in limewater before it is ground. Which vitamin deficiency does this prevent?", options: ["Niacin (vitamin B3)","Vitamin C","Vitamin D","Vitamin K"], answer: 0, fact: "Where maize travelled without the lime treatment, the deficiency travelled with it: pellagra was endemic among poor households in the southern United States into the early twentieth century.", src: "https://en.wikipedia.org/wiki/Nixtamalization" },
  { cat: "Science", sub: "Chemistry", diff: 3, kids: true, q: "Maya blue still holds its colour on murals more than a thousand years old. What is the indigo dye in it bound to?", options: ["A clay","Beeswax","Powdered jade","Egg white"], answer: 0, fact: "The bond is extraordinarily tough: the pigment shrugs off solvents, alkalis and even nitric acid, and only very harsh acid treatment under reflux will break it down.", src: "https://en.wikipedia.org/wiki/Maya_blue" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "Carmine, the deep red used in food colouring and lipstick, is extracted from what?", options: ["A scale insect that lives on cactus","A desert flower","An iron-rich clay","The bark of a tropical tree"], answer: 0, fact: "In colonial Mexico carmine became the region's second most valuable export after silver, and its price was quoted regularly on the London and Amsterdam commodity exchanges.", src: "https://en.wikipedia.org/wiki/Cochineal" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "Which microbes take over as kimchi ferments and give it its sourness?", options: ["Lactic acid bacteria","Brewer's yeast","Blue moulds","Acetic acid bacteria"], answer: 0, fact: "Fermentation keeps producing carbon dioxide, so a sealed jar builds pressure and has to be opened now and then. Left long enough, the brine fizzes like a carbonated drink.", src: "https://en.wikipedia.org/wiki/Kimchi" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "The fish in ceviche turns white and firm without any heat. What has the citrus juice done to its proteins?", options: ["Denatured them","Frozen them","Dissolved them","Turned them into sugars"], answer: 0, fact: "Limes arrived with the Spanish. Cooks on the Andean coast had been getting the same effect long before, using the juice of native fruits such as tumbo, the banana passionfruit.", src: "https://en.wikipedia.org/wiki/Ceviche" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "Porcelain is fired far hotter than ordinary pottery. Which white clay mineral is its main ingredient?", options: ["Kaolinite","Bentonite","Gypsum","Chalk"], answer: 0, fact: "Fired between about 1,200 and 1,400 °C, the body vitrifies — partly turns to glass — which is where the strength and the translucence come from. The English word comes from the Italian porcellana, cowrie shell, for the look of the surface.", src: "https://en.wikipedia.org/wiki/Porcelain" },
  { cat: "Science", sub: "Chemistry", diff: 3, kids: true, q: "The patterned Damascus blades of the Near East were forged from crucible steel ingots imported from where?", options: ["Southern India and Sri Lanka","Scandinavia","Egypt","Korea"], answer: 0, fact: "The name may owe as much to water as to the city: damas is the Arabic root for watered, and the blades were described everywhere by the flowing, rippled pattern on their surface.", src: "https://en.wikipedia.org/wiki/Damascus_steel" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "Long before gunpowder, people in Han-dynasty China made festival bangs by throwing what onto a fire?", options: ["Bamboo stems","Dried gourds","Lumps of pine resin","Sealed clay pots"], answer: 0, fact: "Colour arrived much later, and it comes from metals: compounds of barium, strontium, copper and sodium each burn with their own signature shade.", src: "https://en.wikipedia.org/wiki/Fireworks" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: false, q: "Toast, seared meat and fried onions all brown by the same reaction. Sugars in the food react with what?", options: ["Amino acids","Salt","Oxygen alone","Water"], answer: 0, fact: "The same chemistry runs cold and slow inside peat bogs, where it browns the skin of Iron Age bog bodies and turns their hair a reddish ginger.", src: "https://en.wikipedia.org/wiki/Maillard_reaction" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "Which scientist found the antimalarial drug artemisinin by working through classical Chinese medical texts?", options: ["Tu Youyou","Chien-Shiung Wu","Ahmed Zewail","Har Gobind Khorana"], answer: 0, fact: "The first extracts failed because the team used hot water. A recipe written by Ge Hong in the year 340 said to steep the herb in cold water, and switching to a low-temperature extraction made it work.", src: "https://en.wikipedia.org/wiki/Tu_Youyou" },
  { cat: "Science", sub: "Chemistry", diff: 1, kids: true, q: "Salicin, the ancestor of aspirin, has been used against pain for at least 2,400 years. It comes from the bark of which tree?", options: ["Willow","Oak","Birch","Cedar"], answer: 0, fact: "The name is a chemist's compound word: a for the acetyl group added to make it less irritating, and spir for Spiraea, the meadowsweet from which salicylic acid was first isolated.", src: "https://en.wikipedia.org/wiki/Aspirin" },
  { cat: "Geography", sub: "Cities & Places", diff: 1, kids: true, q: "The Moroccan town of Chefchaouen, in the Rif mountains, is famous for streets and walls painted in which colour?", options: ["Blue","Deep red","Green","Yellow"], answer: 0, fact: "Nobody quite agrees why. Explanations range from repelling mosquitoes to standing for the sky, and some residents say the blue-washing only became the rule in the 1970s to draw visitors. The town itself is far older, founded in 1471 as a fortress against Portuguese raids.", src: "https://en.wikipedia.org/wiki/Chefchaouen" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "Shibam in Yemen is nicknamed the Manhattan of the Desert for its tower houses. What are they built of?", options: ["Mud brick","Coral blocks","Granite","Poured concrete"], answer: 0, fact: "Some rise eleven storeys and more than 30 metres, all of it earth dried in the sun. Shibam is one of the oldest examples of town planning built on the principle of going upwards.", src: "https://en.wikipedia.org/wiki/Shibam" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "Addis Ababa, the capital of Ethiopia, has a name meaning what in Amharic?", options: ["New flower","High meadow","Place of the crossing","Gate of the king"], answer: 0, fact: "Empress Taytu chose it, having persuaded Emperor Menelik II to bring the court down from cold, windy Entoto to the plain below. At 2,355 metres the city is still the highest capital in Africa.", src: "https://en.wikipedia.org/wiki/Addis_Ababa" },
  { cat: "Geography", sub: "Cities & Places", diff: 1, kids: true, q: "Which city lies at the foot of Table Mountain?", options: ["Cape Town","Durban","Maputo","Windhoek"], answer: 0, fact: "The flat top is the floor of an ancient valley. Hard sandstone sagged into a downfold, the softer rock around it wore away, and the valley bottom was left standing at roughly 1,085 metres.", src: "https://en.wikipedia.org/wiki/Table_Mountain" },
  { cat: "Geography", sub: "Cities & Places", diff: 3, kids: true, q: "Guinness World Records lists the largest church in the world. In which country does it stand?", options: ["Ivory Coast","Italy","Brazil","Spain"], answer: 0, fact: "The Basilica of Our Lady of Peace went up at Yamoussoukro between 1985 and 1989, a gift to the Catholic Church from President Félix Houphouët-Boigny. Its complex covers 30,000 square metres, more than St Peter's in Rome.", src: "https://en.wikipedia.org/wiki/Basilica_of_Our_Lady_of_Peace" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "The plain of Bagan, covered with more than 2,000 surviving temples and pagodas, lies in which country?", options: ["Myanmar","Nepal","Thailand","Sri Lanka"], answer: 0, fact: "Over 10,000 were built there between the 11th and 13th centuries, when Bagan was capital of the Pagan kingdom. Only about a fifth are still standing.", src: "https://en.wikipedia.org/wiki/Bagan" },
  { cat: "Geography", sub: "Cities & Places", diff: 1, kids: true, q: "Singapore's name comes from Sanskrit. What does it mean?", options: ["Lion city","Island of spices","Harbour of ships","City of gardens"], answer: 0, fact: "The Malay Annals tell of the prince Sang Nila Utama landing on the island, seeing a strange beast he took for a lion, and reading it as an omen worth founding a town on.", src: "https://en.wikipedia.org/wiki/Singapore" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "Which is the coldest capital city in the world by average annual temperature?", options: ["Ulaanbaatar","Reykjavík","Ottawa","Moscow"], answer: 0, fact: "Its yearly mean sits at about 0.2°C. Before it settled where it now stands in 1778, the city was a moving monastery town that shifted site 29 times.", src: "https://en.wikipedia.org/wiki/Ulaanbaatar" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "Jaipur is known as India's Pink City. Why was it painted pink?", options: ["To welcome a visiting British prince","To reflect the heat of the desert","Because the local building stone is pink","To celebrate a maharaja's wedding"], answer: 0, fact: "The order came in 1876 under Sawai Ram Singh II. The city was already 150 years old by then, laid out in 1727 on a grid of nine blocks with streets 34 metres wide.", src: "https://en.wikipedia.org/wiki/Jaipur" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "Indonesia is moving its capital from Jakarta to a new city called Nusantara. On which island is it being built?", options: ["Borneo","Sumatra","Sulawesi","Java"], answer: 0, fact: "Jakarta is sinking. Pumping groundwater from under the city, together with the weight of building on it, has dropped the land and left the northern coast ever more open to floods.", src: "https://en.wikipedia.org/wiki/Jakarta" },
  { cat: "Geography", sub: "Cities & Places", diff: 1, kids: true, q: "Cusco, high in the Peruvian Andes, was the capital of which empire?", options: ["The Inca empire","The Aztec empire","The Chimú empire","The Tiwanaku empire"], answer: 0, fact: "The old centre is widely thought to have been laid out as an effigy of a puma, a sacred animal. The city stands at about 3,400 metres.", src: "https://en.wikipedia.org/wiki/Cusco" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "The world's largest salt flat, the Salar de Uyuni, lies in which country?", options: ["Bolivia","Chile","Namibia","Iran"], answer: 0, fact: "It is so flat, under a metre of variation across 10,582 square kilometres, and so bright that satellites are calibrated against it, roughly five times more usefully than against the open ocean.", src: "https://en.wikipedia.org/wiki/Salar_de_Uyuni" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "Uluru rises from the Australian desert. What kind of rock is it?", options: ["Sandstone","Granite","Basalt","Limestone"], answer: 0, fact: "It stands 348 metres above the plain and takes 9.4 kilometres to walk around, yet most of its bulk lies underground. Climbing it was closed in 2019 at the wish of the Aṉangu, its traditional owners.", src: "https://en.wikipedia.org/wiki/Uluru" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "What do the buildings of Venice ultimately rest on?", options: ["Wooden piles driven into the mud","Granite bedrock beneath the lagoon","Hollow concrete floats anchored down","A natural bank of packed shells"], answer: 0, fact: "Alder trunks were driven down until they struck hard clay, then capped with plates of Istrian limestone. The first Venetians were refugees from Roman towns on the mainland, drawn to a lagoon that armies found hard to follow them into.", src: "https://en.wikipedia.org/wiki/Venice" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "The Okavango Delta, where a great river spreads out and never reaches the sea, lies in which country?", options: ["Botswana","Namibia","Zambia","Mali"], answer: 0, fact: "Almost all the water evaporates or sinks away. The flood comes down from the Angolan highlands in the middle of Botswana's dry winter, months after the rain that made it.", src: "https://en.wikipedia.org/wiki/Okavango_Delta" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "Which is the deepest river in the world, with places around 220 metres deep?", options: ["The Amazon","The Mekong","The Congo","The Yangtze"], answer: 2, fact: "It is the only major river to cross the equator twice, so some part of its basin is always in a rainy season and its flow barely changes through the year.", src: "https://en.wikipedia.org/wiki/Congo_River" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "Socotra, an island famous for its umbrella-shaped dragon's blood trees, belongs to which country?", options: ["Somalia","Yemen","Oman","Eritrea"], answer: 1, fact: "About 37 per cent of its plants grow nowhere else on Earth, which has earned the island the nickname the Galápagos of the Indian Ocean.", src: "https://en.wikipedia.org/wiki/Socotra" },
  { cat: "Geography", sub: "Landscapes", diff: 3, kids: true, q: "The Danakil Depression is being pulled apart by two tectonic plates. What is it on its way to becoming?", options: ["A mountain range","A high plateau","A deep freshwater lake","A new ocean"], answer: 3, fact: "It lies about 100 metres below sea level and has the highest year-round average temperature of anywhere on Earth.", src: "https://en.wikipedia.org/wiki/Danakil_Depression" },
  { cat: "Geography", sub: "Landscapes", diff: 1, kids: true, q: "The Sundarbans, the largest mangrove forest in the world, is shared between India and which country?", options: ["Myanmar","Sri Lanka","Bangladesh","Nepal"], answer: 2, fact: "It is the only mangrove forest where tigers live, and they swim between the islands. The forest also takes the first blow from cyclones coming up the Bay of Bengal.", src: "https://en.wikipedia.org/wiki/Sundarbans" },
  { cat: "Geography", sub: "Landscapes", diff: 1, kids: true, q: "Lake Titicaca, often called the highest navigable lake in the world, sits on the border of Bolivia and which country?", options: ["Peru","Chile","Brazil","Ecuador"], answer: 0, fact: "The Uru people live on islands they build themselves from layers of cut totora reed, adding fresh reed on top as the bottom slowly rots away.", src: "https://en.wikipedia.org/wiki/Lake_Titicaca" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "If the Greenland ice sheet melted completely, roughly how much would global sea level rise?", options: ["About 70 centimetres","About 7 metres","About 25 metres","About 60 metres"], answer: 1, fact: "The ice buries around 80 per cent of Greenland and is nearly 3.5 kilometres thick at its deepest, making it the second largest body of ice on Earth after Antarctica's.", src: "https://en.wikipedia.org/wiki/Greenland_ice_sheet" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "Perito Moreno, a glacier that repeatedly dams a lake and then bursts through its own ice, is in which country?", options: ["Norway","Canada","New Zealand","Argentina"], answer: 3, fact: "Water trapped behind the ice can stand up to 30 metres higher than the rest of the lake before the arch collapses. The rupture has come round anywhere between once a year and less than once a decade.", src: "https://en.wikipedia.org/wiki/Perito_Moreno_Glacier" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "Madagascar's Tsingy de Bemaraha is a forest of razor-sharp pinnacles made of which rock?", options: ["Basalt","Granite","Limestone","Sandstone"], answer: 2, fact: "The word tsingy comes from a local term for the place where one cannot walk barefoot. Lemurs cross the blades of stone with no trouble at all.", src: "https://en.wikipedia.org/wiki/Tsingy_de_Bemaraha_Strict_Nature_Reserve" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "The white terraces of Pamukkale in Turkey were built up by what?", options: ["A retreating glacier","Mineral-rich hot springs","Wind-blown sea salt","Falling volcanic ash"], answer: 1, fact: "The name means cotton castle. The Greeks built the city of Hierapolis on top of the terraces, which run for some 2.7 kilometres.", src: "https://en.wikipedia.org/wiki/Pamukkale" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "What is the Great Blue Hole, the dark circle in the reef off Belize?", options: ["A meteorite crater","A volcanic vent","A harbour dug by hand","A flooded limestone cave"], answer: 3, fact: "Stalactites still hang inside it, formed in dry air when the sea stood far lower during the ice ages. Jacques Cousteau charted its depths in 1971.", src: "https://en.wikipedia.org/wiki/Great_Blue_Hole" },
  { cat: "Geography", sub: "Landscapes", diff: 2, kids: true, q: "What sits in the summit crater of Antarctica's Mount Erebus?", options: ["A frozen meltwater lake","A field of meteorites","A lake of molten lava","A research station"], answer: 2, fact: "The volcano breathes out roughly 80 grams of gold a day as vapour, and microscopic specks of it have been picked up 1,000 kilometres away.", src: "https://en.wikipedia.org/wiki/Mount_Erebus" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "China's Chang'e 4 landed on the far side of the Moon in 2019. Why did it need a separate satellite parked beyond the Moon?", options: ["Radio signals cannot travel directly between Earth and the far side","The far side is in permanent darkness, ruling out solar power","The Moon's magnetic field scrambles radio transmissions","The lander's antenna was too small to reach Earth"], answer: 0, fact: "The relay satellite is called Queqiao, the bridge of magpies, after a Chinese tale in which birds form a bridge so that two separated lovers can meet once a year. It waits about 65,000 km beyond the Moon.", src: "https://en.wikipedia.org/wiki/Chang%27e_4" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "The Hope probe entered orbit around Mars in February 2021. It was the first interplanetary mission by which country?", options: ["Egypt","United Arab Emirates","Turkey","Malaysia"], answer: 1, fact: "Hope lifted off from Japan on a Japanese rocket, and flies an unusually wide orbit. That lets it watch a whole Martian day across the whole planet, which earlier orbiters on tighter paths could not do.", src: "https://en.wikipedia.org/wiki/Emirates_Mars_Mission" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "China's FAST is the world's largest single-dish radio telescope, 500 metres across. What holds a dish that size?", options: ["A natural bowl-shaped hollow in limestone hills","A steel tower built out over a valley","A flooded quarry drained for the purpose","A mountain top levelled by explosives"], answer: 0, fact: "The dish is not one rigid mirror. Its 4,450 triangular panels hang on cables and are pulled into shape, bending a 300-metre section into a curve aimed at whichever part of the sky is being watched.", src: "https://en.wikipedia.org/wiki/Five-hundred-meter_Aperture_Spherical_Telescope" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "ALMA's 66 antennas stand 5,000 metres up on a plateau in Chile's Atacama Desert. Why put them somewhere so high and so dry?", options: ["Water vapour in the air swallows the signals they collect","The thin air keeps the antennas from overheating","The height brings the dishes measurably closer to the stars","Dry air stops the metal dishes corroding"], answer: 0, fact: "The dishes get rearranged by two 28-wheel transporters that lift a 100-tonne antenna and drive it up to 16 km across the plateau, spreading the array out or drawing it in like adjusting a lens.", src: "https://en.wikipedia.org/wiki/Atacama_Large_Millimeter_Array" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "The Richat Structure in Mauritania forms rings of rock about 40 km across in the Sahara. What made it?", options: ["A dome of rock pushed up from below and then worn down","A meteorite striking the desert","A volcano whose crater collapsed inwards","An inland sea that dried out in stages"], answer: 0, fact: "Astronauts use it to get their bearings. Seen from orbit that stretch of the Sahara is close to featureless, and the Eye of Africa is one of the few things that stands out.", src: "https://en.wikipedia.org/wiki/Richat_Structure" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "Saturn's moon Enceladus sprays jets of water ice into space through cracks near its south pole. What lies beneath its icy shell?", options: ["An ocean of liquid water","A core of molten iron","A layer of liquid methane","Solid rock all the way down"], answer: 0, fact: "The spray feeds one of Saturn's rings, and the Cassini spacecraft flew straight through it, sampling the ocean of another world without ever landing on it.", src: "https://en.wikipedia.org/wiki/Enceladus" },
  { cat: "Science", sub: "Earth & Space", diff: 1, kids: true, q: "Venus lies farther from the Sun than Mercury, yet its surface is far hotter. Why?", options: ["A dense carbon dioxide atmosphere holds the heat in","Its core is much larger and still molten","It turns so slowly that one side bakes","Its whole surface is covered in erupting volcanoes"], answer: 0, fact: "The air presses down as hard as water almost a kilometre deep. The Soviet Venera landers, the only craft ever to send back pictures from the surface, survived barely an hour or two.", src: "https://en.wikipedia.org/wiki/Venus" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "A returning boomerang spins as it flies. What makes its path curve back towards the thrower?", options: ["Uneven lift on its spinning arms","A slight curve carved into the wood","The wind pushing on its flat face","One end being heavier than the other"], answer: 0, fact: "Most traditional Australian boomerangs were never meant to come back — they were throwing sticks for hunting. The returning kind was unknown across large parts of the continent, including Tasmania and much of the Northern Territory.", src: "https://en.wikipedia.org/wiki/Boomerang" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "At the Noor complex near Ouarzazate in Morocco, thousands of mirrors track the Sun. What lets the plant keep making electricity after sunset?", options: ["Heat stored in molten salt","Banks of lithium batteries","Water pumped into a high reservoir","Stored hydrogen burnt at night"], answer: 0, fact: "The tower at the centre of Noor III stands about 250 metres tall, with heliostats spread across the desert floor aiming sunlight at its top. The stored heat carries the plant for several hours into the dark.", src: "https://en.wikipedia.org/wiki/Ouarzazate_Solar_Power_Station" },
  { cat: "Science", sub: "Physics", diff: 3, kids: true, q: "In 1966 Charles Kao argued that glass fibres could carry light over long distances. What did he say was holding them back?", options: ["Impurities in the glass","The fibres being far too thin","The light being far too bright","The glass being far too flexible"], answer: 0, fact: "He was right, and pure silica fibre now carries most of the world's internet traffic along cables on the ocean floor. He shared the 2009 Nobel Prize in Physics for the work.", src: "https://en.wikipedia.org/wiki/Charles_K._Kao" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "Clap your hands at the foot of the staircase of El Castillo at Chichen Itza, in Mexico, and something odd comes back. What?", options: ["A chirp that falls in pitch","A clap repeated exactly nine times","A low hum lasting several seconds","Complete silence, the sound absorbed"], answer: 0, fact: "The steps return the sound as a rapid descending sweep, which has been compared with the call of the resplendent quetzal. The pyramid carries around 365 steps in all, one for each day of the year.", src: "https://en.wikipedia.org/wiki/El_Castillo,_Chichen_Itza" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "In Ladakh, in northern India, villagers freeze winter water into tall cones called ice stupas. Why a cone rather than a flat sheet?", options: ["It exposes less surface to the Sun","It is easier to break up in spring","It stops snow settling on the ice","It lets the water freeze more quickly"], answer: 0, fact: "The idea came from noticing ice that survived into summer under a bridge, simply because it sat in shade. The cones melt slowly and release their water in spring, exactly when the fields need it.", src: "https://en.wikipedia.org/wiki/Ice_stupa" },
  { cat: "Science", sub: "Physics", diff: 3, kids: true, q: "The water around a working nuclear reactor core glows an eerie blue. What is happening?", options: ["Particles outrunning light in the water","The water being heated until it glows","Uranium giving off blue light as it splits","Blue dye added to make leaks visible"], answer: 0, fact: "It is the optical version of a sonic boom: a shock front of light left behind by charged particles travelling faster than light does through water. Pavel Cherenkov, Igor Tamm and Ilya Frank shared the 1958 Nobel Prize for explaining it.", src: "https://en.wikipedia.org/wiki/Cherenkov_radiation" },
  { cat: "Science", sub: "Physics", diff: 3, kids: true, q: "NASA carried blocks of aerogel on the Stardust mission to catch comet dust. Why would an ordinary solid not do the job?", options: ["The grains would vaporise on impact","The grains would bounce straight off","The grains would stick and never come free","The grains would be too cold to handle"], answer: 0, fact: "Aerogel is up to 99.8% empty space, so it slows a grain gradually instead of stopping it dead. The first batch was made in 1931 by Samuel Kistler, to settle a bet about replacing the liquid in a jelly with gas without the jelly shrinking.", src: "https://en.wikipedia.org/wiki/Aerogel" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "A Prince Rupert's drop is a glass teardrop made by dripping molten glass into water. A hammer blow to the bulb does nothing. What destroys it?", options: ["Snapping the thin tail","Warming it in the hand","Rolling it across a table","Leaving it in bright sunlight"], answer: 0, fact: "The skin of the bulb is squeezed under enormous compression while the inside is pulled tight. Break the tail and a crack races through it at over 1,400 metres per second, turning the whole drop to powder.", src: "https://en.wikipedia.org/wiki/Prince_Rupert%27s_drop" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "As the last sliver of the Sun drops below a clear sea horizon, a brief green spark can appear. What causes it?", options: ["Air bending sunlight into its colours","Sunlight reflecting off the sea surface","Green light given off by plankton","The eye recovering from the glare"], answer: 0, fact: "It rarely lasts more than a second or two. Airline pilots flying west see it more often than most, because chasing the sunset stretches the moment out.", src: "https://en.wikipedia.org/wiki/Green_flash" },
  { cat: "Science", sub: "Physics", diff: 3, kids: true, q: "In November 1940 the Tacoma Narrows Bridge in Washington State twisted itself apart in a wind of only about 64 km/h. What had its designers not allowed for?", options: ["The deck acting like a wing in the wind","The cables stretching in the cold","The towers sinking into the riverbed","The traffic load exceeding the limit"], answer: 0, fact: "The failure is often called resonance, but the modern explanation is aeroelastic flutter: the deck's own twisting fed energy back into itself with nothing to cap it. Wind-tunnel testing of bridge designs became standard afterwards.", src: "https://en.wikipedia.org/wiki/Tacoma_Narrows_Bridge_(1940)" },
  { cat: "Science", sub: "Physics", diff: 1, kids: true, q: "A vacuum flask keeps tea hot for hours. What sits between its two walls?", options: ["Almost nothing at all","A layer of dense foam","Compressed dry air","A thin film of oil"], answer: 0, fact: "With the air mostly removed there is nothing left to carry heat by conduction or convection, and the shiny inner surfaces reflect most of the rest back. James Dewar invented it in 1892 and refused to patent it; two German glassblowers turned it into Thermos.", src: "https://en.wikipedia.org/wiki/Vacuum_flask" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: true, q: "A game show has three doors: a car behind one, goats behind the other two. You pick a door; the host, who knows where the car is, opens another door to reveal a goat and offers you the switch. What should you do?", options: ["Switch, which doubles your chance","Stay, since switching halves your chance","It makes no difference either way","Switch only if you first chose door 1"], answer: 0, fact: "When Marilyn vos Savant printed the switching answer in 1990, around 10,000 readers wrote in to say she was wrong, close to 1,000 of them holding doctorates.", src: "https://en.wikipedia.org/wiki/Monty_Hall_problem" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "In a room of 23 people, what is the chance that two of them share a birthday?", options: ["About 6 per cent","About 23 per cent","About 50 per cent","About 90 per cent"], answer: 2, fact: "Raise the room to 70 people and a match is all but certain, at 99.9 per cent. What counts is not people but pairs, and 23 people make 253 of them.", src: "https://en.wikipedia.org/wiki/Birthday_problem" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "Give a paper strip a half-twist, glue the ends together, then cut all the way along the middle. What comes off the scissors?", options: ["Two separate loops","One longer loop","Two loops linked like a chain","Three loops of equal size"], answer: 1, fact: "Cut the same band a third of the way in from its edge instead and you get two loops threaded through each other, one of which is still a Möbius strip. Machinists once joined drive belts this way so both faces wore evenly.", src: "https://en.wikipedia.org/wiki/M%C3%B6bius_strip" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "One grain of wheat on the first square of a chessboard, two on the second, four on the third, doubling all the way to the 64th. Of all the grain on the finished board, how much sits on that last square alone?", options: ["About a hundredth","About a tenth","About a half","Almost all of it"], answer: 2, fact: "That final square holds more than two billion times the grain of the entire first half of the board, and the whole total, 18.4 quintillion grains, is over a thousand times a year's world wheat harvest.", src: "https://en.wikipedia.org/wiki/Wheat_and_chessboard_problem" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: true, q: "The Koch snowflake is built by adding an ever-smaller triangle to every edge, without end, so its outline is infinitely long. What happens to the area it encloses?", options: ["It is infinite as well","It settles at a finite value","It shrinks away to nothing","It depends on the starting triangle's angles"], answer: 1, fact: "However many times the process is repeated, the area comes to rest at exactly eight-fifths of the triangle it began with: a boundary of endless length drawn around a patch of ground that could be mown.", src: "https://en.wikipedia.org/wiki/Koch_snowflake" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "You are colouring a map so that no two countries sharing a border get the same colour. However tangled the map, how many colours are always enough?", options: ["Three","Four","Five","Seven"], answer: 1, fact: "The proof, finished in 1976, was the first major theorem settled by computer: it works through a catalogue of awkward cases far too large for any person to check by hand, which left some mathematicians uneasy.", src: "https://en.wikipedia.org/wiki/Four_color_theorem" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "Hundreds of beads are dropped through a board of evenly spaced pegs, each bead bouncing left or right at random. What shape does the pile in the bins below take?", options: ["A flat, even spread","A bell-shaped hump in the middle","Two heaps at the outer edges","A different shape every time"], answer: 1, fact: "Pure chance at every peg produces a shape that can be predicted before a single bead falls. It is the central limit theorem built out of wood, and the same reason heights, measurement errors and exam marks pile up alike.", src: "https://en.wikipedia.org/wiki/Galton_board" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "The Chinese suanpan carries two beads above the bar and five below on every rod, more than counting to ten requires. What did the extra beads let a merchant do?", options: ["Reckon in base sixteen for weights","Use the frame as a musical instrument","Write down negative numbers","Keep two separate sums at once"], answer: 0, fact: "A jin weighed sixteen liang, so shopkeepers had to count in sixteens as fluently as in tens. A single suanpan rod holds up to fifteen before it must carry over.", src: "https://en.wikipedia.org/wiki/Suanpan" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "The Luoshu arranges the numbers 1 to 9 in a three-by-three grid so that every row, every column and both diagonals add to the same total. What is that total?", options: ["12","15","18","21"], answer: 1, fact: "It could not be anything else: the nine numbers add to 45, and three rows must share that equally. Chinese tradition holds that the pattern was found on the shell of a turtle rising from the River Luo.", src: "https://en.wikipedia.org/wiki/Luoshu_Square" },
  { cat: "Science", sub: "Mathematics", diff: 3, kids: true, q: "Persian craftsmen built vast interlacing wall patterns from a set of just five tile shapes. In 2007 two physicists argued that the 1453 tilework at the Darb-e Imam shrine in Isfahan anticipated what?", options: ["Quasicrystals, only described in the West much later","Perspective drawing, worked out in Renaissance Italy","The metric system, devised in revolutionary France","Movable type, spread across Europe by Gutenberg"], answer: 0, fact: "The five tiles, a decagon, a pentagon, two hexagons and a rhombus, each carry decorating lines that join up when the tiles touch, so the visible pattern conceals the simple shapes beneath it.", src: "https://en.wikipedia.org/wiki/Girih_tile" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "The Bakhshali manuscript, seventy fragile leaves of birch bark found in 1881 near Peshawar, uses a plain dot again and again. What does the dot stand for?", options: ["Zero, an empty place in a number","A full stop between two problems","An unknown quantity to be found","A unit of weight used in trade"], answer: 0, fact: "Radiocarbon dating in 2017 gave three of its leaves ages centuries apart, roughly the 3rd, the 8th and the 10th century, and scholars still argue over how one manuscript came to gather such different times.", src: "https://en.wikipedia.org/wiki/Bakhshali_manuscript" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "Navigators in the Marshall Islands lashed coconut ribs and cowrie shells into frames that mapped the ocean. What did the curved sticks record?", options: ["The way swells bend around islands","The paths taken by migrating birds","The positions of the stars at dusk","The depth of water over the reefs"], answer: 0, fact: "The frames stayed ashore. A navigator memorised one, then lay flat in the hull at sea and read the same swell patterns through the pitch and roll of the canoe.", src: "https://en.wikipedia.org/wiki/Marshall_Islands_stick_chart" },
  { cat: "Science", sub: "Mathematics", diff: 2, kids: true, q: "On a Mercator world map Greenland looks about the size of Africa. In reality, how much larger than Greenland is Africa?", options: ["About twice","About five times","About fourteen times","About forty times"], answer: 2, fact: "The stretching is the price of a useful trick: on this map any course of constant compass bearing is a straight line, which is why sailors put up with it for four centuries.", src: "https://en.wikipedia.org/wiki/Mercator_projection" },

  // ---------- BATCH 2026-08-13 · thin sub-topics first ----------
  { cat: "Geography", sub: "Cities & Places", diff: 1, kids: true, q: "Khartoum, the capital of Sudan, grew up where two great rivers meet. Which two?", options: ["The Blue Nile and the White Nile","The Nile and the Atbara","The Blue Nile and the Atbara","The White Nile and the Sobat"], answer: 0, fact: "One reading of the city's name traces it to the Arabic khurtum, meaning trunk, for the narrow tongue of land between the two rivers. Another traces it to Dinka words meaning place where rivers meet.", src: "https://en.wikipedia.org/wiki/Khartoum" },
  { cat: "Geography", sub: "Cities & Places", diff: 1, kids: true, q: "Many people in Coober Pedy, in outback South Australia, live in dugouts bored into the hillsides. Why?", options: ["To escape the scorching daytime heat","To shelter from seasonal floods","Because building timber is scarce there","To keep out the region's red dust"], answer: 0, fact: "A three-bedroom cave home can be excavated for roughly the price of building one on the surface. The town also has underground motels and underground churches, and its name is thought to come from the Kokatha-Barngarla term kupa-piti.", src: "https://en.wikipedia.org/wiki/Coober_Pedy" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "Mexico City keeps sinking because it stands on the saturated clay of a drained lake bed. Which lake?", options: ["Lake Texcoco","Lake Chapala","Lake Pátzcuaro","Lake Cuitzeo"], answer: 0, fact: "Parts of the city have dropped as much as nine metres since the start of the twentieth century, and it is still going down by almost 50 centimetres a year. The city sits about 2,240 metres above sea level.", src: "https://en.wikipedia.org/wiki/Mexico_City" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "Which capital city's full ceremonial name is listed in Guinness World Records as the world's longest place name?", options: ["Bangkok","Jakarta","Kuala Lumpur","Manila"], answer: 0, fact: "The name runs to 168 letters of Pali and Sanskrit, and translates roughly as the city of angels, great city of immortals, seat of the king, home of gods incarnate. Krung Thep Maha Nakhon is the official short name; in everyday speech Thais shorten it further, to Krung Thep.", src: "https://en.wikipedia.org/wiki/Bangkok" },
  { cat: "Geography", sub: "Cities & Places", diff: 2, kids: true, q: "The fortified village of Aït Benhaddou in Morocco stood on an old caravan route running from Marrakesh to where?", options: ["The Sahara","The Atlantic coast","The Rif mountains","The Strait of Gibraltar"], answer: 0, fact: "Its towers are made of rammed earth, adobe, clay brick and wood, which needs constant maintenance and decays quickly once abandoned. Only a few families still live inside; most moved to a modern village across the river.", src: "https://en.wikipedia.org/wiki/A%C3%AFt_Benhaddou" },
  { cat: "Geography", sub: "Cities & Places", diff: 3, kids: true, q: "The ruined city of Nan Madol, beside Pohnpei in Micronesia, has a very unusual plan. What was it built on?", options: ["Artificial islets inside a shallow lagoon","A ring of cliffs above a crater lake","Wooden stilts driven into a river delta","One flat-topped hill above the coast"], answer: 0, fact: "Its name means within the intervals, a reference to the tidal canals that criss-cross it, and it is sometimes called the Venice of the Pacific. It was the capital of the Saudeleur dynasty until about 1628.", src: "https://en.wikipedia.org/wiki/Nan_Madol" },
  { cat: "Geography", sub: "Cities & Places", diff: 3, kids: true, q: "Chan Chan, capital of the Chimor kingdom on Peru's desert coast, was built almost entirely from which material?", options: ["Adobe brick","Cut granite","Fired red brick","Timber and thatch"], answer: 0, fact: "It spanned some 20 square kilometres and held an estimated 40,000 to 60,000 people, making it the largest city of the pre-Columbian era in South America. The heavy rains that come with El Niño now damage the base of its structures.", src: "https://en.wikipedia.org/wiki/Chan_Chan" },
  { cat: "Geography", sub: "Cities & Places", diff: 3, kids: true, q: "The vast underground city of Derinkuyu, in Cappadocia, was forgotten for centuries. How was it found again in 1963?", options: ["A man renovating his house broke through a wall","An earthquake opened a crack in a field","A shepherd's dog fell down a ventilation shaft","Aerial photographs showed oddly regular shadows"], answer: 0, fact: "It reaches about 85 metres down and was large enough to shelter as many as 20,000 people together with their livestock and food stores. Each floor could be sealed off separately with a large rolling stone door.", src: "https://en.wikipedia.org/wiki/Derinkuyu_underground_city" },
  { cat: "Geography", sub: "Cities & Places", diff: 3, kids: true, q: "Hulhumalé, the new island built beside the Maldivian capital, was made from what?", options: ["Sand pumped up from the sea floor","Rock quarried and shipped from Sri Lanka","Linked floating concrete pontoons","Silt dredged from an Indian river"], answer: 0, fact: "Reclamation has taken it to about 4 square kilometres, the fourth largest island in the Maldives, and it passed 50,000 residents by the end of 2019. It was inaugurated in 2004, partly as a response to rising sea levels.", src: "https://en.wikipedia.org/wiki/Hulhumal%C3%A9" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "The largest known meteorite still in one piece lies in the field in Namibia where a farmer's plough struck it in 1920. Why has it never been moved?", options: ["It crumbles as soon as it is touched","The law forbids it from being dug up","It is far too heavy to move","It is still too hot to approach"], answer: 2, fact: "The Hoba is roughly 84% iron and 16% nickel and weighs more than 60 tonnes — the most massive naturally occurring lump of iron known at Earth's surface, about twice the mass of the biggest Cape York fragment.", src: "https://en.wikipedia.org/wiki/Hoba_meteorite" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: true, q: "Ol Doinyo Lengai in Tanzania erupts a lava that no other active volcano on Earth produces. What is strange about it?", options: ["It glows bright green as it flows","It is so cool it looks like black mud by day","It floats on water without sinking","It hardens within seconds of leaving the vent"], answer: 1, fact: "The flows leave the vent at only 540 to 593 °C and turn white as snow within hours or days. The Maasai name for the mountain means the Mountain of God.", src: "https://en.wikipedia.org/wiki/Ol_Doinyo_Lengai" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: true, q: "The Deccan Traps of west-central India are vast stacked layers of ancient lava. The word 'trap' here comes from a Swedish word meaning what?", options: ["A snare or trap","Stairs","Black rock","Flood"], answer: 1, fact: "The flows still cover some 500,000 square kilometres and may once have spread over 1.5 million. They were laid down over 600,000 to 800,000 years, ending around 65.6 million years ago.", src: "https://en.wikipedia.org/wiki/Deccan_Traps" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "One named sea on Earth has no coastline at all — its edges are ocean currents. Which is it?", options: ["The Coral Sea","The Andaman Sea","The Sargasso Sea","The Sea of Okhotsk"], answer: 2, fact: "European eels cross the Atlantic to breed there, something Danish research voyages worked out in the early 1920s. The sea is named after the brown sargassum weed drifting on its calm blue surface.", src: "https://en.wikipedia.org/wiki/Sargasso_Sea" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "From late November to March a dry, dust-laden wind blows off the Sahara across West Africa towards the Gulf of Guinea. What is it called?", options: ["The Harmattan","The Sirocco","The Khamsin","The Levanter"], answer: 0, fact: "It is nicknamed the doctor wind, because its dryness feels bracing after months of heavy tropical humidity. Its dust can blot out the sun for days and forces airlines to cancel and divert flights.", src: "https://en.wikipedia.org/wiki/Harmattan" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: true, q: "In 2019 Japan's Hayabusa2 fired a 2.5-kilogram copper slug into the asteroid Ryugu. Why?", options: ["To slow the asteroid's spin before landing","To open a crater and sample rock unweathered by space","To test a way of deflecting future asteroids","To shake dust loose for its cameras"], answer: 1, fact: "The return capsule parachuted into the Australian outback at Woomera in December 2020 carrying 5.4 grams of Ryugu, far more than the mission had aimed for.", src: "https://en.wikipedia.org/wiki/Hayabusa2" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "When India's Mars Orbiter Mission slipped into orbit around Mars in September 2014, what did it achieve?", options: ["The first Asian mission to reach Mars orbit","The first landing on the surface of Mars","The first craft to orbit two planets","The first mission to return Martian soil"], answer: 0, fact: "It cost about 73 million US dollars, the least expensive Mars mission flown, and although it was designed to last six months it kept working for more than seven years.", src: "https://en.wikipedia.org/wiki/Mars_Orbiter_Mission" },
  { cat: "Science", sub: "Earth & Space", diff: 2, kids: true, q: "Astronomers have watched Jupiter's Great Red Spot closely since the 1800s. What has been happening to it?", options: ["It has been drifting towards the poles","It has been shrinking","It has split into two spots","It has been fading slowly to white"], answer: 1, fact: "The storm is about 1.3 times the width of Earth today, against roughly three times a century ago, and its winds reach some 496 kilometres per hour. At this rate it will be circular by about 2040.", src: "https://en.wikipedia.org/wiki/Great_Red_Spot" },
  { cat: "Science", sub: "Earth & Space", diff: 3, kids: true, q: "Between late 2019 and early 2020 the red supergiant Betelgeuse, in Orion, saw its brightness fall by a factor of about three. What was behind it?", options: ["A planet passing in front of the star","A companion star eclipsing it","A cloud of dust the star had thrown off","The start of its collapse into a black hole"], answer: 2, fact: "Betelgeuse is expected to end as a supernova, most likely within the next 100,000 years. When it does, it should shine as brightly as a half Moon for more than three months.", src: "https://en.wikipedia.org/wiki/Betelgeuse" },
  { cat: "Science", sub: "Physics", diff: 3, kids: true, q: "In the desert city of Yazd in Iran, tall towers with openings near the top rise from the rooftops. They cool the house below even on a night with no wind at all. How?", options: ["Warm air inside rises up the tower and escapes, pulling cooler air in behind it","The tower's shadow keeps the roof beneath it from heating up during the day","Cold air sinks down the tower because the top of the tower is colder","The thick mud walls of the tower slowly release the cool they stored overnight"], answer: 0, fact: "A windcatcher can hold a house 8 to 12 °C cooler than the air outside. Some are joined to a qanat, an underground water channel, so the air arriving in the room has already been chilled by evaporation.", src: "https://en.wikipedia.org/wiki/Windcatcher" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "A small clay pot sits inside a bigger one, the gap between them packed with wet sand and a damp cloth laid over the top. Food inside keeps for days with no electricity. What does the cooling?", options: ["Water evaporating from the outer pot carries heat away with it","The clay blocks the sun's heat from reaching the inner pot","The sand conducts heat poorly, so heat cannot pass through it","The damp cloth reflects warm air back away from the pots"], answer: 0, fact: "The design was spread across northern Nigeria in the 1990s by Mohammed Bah Abba, a potter who made 5,000 of them. He won the 2001 Rolex Award for Enterprise and put the $75,000 into getting them to more villages; a unit cost about a dollar.", src: "https://en.wikipedia.org/wiki/Pot-in-pot_refrigerator" },
  { cat: "Science", sub: "Physics", diff: 3, kids: true, q: "Magnetite is a common iron mineral, but almost none of it is magnetic. The rare pieces that are — lodestones — long puzzled geologists. What is now thought to have magnetised them?", options: ["A strike of lightning passing through the rock","Slow cooling deep inside the Earth's crust","The Earth's own field acting over millions of years","Friction as the rock was ground along a fault"], answer: 0, fact: "Pure magnetite cannot hold a magnetic field at all. Lodestones are magnetite laced with maghemite and traces of titanium, aluminium and manganese — the impurities are exactly what lets them keep it.", src: "https://en.wikipedia.org/wiki/Lodestone" },
  { cat: "Science", sub: "Physics", diff: 3, kids: true, q: "At the mouth of the Catatumbo River, where it meets Lake Maracaibo in Venezuela, lightning flashes 16 to 40 times a minute on 140 to 160 nights a year. Why there, and why so relentlessly?", options: ["Warm damp air off the lake is forced upward when it meets the mountain ridges around it","Iron-rich rock under the lake bed pulls charge down out of the clouds","The lake water is unusually salty, and salt spray carries charge upward","The river carries so much silt that the water surface itself becomes charged"], answer: 0, fact: "It has been known for centuries as the Lighthouse of Maracaibo, because it is visible for miles around the lake. NASA satellite data put the area at roughly 250 lightning flashes per square kilometre a year — the highest density anywhere on Earth.", src: "https://en.wikipedia.org/wiki/Catatumbo_lightning" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "At the dunes of Mingsha Shan near Dunhuang in China, and on dunes in Kazakhstan and the Namib, the sand gives out a low boom that can reach 105 decibels. What is making the sound?", options: ["Grains avalanching down the face of the dune and sliding over one another","Wind funnelling through cracks in the rock beneath the dune","Air trapped under the dune escaping as the sand shifts","The dune's dried crust splitting apart as it cools at dusk"], answer: 0, fact: "The note sits close to 450 hertz and can carry on for several minutes. It only happens if the grains are round, between 0.1 and 0.5 millimetres across, contain silica, and the humidity is right — miss any one and the dune stays silent.", src: "https://en.wikipedia.org/wiki/Singing_sand" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "The pigment in a peacock's tail feathers is brown. Yet the tail looks blue, turquoise and green. Where does that colour come from?", options: ["Microscopic structures in the feather that interfere with light waves","A second pigment that only shows itself in bright sunlight","Tiny droplets of oil the bird spreads over its feathers","The feathers absorbing ultraviolet light and re-emitting it as colour"], answer: 0, fact: "The same trick colours the wings of Morpho butterflies and the inside of a shell. Because the colour comes from geometry rather than chemistry, it shifts as you move — tilt the feather and the hue slides.", src: "https://en.wikipedia.org/wiki/Structural_coloration" },
  { cat: "Science", sub: "Physics", diff: 2, kids: true, q: "A steel ball weighing 660 tonnes hangs between the 87th and 92nd floors of Taipei 101, in full view of visitors. What is it doing there?", options: ["Swinging against the building's own sway, so the tower moves less in wind","Acting as a counterweight for the tower's high-speed lifts","Anchoring the lightning conductors that run down the tower","Keeping the load on the foundations even as the building settles"], answer: 0, fact: "London's Millennium Bridge had the same treatment added after it swayed under the tread of pedestrians, and Sydney Tower uses a tank of water instead of a steel ball.", src: "https://en.wikipedia.org/wiki/Tuned_mass_damper" },
  { cat: "Science", sub: "Physics", diff: 3, kids: true, q: "In films, people disappear beneath quicksand. In reality, how far can a person sink into it?", options: ["To about waist height, and then no further","Completely under, within a minute or two","Up to the chest, and deeper still if they stay motionless","Only to the ankles, unless the layer is very deep"], answer: 0, fact: "Quicksand is about twice as dense as a human body, so you float in it. The real trouble is getting out: pulling a foot free at one centimetre a second takes roughly the force needed to lift a car.", src: "https://en.wikipedia.org/wiki/Quicksand" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "Cloth lifted out of an indigo vat only turns blue once it meets the open air. Why?", options: ["Oxygen in the air restores the blue form","The water evaporates and concentrates the dye","Sunlight triggers the colour","The dye cools and crystallises"], answer: 0, fact: "Indigo will not dissolve in water at all, so dyers must first chemically reduce it to a soluble, pale yellow form known as white indigo. Across much of West Africa women did the dyeing, with the Yoruba of Nigeria and the Mandinka of Mali especially renowned for it.", src: "https://en.wikipedia.org/wiki/Indigo_dye" },
  { cat: "Science", sub: "Chemistry", diff: 1, kids: true, q: "A fresh henna stain comes off orange, then deepens to reddish brown over about three days. What causes that darkening?", options: ["Oxidation of the dye","The paste sinking into deeper skin","The outer skin layer renewing itself","Sunlight bleaching the pattern"], answer: 0, fact: "The colouring molecule, lawsone, is locked inside the whole leaf. Once the leaves are crushed into a paste it gradually migrates out into the outer layer of the skin and binds to the proteins there.", src: "https://en.wikipedia.org/wiki/Henna" },
  { cat: "Science", sub: "Chemistry", diff: 3, kids: true, q: "Egyptian blue has an unusual property that lets researchers spot traces of it invisible to the eye on ancient statues. What does it do?", options: ["It glows in infrared light","It is attracted by a magnet","It fizzes on contact with vinegar","It smells of sulfur when warmed"], answer: 0, fact: "The pigment is a calcium copper silicate, CaCuSi4O10, and is considered the first synthetic pigment. Egyptians were using it by around 3250 BC, and its manufacture died out in the fourth century AD.", src: "https://en.wikipedia.org/wiki/Egyptian_blue" },
  { cat: "Science", sub: "Chemistry", diff: 2, kids: true, q: "The earthy smell of rain landing on dry ground, called petrichor, owes much of its punch to geosmin. What makes geosmin?", options: ["Soil bacteria","Plant roots","Lightning","Clay minerals"], answer: 0, fact: "The human nose picks up geosmin at concentrations as low as 0.4 parts per billion. The word petrichor was coined in 1964 by two Australian scientists, Isabel Joy Bear and Richard Grenfell Thomas, writing in the journal Nature.", src: "https://en.wikipedia.org/wiki/Petrichor" },
];
